L5R4E.efeitosEquip={"blowgun_special_rule": "Triplica o bônus de armadura no TN do alvo. A perícia Ninjutsu aumenta o dano para 1k1 no rank 3 e 2k1 no rank 7. Recarregar é Ação Livre.", "daikyu_rule": "+10 no TN de todos os ataques se usado a pé.", "dbl_opp_armor_rule": "Dobra o bônus de armadura no TN do alvo.", "may_break_25w_rule": "Quebra se causar mais de 25 Ferimentos num só ataque.", "may_break_30w_rule": "Quebra se causar mais de 30 Ferimentos num só ataque.", "throw_20f_rule": "Pode ser arremessada com precisão até 6 m (20 pés).", "throw_25f_rule": "Pode ser arremessada com precisão até 7,5 m (25 pés).", "throw_50f_rule": "Pode ser arremessada com precisão até 15 m (50 pés).", "lance_special_rule": "O DR indicado só vale a cavalo, num ataque logo depois de uma Ação de Movimento; fora disso, DR 1k2. Em corpo a corpo sem Movimento, +5 no TN a cavalo e +10 a pé. Quebra se causar mais de 30 Ferimentos num só ataque.", "yari_special_rule": "Pode ser arremessada até 9 m (30 pés), com DR 1k2 quando arremessada.", "tsubute_special_rule": "Arremessada até 9 m (30 pés). Não soma a Força ao DR à distância e os dados de dano não explodem.", "shuriken_special_rule": "Arremessada até 7,5 m (25 pés). Não soma a Força ao DR à distância e os dados de dano não explodem.", "void_rise_dr_rule": "Pode gastar 1 Ponto de Vazio para somar +1k1 ao dano (normalmente o Vazio não aumenta dano). Só 1 Ponto por vez.", "ninjato_special_rule": "Arma média, mas conta como pequena para esconder. Quebra se causar mais de 40 Ferimentos num só ataque.", "keep_grapple_rule": "Pode iniciar e manter um agarrão.", "no_shoot_horseback_rule": "+10 no TN de todos os ataques se usado a cavalo.", "light_armor_rule": "+5 no TN das rolagens de Atletismo e Furtividade.", "heavy_armor_rule": "+5 no TN de todas as rolagens de perícia com Agilidade ou Reflexos.", "riding_armor_rule": "+12 no TN de Armadura a cavalo (em vez de +4). Conta como armadura pesada; a pé, +5 no TN das rolagens de Agilidade e Reflexos.", "ignore_armor_rule": "Ignora o bônus de armadura no TN do alvo.", "flesh_cutter_rule": "Dobra o bônus de armadura no TN do alvo; metade do alcance.", "humming_bulb_rule": "Faz um assobio alto (sinal).", "rope_cutter_rule": "2 Raises grátis em Golpes Mirados contra objetos; metade do alcance."};
