L5R4E.ancestrais=[{"id": "ancestor_crab_hida", "nome": "Ancestor, Hida", "tipo": "ancestral", "custo": 14, "cla4e": "crab", "pagina": "242", "descricao": "Hida was a warrior of unmatched strength and endurance, who relied on that to defeat all foes, never backing down from any of them, even his own Taint-corrupted son. With Hida watching over you, your blows strike hard and true – you gain +1k0 to all damage rolls and may ignore 4 points of an enemy’s Reduction, regardless of what weapon you are using. Further, any Crab who fight alongside you in a skirmish are inspired by the spirit of Hida which infuses your frame, and gain +1 bonus Void point (if they do not use this Void point by the end of the skirmish, it is lost). Demands: Any Round that at least one fellow Crab is wounded within your sight, you must suffer 1 Wound in sympathy. (This does not increase if multiple Crab are wounded in the same Round.) This Wound ignores Reduction and any other effects which would otherwise negate damage. However, you can voluntarily choose not to suffer the Wound. If you ever refuse to suffer these Wounds, or if you ever voluntarily retreat from a fight with a creature of the Shadowlands, Hida will abandon you."}, {"id": "ancestor_crab_kuni", "nome": "Ancestor, Kuni", "tipo": "ancestral", "custo": 8, "cla4e": "crab", "pagina": "242", "descricao": "The founder of the Crab shugenja school was a capable shugenja and a man who knew more about the creatures of the Shadowlands than any other. Once per session, you may spend a Void point to gain a bonus to your spellcasting roll equal to your Earth Rank in kept dice. Also, when rolling to resist gaining the Shadowlands Taint, you may roll twice and keep the better result. Demands: Kuni’s demand to his descendents is a simple one – stay pure. If you ever gain so much as a single point of the Shadowlands Taint, Kuni will abandon you."}, {"id": "ancestor_crane_doji", "nome": "Ancestor, Doji", "tipo": "ancestral", "custo": 8, "cla4e": "crane", "pagina": "242", "descricao": "The Lady Doji created most of the rules and concepts of Rokugani civilization, and her influence is still felt throughout the Empire’s courts in the present day. Those who receive Doji’s advice gain a +1k0 bonus to all of their Courtier, Etiquette, Perform, and Sincerity rolls. Demands: Doji requires those who have her guidance to live in a manner both honorable and civilized. If you ever commit a Major Breach of Etiquette (as per the Honor table in the Book of Earth), or you ever lose more than 3 points of Honor or Glory from a single breach of etiquette, Doji will abandon you."}, {"id": "ancestor_crane_kakita", "nome": "Ancestor, Kakita", "tipo": "ancestral", "custo": 12, "cla4e": "crane", "pagina": "242", "descricao": "Doji’s husband was both a duelist and an artisan of renown, author of The Sword, and served as the first Emerald Champion in Rokugan’s history. However, he also started the Crane Clan’s long and bitter feud with the Lion Clan. Those who have Kakita’s guidance may spend a Void point to re-roll any Iaijutsu or Artisan Skill roll with a +1k1 bonus to the second roll. They keep the better result. However, all those who are watched over by Kakita earn the automatic enmity of Matsu samurai, who sense their own ancestor’s anger – all members of the Matsu family are effectively Sworn Enemies to you. Demands: Kakita was an honorable man who sought perfection in both the sword and with the artist’s brush, and he expects the same of you. If you ever lose a duel or an artistic competition, Kakita forsakes you. He also abandons you if your Honor ever drops below 4.0."}, {"id": "ancestor_dragon_agasha_kitsuki", "nome": "Ancestor, Agasha Kitsuki", "tipo": "ancestral", "custo": 11, "cla4e": "dragon", "pagina": "242", "descricao": "The founder of the Kitsuki family originated the concept of the controversial “Kitsuki Method,” which uses logical deduction and inference to solve crimes. Those who have his guidance gain the ability to “read” others and to pick up on subtle, hidden clues in an uncanny, almost supernatural manner that many samurai fine disturbing. When you have Kitsuki’s guidance, you may use your Perception Trait for any Skill or Trait roll that would normally require you to use your Awareness Trait. Furthermore, if you spend a Void point on any Skill or Trait roll to tell whether someone is lying to you, you gain +2k2 instead of the normal +1k1. Demands: Kitsuki requires you to always pursue the truth. If you ever accept a solution to a problem, crime, or puzzle that you know or sincerely believe to be false, Kitsuki will abandon you."}, {"id": "ancestor_dragon_mirumoto", "nome": "Ancestor, Mirumoto", "tipo": "ancestral", "custo": 9, "cla4e": "dragon", "pagina": "242", "descricao": "The founder of the Dragon Clan’s warrior family was one of the greatest swordsmen of his age, a pragmatic and cunning warrior and brilliant duelist, and a deep rival to Kakita in the pursuit of swordsmanship. He created the Niten style, a method of fighting with both the katana and wakizashi. He also wrote one of the Empire’s greatest works on swordsmanship, and died fighting Fu Leng on the first Day of Thunder. If you have gained Mirumoto’s attention, he grants you +1k1 to all Agility-based Skill rolls. If the Skill roll is made using a Mirumoto Bushi School Skill, the bonus is +3k1 instead. Demands: Mirumoto expects his descendents to follow his tradition of victory, and to carry on his rivalry with his ancient nemesis Kakita. If you ever issue a challenge and then lose the subsequent duel, Mirumoto will abandon you. He will also leave you if you ever refuse a duel with someone trained in the Kakita Bushi school. He will not abandon you if you lose a duel that was forced on you… unless that duel was against a Kakita."}, {"id": "ancestor_lion_akodo", "nome": "Ancestor, Akodo", "tipo": "ancestral", "custo": 12, "cla4e": "lion", "pagina": "242", "descricao": "The founder of the Lion Clan was a general beyond compare, one of the greatest tacticians ever to walk the face of the Empire. He was also a supreme soldier, a man who gained strength not just from his own ability but also from the support of all those around him. He forged the Lion into a clan where every soldier was part of a greater whole, made strong by their brothers in arms. While you have Akodo’s guidance, you gain a +1k0 bonus to all Bugei skill rolls (except Iaijutsu rolls) and a +1k1 bonus to any rolls made on the Mass Battle Table. Further, whenever you fight alongside your fellow Lion, you draw strength from their presence, just as Akodo taught. Any time you enter a skirmish with at least one other Lion bushi fighting alongside you, you gain +1 extra Void point (this bonus Void must be spent by the end of the skirmish, or it is lost). Demands: Akodo requires all his followers to be soldiers of both steadfast courage and unimpeachable honor. If your Honor ever drops below 5.0, Akodo will abandon you. He will also abandon you if you ever voluntarily leave a battle or skirmish where other Lion are still fighting."}, {"id": "ancestor_lion_ikoma", "nome": "Ancestor, Ikoma", "tipo": "ancestral", "custo": 9, "cla4e": "lion", "pagina": "243", "descricao": "The founder of the Lion Clan’s family of storytellers and historians was a capable spinner of tales himself, but he was also a cheerful rogue who chased women and brawled without hesitation or fear. Those who are watched over by Ikoma’s boisterous spirit are expected to emulate him in all ways. In return, he infuses them with both his toughness and his rough-and-ready wisdom. You gain +1k0 to all rolls you make with the Intelligence Trait, and +2k0 to your damage when fighting unarmed (with the Jiujutsu skill). Demands: Ikoma expects you to live as he did – drink hard, fight hard, tell fine tales, and welcome the company of beautiful and interesting women. If you ever choose to refuse a drink, run from a fight, or insult an attractive or compelling woman, Ikoma will forsake you."}, {"id": "ancestor_mantis_kaimetsu_uo", "nome": "Ancestor, Kaimetsu-Uo", "tipo": "ancestral", "custo": 9, "cla4e": "mantis", "pagina": "243", "descricao": "The original founder of the Mantis Clan was the son of Hida Osano-Wo and his Matsu bride, and one of the most formidable warriors of his day. Preferring action to words, he carved a clan’s founding out of a dangerous tropical island, and stormed Kyuden Isawa to avenge his father’s death. Those who gain Kaimetsu-Uo’s favor are expected to live as he did, carving their way through life with action and sheer determination, using whatever weapon comes to hand, and countenancing no insult from anyone. You gain a +1k1 bonus to all Willpower Trait and Skill rolls except those made to avoid being provoked. You gain a +3k0 bonus when using the Improvised Weapon emphasis of the Jiujutsu skill, and also gain +1k1 damage to all damage rolls made with improvised weapons. Demands: Kaimetsu-Uo requires you to take on all challenges, no matter how strange or embarrassing. If you ever back down from a physical competition or challenge, even a trivial one such as a foot race, he will forsake you."}, {"id": "ancestor_mantis_gusai", "nome": "Ancestor, Gusai", "tipo": "ancestral", "custo": 5, "cla4e": "mantis", "pagina": "243", "descricao": "One of the most notorious of Mantis ancestors, Gusai proved the power of a single individual by successfully carrying a knife into the presence of the Emperor – only to see the Emperor prove the limitations of such power when he signed the order for Gusai’s execution. When Gusai guides you, you gain +3k3 to any Stealth or Sleight-of-Hand roll made to conceal a weapon on your person. Demands: Gusai will abandon you if you ever voluntarily go unarmed into the presence of a rival or enemy."}, {"id": "ancestor_phoenix_asako", "nome": "Ancestor, Asako", "tipo": "ancestral", "custo": 5, "cla4e": "phoenix", "pagina": "243", "descricao": "Shiba’s favored follower, Asako, learned the secrets of humanity’s limitless potential from her lord, and founded the mystic order known as the henshin. She treasured friendship above all things, but for this very reason felt the pain of betrayal more deeply and keenly than any other. While Asako guides your steps, others find you a charming ally and a true friend. Any of your Ally Advantages gain a free +1 increase to their level of Devotion, and you gain +1k0 to all Social Skill rolls made against someone with whom you are an Ally. However, if an Ally ever betrays you, you automatically gain Driven: Destroy the Betrayer for no points. Demands: Asako requires you to treat your friends with the same devotion you expect of them. If you ever betray or abandon a friend, Asako will forsake you."}, {"id": "ancestor_phoenix_shiba", "nome": "Ancestor, Shiba", "tipo": "ancestral", "custo": 9, "cla4e": "phoenix", "pagina": "243", "descricao": "Known for his wisdom, perception, and foresight, Shiba served the Isawa faithfully in life, and wrote down the Tao, which became the foundation of the Empire’s religion. When he perished in the Shadowlands, he found a way to pass on his knowledge to his descendents, ensuring the Phoenix would always be well-led by the Soul of Shiba. However, he also sometimes chooses individual Phoenix samurai to benefit from his guidance. Those who are watched over by Shiba gain +1k1 to all Intelligence Rolls and Intelligence-based Skill Rolls, and may add their Intelligence Rank to their Armor TN at all times. If you enter a skirmish alongside a member of the Isawa family, you gain +1 Void point (this Void point must be used by the end of the skirmish or it is lost). Demands: Shiba requires that you maintain both a high honor and an absolute, unswerving dedication to fulfilling his oath to the Isawa. If your Honor Rank ever drops below 4.0, he will abandon you. He will also abandon you if you ever willingly disobey a higher-ranking Isawa, or if you ever voluntarily leave a skirmish while an Isawa ally remains behind."}, {"id": "ancestor_scorpion_bayushi", "nome": "Ancestor, Bayushi", "tipo": "ancestral", "custo": 12, "cla4e": "scorpion", "pagina": "243", "descricao": "The founder of the Scorpion Clan was known for his subtle cunning and trickery, as well as a sort of cruel honesty that he employed most famously at his brother Hantei’s deathbed. Although his skills and ruthlessness in both battle and politics were legendary, he also carried a life-long devotion to his follower Shosuro, and her corruption by the Lying Darkness led him to his own death. If you are trained in one of the Bayushi schools (such as the Bayushi Bushi or Bayushi Courtier schools, for example), you gain a +1k0 bonus to all your School Skills, and any time you spend a Void point on a School Skill, you gain +2k2 instead of +1k1. If you have a Kharmic Tie with another character, both of you may use each others’ Void Points, but if one of you dies, the other immediately gains the Momoku Disadvantage for no points. Demands: Bayushi made only one demand of his followers – loyalty. He expects the same of you. If you ever voluntarily and knowingly betray the Scorpion Clan, he will abandon you. He will also abandon you if your Honor ever climbs to 5.0 or better – such pure souls have no place in the ranks of Rokugan’s designated villains."}, {"id": "ancestor_scorpion_shoshuro", "nome": "Ancestor, Shoshuro", "tipo": "ancestral", "custo": 8, "cla4e": "scorpion", "pagina": "244", "descricao": "Bayushi’s most beloved follower was consumed by the Lying Darkness, and spent centuries imprisoned by the kami Togashi before finally escaping during the Hidden Emperor era. At the end of that era, Bayushi carried her soul into Yomi, and since that time she has begun to show her favor to those of her descendents she finds worthy. If Shosuro’s whispers guide your actions, you gain a +3k1 bonus to all Stealth, Acting, and Sincerity (Deceit) skill rolls. Demands: Having been forced to betray her lord Bayushi once, Shosuro is determined that her descendents will never make the same mistake. If you ever betray the Scorpion Clan, disobey your superiors in the clan, or become corrupted by the Lying Darkness or the Shadow Dragon, Shosuro will immediately abandon you."}, {"id": "ancestor_spider_hida_atarasi", "nome": "Ancestor, Hida Atarasi", "tipo": "ancestral", "custo": 7, "cla4e": "spider", "pagina": "244", "descricao": "The first son of Hida, and the original Crab Thunder, also became one of the first samurai to be Lost to the Shadowlands Taint. So great was his power that those who encountered him (and were fortunate enough to survive) called him an akutenshi, or “evil angel.” Atarasi’s own father Hida eventually hunted him down and destroyed him in single combat. Atarasi’s twisted warrior spirit infuses those he guides, allowing them to call on their corruption to deliver terrible blows to their enemies. While Atarasi watches over you, during each round of a skirmish you may choose to spend a Void Point or gain a point of Shadowlands Taint (your choice) in order to add either your Taint Rank or your Earth in unkept dice to your attack and damage rolls for that round. Demands: Atarasi is a fallen soul, and he reviles purity and virtue. If your Honor Rank ever reaches 3.0 or higher, or you ever lose any of your Taint, Atarasi forsakes you."}, {"id": "ancestor_spider_kuni_yori", "nome": "Ancestor, Kuni Yori", "tipo": "ancestral", "custo": 5, "cla4e": "spider", "pagina": "244", "descricao": "Kuni Yori was once a loyal Crab, a servant of his lord Hida Kisada, but he was seduced by the Shadowlands and betrayed the Crab Clan. Transformed by the power of maho, Yori became an undead abomination, leading the forces of the Shadowlands against his former clan. Yori’s guidance teaches both deceit and greater mastery of the forces of maho. You gain +1k0 to all Sincerity (Deceit) rolls and all maho spellcasting rolls. However, Yori’s malign influence draws the Taint to you even faster than otherwise. Any time you cast a Maho spell, you gain 1 extra point of Taint. Demands: Yori makes no demands – he is confident that his guidance will inevitably lead to complete corruption by the Taint."}, {"id": "ancestor_unicorn_moto", "nome": "Ancestor, Moto", "tipo": "ancestral", "custo": 10, "cla4e": "unicorn", "pagina": "244", "descricao": "A formidable desert warrior who swore allegiance to Shinjo and brought his tribe into the Ki-Rin Clan, Moto was known for his incredible speed and refusal to be bound by anything but his own choice. He imbues the same spirit and determination in those of his descendents who win his favor. Any time you roll to resist an attempt to physically restrain you (such as a Grappling attack) or to mentally influence you (such as a Temptation Skill roll), you gain a +2k2 bonus to the roll. Likewise, any spell which would restrain your physical movement has its Spellcasting TN increased by an amount equal to 5 x your Willpower. Demands: Moto expects you to live by the same standard of freedom as he did, offering obedience only to your lord and clan. If you ever knowingly and voluntarily allow yourself to be controlled by another who is not your rightful superior in the Unicorn Clan (such as letting yourself be blackmailed by a courtier), Moto will abandon you."}, {"id": "ancestor_unicorn_shinjo", "nome": "Ancestor, Shinjo", "tipo": "ancestral", "custo": 8, "cla4e": "unicorn", "pagina": "244", "descricao": "The founder of the Unicorn was known for her boundless curiosity about the world, which caused her to lead her Ki-Rin Clan out into the Burning Sands, and for her deep compassion, which allowed her to retain sympathy even for her fallen brother Fu Leng. After her long imprisonment and sleep in the Burning Sands, she returned to Rokugan to purge the Kolat from her beloved clan. You gain a +1k1 bonus to any Investigation roll made to understand something new, strange, or enigmatic, as Shinjo’s spirit guides you to seek deeper understanding of the world around you. You also gain +1k1 to all Awareness rolls made with the Etiquette or Sincerity (Honesty) skills, as Shinjo’s compassion infuses you with empathy and grace. Demands: Shinjo requires you to always act with compassion, even when facing bitter enemies. If you ever fail to show mercy and compassion to a rival or enemy, Shinjo will abandon you. (This does not apply to members of the Kolat or minions of the Lying Darkness or the Shadow Dragon.)"}];

/* 2026-11-05: conteúdo dos suplementos da 4ª ed. (data packs do L5RCM, OpenNingia, LGPL3). Cada item
   traz o livro de origem em 'livro'; o resto do arquivo é do Livro Básico. Burning Sands e o
   pacote da comunidade ficaram de fora. */
L5R4E.suplementos={"escolas": [{"id": "order_of_the_wind", "clanId": "monks", "nome": "Order of the Wind", "traco": "reflexes", "honra": "4.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "staves", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "essence_of_the_wind", "nome": "Essence of the Wind", "rank": 1, "descricao": "A true Brother of the Wind allows the world to move around him like a breeze, remaining centered and assured throughout the chaos of existence. Any effect that targets you and attempts to influence your behavior, whether it be a spell, a courtier Technique, a social Skill or Advantage, or any other mechanic, requires an additional Void Point to take effect. (However, this can bypass the normal limit on spending one Void Point per Round for enhancement effects.)"}], "livro": "Book of Air (Livro do Ar)"}, {"id": "winds_grace_order", "clanId": "monks", "nome": "Wind's Grace Order", "traco": "reflexes", "honra": "6.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": "Shintao"}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "pillars_of_the_minds_eye", "nome": "Pillars of the Mind's Eye", "rank": 1, "descricao": "By clearing the mind and embracing absolute serenity and focus, a brother of the Wind's Grace can grasp the simple truth: the arrow and the target are already one. You make an archery attack as a Complex Action; for every Kiho you have that is presently active, you gain a bonus of +1k0 to the total of that roll. Active Kiho may not have any other effects during a Round in which you employ this Technique, and only one Martial Kiho can confer this benefit. However, any time you use this Technique to make an attack that directly results in the death of an intelligent being, you lose 3 points of Honor."}], "livro": "Book of Air (Livro do Ar)"}, {"id": "fukurokujins_eyes", "clanId": "monks", "nome": "Fukurokujin's Eyes", "traco": "perception", "honra": "4.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "divination", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "investigation", "rank": 1, "enfase": ""}, {"id": "lore_history", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": "Shintao"}], "tecnicas": [{"id": "way_of_the_closed_eye", "nome": "Way of the Closed Eye", "rank": 1, "descricao": "By observing and anticipating, monks of Fukurokujin's Eyes can accurately predict the actions of others and take advantage of this foreknowledge in a variety of ways. You may not be surprised by ambushes. Further, at the start of a skirmish prior to rolling Initiative, you may spend a Void Point and make a Perception Trait Roll at TN 20. If the roll succeeds, you may increase your subsequent Initiative Score by 20. However, this bonus is lost instantly if you make an attack of any kind."}], "livro": "Book of Air (Livro do Ar)"}, {"id": "order_of_the_nameless_gift", "clanId": "monks", "nome": "Order of the Nameless Gift", "traco": "stamina", "honra": "4.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "shinseis_gift", "nome": "Shinsei's Gift", "rank": 1, "descricao": "A monk taught by the Order of the Nameless Gift can be an endless well of endurance, patience, and insight. Because they are much more worldly than many other monks in the Brotherhood, their training and experience add to a typical monk’s canny mind and strength in combat. You gain a number of Void Points per day equal to your Earth Ring, but these Void Points may only be spent to reduce damage or to raise your Armor TN. These Void Points may not be spent simultaneously with other Void Points or in any other fashion."}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "temple_of_persistence", "clanId": "monks", "nome": "Temple of Persistence", "traco": "stamina", "honra": "3.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": "martial_arts"}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "unyielding_spirit", "nome": "Unyielding Spirit", "rank": 1, "descricao": "Members of the Order of Persistence are known to be stubborn in both body and soul. They do not simply endure the wrathful assaults of others, but learn to push forward actively toward their goal. You may spend a Void Point as a Free Action to ignore all penalties to an immediately subsequent die roll. If you use this Technique when making either a Contested Roll you did not initiate or an Attack Roll, you may also add +Xk0 to the roll, where X is your Earth Ring."}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "monks_order_of_rebirth", "clanId": "monks", "nome": "Order of Rebirth", "traco": "intelligence", "honra": "6.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "lore_history", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "monks_changing_the_way", "nome": "Changing the Way", "rank": 1, "descricao": "The Brothers of Rebirth celebrate different approaches in all the myriad of forms. Each time in a given encounter that you attempt to utilize a Kiho of a different Element that any Kiho previously used in the same encounter, you gain a bonus of +5 on the activation roll."}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "monks_tengokus_fist", "clanId": "monks", "nome": "Tengoku's Fist", "traco": "agility", "honra": "4.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 2, "enfase": ""}, {"id": "battle", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "monks_the_hand_of_the_heavens", "nome": "The Hand of the Heavens", "rank": 1, "descricao": "The monks of Tengoku's Fist strike with surety and purpose, and their strength is magnified by the influence of the divine. When making an unarmed attack against an opponent, or an attack using a bisento, a bo staff, or a weapon with the Monk property, you may gain a Free Raise on the attack roll if your Fire Ring is higher than your opponent's Fire Ring."}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "monks_the_temple_of_heavenly_wisdom", "clanId": "monks", "nome": "The Temple of Heavenly Wisdom", "traco": "intelligence", "honra": "6.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "courtier", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": ""}, {"id": "lore_history", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": "Shintao"}], "tecnicas": [{"id": "monks_the_largesse_of_fukurokujin", "nome": "The Largesse of Fukurokujin", "rank": 1, "descricao": "The Fortune of Wisdom showers his blessings upon those monks who revere him, granting them insight into the way of politics and diplomacy where others might make grievous errors. When making any Social Skill Roll, you may select any one Kiho you possess. You may not use that Kiho for the remainder of the day, but you gain a bonus of +1k1 to the Social Skill Roll. You may only select each Kiho you know once per day for this purpose."}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "order_of_eternity", "clanId": "monks", "nome": "Order of Eternity", "traco": "intelligence", "honra": "4.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "defense", "rank": 1, "enfase": ""}, {"id": "divination", "rank": 1, "enfase": "astrology"}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "the_touch_of_eternity", "nome": "The Touch of Eternity", "rank": 1, "descricao": "The monks of this Order believe that time is an illusion and that the events of the past, present, and future are all coexistent. This causes them to engage in many strange actions, but also allows them an unusual degree of insight into the world around them. You may contemplate a noncombat situation, for an amount of time determined by the GM (the monks of this Order have been known to size up a complex situation in an instant, but also to spend an hour considering whether to eat a bowl of rice). At the end of your contemplation, you roll Meditation / Void at TN 25 (higher for complex situations). With a success, you gain a bonus of +1k1 +Void to any Skill Rolls you make to try to resolve that specific situation. The GM should exercise good judgment in considering the application of the Order of Eternity Technique – some situations may be too complex to master with a single consideration. In general, the monk should not be able to apply this Technique’s benefits to more Skill Rolls than his Void Rank – any rolls beyond that will require further contemplation and another Meditation / Void roll."}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "peasant_koga_ninja", "clanId": "peasant", "nome": "Koga Ninja", "traco": "", "honra": "", "tags": ["ninja", "peasant", "peasant_ninja"], "pericias": [{"id": "acting", "rank": 1, "enfase": ""}, {"id": "athletics", "rank": 1, "enfase": ""}, {"id": "chain_weapons", "rank": 1, "enfase": ""}, {"id": "craft_poison", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": "Tanto"}, {"id": "stealth", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "the_peoples_vengeance", "nome": "The People's Vengeance", "rank": 1, "descricao": "The Koga Ninja specialize in protecting and avengingthe common people by killing those samurai who abuse their station. You gain a +1k1 bonus to any Skill roll made against a member of the samurai caste."}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "ronin_void_mystic", "clanId": "ronin", "nome": "Void Mystic", "traco": "willpower", "honra": "3.5", "tags": ["ronin", "shugenja", "ronin_shugenja"], "pericias": [{"id": "defense", "rank": 1, "enfase": ""}, {"id": "divination", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "lore_elements", "rank": 1, "enfase": "Void"}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "ronin_the_voids_caress", "nome": "The Void's Caress", "rank": 1, "descricao": "Affinity/Deficiency: None. Instead, the Void Mystic begins play with both the Ishiken-do Advantage and the Touch of the Void Disadvantage. You cannot cast spells of the four non-Void Elements except for the basic spells of Sense, Commune, and Summon, and you cannot Importune for spells. The Void Mystic, born with a close attunement to the Void but lacking any conventional training, does not need to acquire spell-scrolls. You may cast any Void spell up to your current Mastery Level, expending a Spell Slot as normal. Mechanically, the spell is cast as normal, but you do not need to speak aloud to cast your spells. You may only cast each Spell once per day, and you may never cast Void spells above Rank 5. You also gain a Free Raise to the Divination Skill (a by-product of your attunement to the Void). Spells: As noted above, you may cast any Void Spell within your Mastery Level Option: If the GM feels the Void Mystic’s limited spell abilities are too confining, the Mystic may be granted one additional Spell Slot for each Insight Rank he attains."}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "monks_order_of_jurojins_blessing", "clanId": "monks", "nome": "Order of Jurojin's Blessing", "traco": "intelligence", "honra": "5.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "lore_anatomy", "rank": 1, "enfase": "disease"}, {"id": "medicine", "rank": 1, "enfase": "disease, herbalism"}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "staves", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "monks_blessings_of_longevity", "nome": "Blessings of Longevity", "rank": 1, "descricao": "You gain a +1k1 bonus to all Medicine rolls made for the purpose of treating disease or infection, and a +1k0 bonus to all Medicine rolls made for the purpose of treating Wounds. You may also attempt to treat natural (non- Taint-induced) insanity with a Medicine roll, although it is the GM’s option whether your treatment actually has any effect."}], "livro": "Book of Water (Livro da Água)"}, {"id": "monks_the_shrine_of_heavens_mirror", "clanId": "monks", "nome": "The Shrine of Heaven's Mirror", "traco": "perception", "honra": "3.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "divination", "rank": 1, "enfase": "Omens"}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "lore_omens", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "monks_gaze_into_the_mirror", "nome": "Gaze Into the Mirror", "rank": 1, "descricao": "The peculiar practices of Heaven’s Mirror monks grant them insights denied to other mortals. You gain a bonus of +1k0 to all Divination Skill rolls. If the roll involves interpretation of an omen, the bonus is +1k1 instead. Once per day, you may spend a Void Point to interpret an omen with absolute accuracy, with no need for a Skill roll to do so. (Of course, the GM still has discretion as to what the correct interpretation of the omen might be.) Special: You must be Ascetic and follow the peculiar practices of the Heaven’s Mirror sect, regardless of the social consequences of doing so. Failing to embrace these practices will result in your losing the benefits of your School Technique, and may also result in expulsion from this sect."}], "livro": "Book of Water (Livro da Água)"}, {"id": "any_minor_clan_defender", "clanId": "any_minor_clan", "nome": "Minor Clan Defender", "traco": "", "honra": "", "tags": ["bushi", "minor_clan", "advanced"], "pericias": [], "tecnicas": [{"id": "minor_know_no_boundaries", "nome": "Know no Boundaries", "rank": 1, "descricao": "Conviction and determination can elevate even the lowest samurai to greatness if he but follows his own sense of honor in moments of crisis. You may spend a Void Point to tempo- rarily gain two ranks of Status, forcing others to recognize your talents and abilities. This effect lasts for a period of one hour."}, {"id": "minor_speed_of_certainty", "nome": "The Speed of Certainty", "rank": 2, "descricao": "A true master of destiny is versatile and fleet of action. Once per Round you may spend a Void Point to make one melee attack as a Free Action. You may make no other attacks during this Round."}, {"id": "minor_strength_of_humility", "nome": "The Strength of Humility", "rank": 3, "descricao": "A defender of the Minor Clans is a paragon of strength and certainty, skilled in the samurai arts and capable of virtually any deadly action. You may make melee attacks as a Simple Action when using weapons with the Samurai keyword. If you already possess the ability to make attacks as a Simple Action when wielding such weapons, you may choose any one other type of melee weapon (knives, heavy weapons, spears, etc.). You gain the ability to attack with these weapons as a Simple Action instead."}], "livro": "Emerald Empire"}, {"id": "crab_ob_hida_pragmatist_school", "clanId": "crab", "nome": "Hida Pragmatist School", "traco": "agility", "honra": "2.5", "tags": ["bushi", "crab_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 2, "enfase": "Improvised Weapons"}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "crab_the_eternal_stone_unleashed", "nome": "The Eternal Stone Unleashed", "rank": 1, "descricao": ""}, {"id": "crab_wearing_down_the_mountain", "nome": "Wearing Down The Mountain", "rank": 2, "descricao": ""}, {"id": "crab_fury_of_the_avalanche", "nome": "Fury Of The Avalanche", "rank": 3, "descricao": ""}, {"id": "crab_stone_turns_steel_aside", "nome": "Stone Turns Steel Aside", "rank": 4, "descricao": ""}, {"id": "crab_fight_to_the_end", "nome": "Fight To The End", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "crane_ob_doji_magistrate_school", "clanId": "crane", "nome": "Doji Magistrate School", "traco": "reflexes", "honra": "5.5", "tags": ["bushi", "crane_bushi"], "pericias": [{"id": "defense", "rank": 1, "enfase": ""}, {"id": "horsemanship", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": "Jitte"}, {"id": "polearms", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "crane_temper_steel_with_honor", "nome": "Temper Steel With Honor", "rank": 1, "descricao": ""}, {"id": "crane_flowing_like_water", "nome": "Flowing Like Water", "rank": 2, "descricao": ""}, {"id": "crane_breath_of_the_law", "nome": "Breath Of The Law", "rank": 3, "descricao": ""}, {"id": "crane_flowing_like_air", "nome": "Flowing Like Air", "rank": 4, "descricao": ""}, {"id": "crane_the_willow_in_the_storm", "nome": "The Willow In The Storm", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "dragon_ob_mirumoto_taoist_swordsman", "clanId": "dragon", "nome": "Mirumoto Taoist Swordsman", "traco": "void", "honra": "5.5", "tags": ["bushi", "dragon_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "iaijutsu", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": "Katana"}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "dragon_aligned_with_the_elements", "nome": "Aligned With the Elements", "rank": 1, "descricao": ""}, {"id": "dragon_fist_and_blade", "nome": "Fist and Blade", "rank": 2, "descricao": ""}, {"id": "dragon_strike_of_harmony", "nome": "Strike of Harmony", "rank": 3, "descricao": ""}, {"id": "dragon_master_of_steel", "nome": "Master of Steel", "rank": 4, "descricao": ""}, {"id": "dragon_balance_in_nothingness", "nome": "Balance in Nothingness", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "lion_ob_the_ikoma_lions_shadow_school", "clanId": "lion", "nome": "The Ikoma Lion's Shadow School", "traco": "awareness", "honra": "3.5", "tags": ["bushi", "lion_bushi"], "pericias": [{"id": "courtier", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "investigation", "rank": 1, "enfase": "Notice"}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "lion_no_boundaries", "nome": "No Boundaries", "rank": 1, "descricao": ""}, {"id": "lion_the_lion_cannot_fail", "nome": "The Lion Cannot Fail", "rank": 2, "descricao": ""}, {"id": "lion_the_spirit_of_ikoma", "nome": "The Spirit Of Ikoma", "rank": 3, "descricao": ""}, {"id": "lion_the_quiet_lions_claws", "nome": "The Quiet Lion's Claws", "rank": 4, "descricao": ""}, {"id": "lion_ferocious_determination", "nome": "Ferocious Determination", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "monks_shinmaki_order", "clanId": "monks", "nome": "Shinmaki Order", "traco": "void", "honra": "6.5", "tags": ["monk", "monks_monk", "brotherhood", "monks_brotherhood"], "pericias": [{"id": "divination", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": "Diamond Sutra"}, {"id": "meditation", "rank": 2, "enfase": ""}], "tecnicas": [{"id": "monks_shinmaki_diamond_sutra", "nome": "The Diamond Sutra", "rank": 1, "descricao": "The monks who study the Diamond Sutra are known for their strange and bizarre behavior and esoteric practices, but also for their extreme spiritual purity and lack of respect for conventional etiquette. You start play with the Disturbing Countenance Disadvantage for no points, but gain a +1k0 bonus to Meditation rolls, Fear rolls, and to all Social Skill Rolls involving members of the heimin and hinin castes. You do not lose Honor for touching dead flesh (but lose Glory or gain Infamy normally)."}], "livro": "Emerald Empire"}, {"id": "phoenix_ob_shiba_artisan_school", "clanId": "phoenix", "nome": "Shiba Artisan School", "traco": "intelligence", "honra": "5.5", "tags": ["artisan", "phoenix_artisan"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "phoenix_soul_of_brilliance", "nome": "Soul Of Brilliance", "rank": 1, "descricao": ""}, {"id": "phoenix_the_way_of_sincerity", "nome": "The Way Of Sincerity", "rank": 2, "descricao": ""}, {"id": "phoenix_the_art_speaks", "nome": "The Art Speaks", "rank": 3, "descricao": ""}, {"id": "phoenix_bounty_of_the_craft", "nome": "Bounty Of The Craft", "rank": 4, "descricao": ""}, {"id": "phoenix_the_touch_of_destiny", "nome": "The Touch Of Destiny", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "scorpion_soshi_magistrate", "clanId": "scorpion", "nome": "Soshi Magistrate", "traco": "agility", "honra": "2.5", "tags": ["bushi", "scorpion_bushi"], "pericias": [{"id": "intimidation", "rank": 1, "enfase": "Control"}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "athletics", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "lore_underworld", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "scorpion_the_face_of_justice", "nome": "The Face of Justice", "rank": 1, "descricao": ""}, {"id": "scorpion_rise_to_meet_the_challenge", "nome": "Rise to Meet the Challenge", "rank": 2, "descricao": ""}, {"id": "scorpion_the_magistrates_cut", "nome": "The Magistrate's Cut", "rank": 3, "descricao": ""}, {"id": "scorpion_certainty_of_purpose", "nome": "Certainty of Purpose", "rank": 4, "descricao": ""}, {"id": "scorpion_relentless_resolve", "nome": "Relentless Resolve", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "unicorn_shinjo_bushi", "clanId": "unicorn", "nome": "Shinjo Bushi", "traco": "agility", "honra": "4.5", "tags": ["bushi", "unicorn_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "horsemanship", "rank": 2, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "unicorn_the_way_of_the_kirin", "nome": "The Way of the Ki-Rin", "rank": 1, "descricao": ""}, {"id": "unicorn_dance_of_the_blade", "nome": "Dance of the Blade", "rank": 2, "descricao": ""}, {"id": "unicorn_the_four_winds_strike", "nome": "The Four Winds Strike", "rank": 3, "descricao": ""}, {"id": "unicorn_spirit_of_the_blade_unleashed", "nome": "Spirit of the Blade Unleashed", "rank": 4, "descricao": ""}, {"id": "unicorn_dancing_with_the_fortunes", "nome": "Dancing with the Fortunes", "rank": 5, "descricao": ""}], "livro": "Emerald Empire"}, {"id": "crane_kakita_master_artisan", "clanId": "crane", "nome": "Kakita Master Artisan", "traco": "", "honra": "", "tags": ["artisan", "crane_artisan", "advanced", "crane_advanced"], "pericias": [], "tecnicas": [{"id": "crane_the_masters_touch", "nome": "The Master's Touch", "rank": 1, "descricao": "The Master Artisan transcends the social demands of art to focus on creating works of lasting magnificence which transform those who witness them. You may attempt to create such a work or performance with a chosen art Skill roll at TN 40. A success results in a creation or performance that awes everyone who witnesses its first public appearance. You gain 5 points of Glory, +1 additional point of Glory for each Raise called on the roll. Everyone in the audience at the art’s unveiling/performance gains one bonus Void Point (which can exceed their normal maximum) for the next 24 hours; if you successfully called at least 4 Raises on the roll, they gain two bonus Void Points instead. (The effects of this technique cannot stack.)"}, {"id": "crane_mastery_unbounded", "nome": "Mastery Unbounded", "rank": 2, "descricao": "At this level of skill, the Master Artisan’s skills become truly legendary. You gain a bonus of +2k0 with your chosen art Skill rolls. If you are trained as a Kakita Artisan, you may select a third chosen art from your School Skills."}, {"id": "crane_the_perfect_art", "nome": "The Perfect Art", "rank": 3, "descricao": "The final secret of the Master Artisans is a level of excellence that transcends the normal bounds of mortal capability, producing art that literally comes to life. Once per month when creating a work or performance with one of your chosen arts, you may spend two Void Points and then roll [chosen art] / Awareness at TN 50. With a success, the art comes to life— birds fly off a painting, the characters of a play manifest on the stage, the statue of a Fortune comes to life, and so forth. The specific nature of the manifestation, and what action it takes after appearing, is chosen by the GM—but it will always be helpful to you, and will usually be something awe-inspiring and extraordinary. The manifestation normally lasts only a few minutes, but if you successfully call four Raises on the skill roll it will last for one hour."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "dragon_mirumoto_master_sensei", "clanId": "dragon", "nome": "Mirumoto Master Sensei", "traco": "", "honra": "", "tags": ["bushi", "dragon_bushi", "advanced", "dragon_advanced"], "pericias": [], "tecnicas": [{"id": "dragon_the_sword_and_the_soul", "nome": "The Sword And The Soul", "rank": 1, "descricao": "The Master Sensei has learned that the sword can bring moments of perfect harmony, just like art or meditation. When fighting with a sword, any time you reduce an opponent to Down, Out, or Dead, you regain 1 Void Point. This can temporarily increase your total Void Points above your Void Ring, although any such “extra” points disappear at the end of the current skirmish."}, {"id": "dragon_the_body_is_illusion", "nome": "The Body Is Illusion", "rank": 2, "descricao": "The Master Sensei has studied meditation and enlightenment to such an extent that he can transcend the limitations of the flesh. You may take a Simple Action to spend a Void Point to ignore Wound Penalties (including Down, but not Out) for the remainder of this skirmish, or for ten minutes when outside of a skirmish."}, {"id": "dragon_sword_of_the_sensei", "nome": "Sword Of The Sensei", "rank": 3, "descricao": "The Master Sensei knows that a true teacher can share his greatest power with his students. Once per day, you may take a Simple Action to roll Awareness/Meditation at a TN of 25 plus 5 for each ally fighting alongside you. If you succeed, your allies gain the benefits of your Rank One technique for the remainder of this skirmish."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "lion_akodo_tactical_masters", "clanId": "lion", "nome": "Akodo Tactical Masters", "traco": "", "honra": "", "tags": ["bushi", "lion_bushi", "advanced", "lion_advanced"], "pericias": [], "tecnicas": [{"id": "lion_the_eyes_of_the_general", "nome": "The Eyes Of The General", "rank": 1, "descricao": "The Akodo Tactical Master spends his entire life studying the teachings of Lion generals from centuries past. He benefits from the wisdom of all of his ancestors and hones himself into the perfect general. You may reroll any one of your dice in each Battle Turn of Mass Combat. You may also reroll any one of your dice during an attack roll in which you called at least one Raise."}, {"id": "lion_malleable_as_the_sea", "nome": "Malleable As The Sea", "rank": 2, "descricao": "The Tactical Master can navigate the sudden changes in the battlefield, adapting and reacting so his army can benefi t. You may spend a Void Point to choose any one Heroic Opportunity from the core rulebook to perform during a Mass Battle Turn. (This choice is subject to GM approval, since not all options will be suitable for the situation and the characters involved.)"}, {"id": "lion_the_soul_of_the_army", "nome": "The Soul Of The Army", "rank": 3, "descricao": "The Tactical Master knows he is responsible for his army, and directs its strength where it may do the most damage. You may spend a Void Point to gain a +5k1 bonus to any Battle Skill Roll (rather than the usual +1k1), or to gain a +2k2 bonus to any Bugei Skill Roll (rather than the usual +1k1)"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "phoenix_asako_inquisitors", "clanId": "phoenix", "nome": "Asako Inquisitors", "traco": "", "honra": "", "tags": ["monk", "phoenix_monk", "advanced", "phoenix_advanced"], "pericias": [], "tecnicas": [{"id": "phoenix_eye_of_the_inquisitor", "nome": "Eye of the Inquisitor", "rank": 1, "descricao": "The Asako Inquisitors are taught to focus their will to disrupt the unnatural magic of blasphemers and criminals. You are considered one Rank higher in your original Shugenja School for the purposes of casting spells. Nonshugenja Inquisitors instead gain one Kiho, for which you must meet all prerequisites. During a skirmish you may use a Complex Action to prepare a disruption of enemy magic. At any point later in the same skirmish when an opponent is casting a spell, you may as a Free Action force him to make two additional Raises on his spell-casting roll. These additional Raises have no effect other than to raise the TN of the roll. Once this is done, you must take another Complex Action if you wish to ready another disruption."}, {"id": "phoenix_the_trials_of_jade", "nome": "The Trials of Jade", "rank": 2, "descricao": "An Inquisitor finds the weakness in his enemies and exploits it, bringing them the Emperor’s justice. When casting any spell, you may spend a Void Point for the spell to count as jade or crystal for the purposes of reducing or defeating your target’s Reduction or Invulnerability traits. If you cannot cast spells, you may instead make a melee attack as a Simple Action instead of a Complex Action when facing an opponent you know has violated the Empire’s laws regarding the legal forms of magic."}, {"id": "phoenix_conviction_of_purity", "nome": "Conviction of Purity", "rank": 3, "descricao": "Those who commit the unpardonable sin of breaking the Emperor’s laws concerning magic are unable to stand against you. You are considered one Rank higher in your original Shugenja School for the purposes of casting spells. Non-shugenja Inquisitors instead gain one additional Kiho, for which you must meet all prerequisites. You may now prepare a disruption (as per your Rank One technique) as a Simple Action instead of a Complex Action, and opponents whose spells are disrupted require three additional Raises rather than two."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "crab_ob_kaiu_engineer_school", "clanId": "crab", "nome": "Kaiu Engineer School", "traco": "intelligence", "honra": "4.5", "tags": ["artisan", "crab_artisan", "bushi", "crab_bushi"], "pericias": [{"id": "battle", "rank": 1, "enfase": ""}, {"id": "craft_armorsmithing", "rank": 1, "enfase": ""}, {"id": "craft_weaponsmithing", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "engineering", "rank": 1, "enfase": "*any"}, {"id": "lore_architecture", "rank": 1, "enfase": ""}, {"id": "war_fan", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "crab_the_kaiu_method", "nome": "The Kaiu Method", "rank": 1, "descricao": "A student of the Kaiu Method is taught the many basic essential disciplines the family uses to serve the Crab. You gain a bonus of +1k0 when making any School Skill Roll. When spending a Void Point to augment a School Skill Roll, you gain a bonus of +2k2 instead of +1k1. These effects are not cumulative."}, {"id": "crab_the_path_of_stone", "nome": "The Path Of Stone", "rank": 2, "descricao": "The Kaiu are feared on the battlefield for good reason—they are the masters of both construction and destruction. When constructing any large structure (temple-sized or larger), you may make an Engineering Skill Roll at TN 25 to add an additional number of Wounds to the structure equal to your School Rank x 100. Also, when commanding a siege engine, you may re-roll once any of the siege engine's damage dice that roll below your School Rank."}, {"id": "crab_the_path_of_the_shell", "nome": "The Path Of The Shell", "rank": 3, "descricao": "The security and protection of Crab samurai is a somber duty all Kaiu take very seriously indeed. When crafting any set of armor, you may double the crafting time and cost in order to add your School Rank to the armor's Reduction value. You may also add half your School Rank (rounding up) to the armor's Armor TN bonus."}, {"id": "crab_the_path_of_war", "nome": "The Path Of War", "rank": 4, "descricao": "Every Kaiu is a student of battle, as are all Crab. When you roll on the Mass Battle Chart, you may modify your result (up or down) by an additional amount equal to half your School Rank. Additionally, when fighting with a katana, dai tsuchi, or war fan, you may make melee attacks as a Simple Action rather than a Complex Action."}, {"id": "crab_the_path_of_steel", "nome": "The Path Of Steel", "rank": 5, "descricao": "The greatest and most sacred duty of the Kaiu is crafting the sacred weapons of the Crab Clan. When crafting any weapon, you may choose to confer either a +1k0 bonus to all attack rolls made with that weapon, or a +0k1 bonus to all damage rolls made with that weapon. If the weapon is a katana, you may expend all your Void Points (a minimum of one point must be spent) to make the blade unbreakable (as per the Sacred Weapon: Kaiu Blade Advantage). Doing so renders you unable to recover Void Points for one week."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "crab_ob_kuni_witch_hunter_school", "clanId": "crab", "nome": "Kuni Witch Hunter School", "traco": "willpower", "honra": "5.5", "tags": ["monk", "crab_monk"], "pericias": [{"id": "investigation", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "lore_maho", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "crab_to_see_the_darkness", "nome": "To See The Darkness", "rank": 1, "descricao": "Witch-Hunters are taught both to sense the power of Jigoku and to crush those who carry its dreadful mark. You may attempt to detect the Taint in another person by holding your jade pendant (or another piece of jade) and staring intently at them. This is a Complex Action and requires you to make a Contested Roll of your Investigation (Interrogation) / Awareness against the target's Sincerity (Deceit) / Willpower. You gain a +1k0 bonus to this roll for every full Rank of Taint the target possesses. If you succeed in the roll and the target is Tainted (has at least 1 Rank of Taint), you are able to sense the presence of the Taint and its approximate strength. If you fail the roll or the target is not Tainted, you gain no information. In addition, you gain +1k1 to your rolls to resist the Shadowlands Taint and to your attack rolls when attacking a foe who is a Shadowlands creature or who you know to be Tainted."}, {"id": "crab_to_ride_the_darkness", "nome": "To Ride The Darkness", "rank": 2, "descricao": "Witch-Hunters do not confine themselves to rooting out Tainted men and women—they also learn how to fight the creatures of the Shadowlands, and spend considerable time studying their strengths and weaknesses. Any time you are confronted by a Shadowlands creature, you may take a Free Action to roll Lore: Shadowlands / Intelligence at TN 20 to recall either one specific strength (such as Invulnerability) or one specific weakness (such as jade) for that creature. You choose whether you recall a strength or a weakness, but the GM chooses the exact information. You may Raise on this roll to learn additional pieces of information—one strength or weakness per Raise."}, {"id": "crab_to_strike_the_darkness", "nome": "To Strike The Darkness", "rank": 3, "descricao": "At this rank the Witch-Hunter learns to call on the power of purity to guide and strengthen his blows. You may make melee attacks as a Simple Action when your opponent is a Shadowlands creature or when you know your opponent to be Tainted."}, {"id": "crab_to_repel_the_darkness", "nome": "To Repel The Darkness", "rank": 4, "descricao": "The Witch-Hunter's intense study and spiritual training now gives him access to esoteric powers and makes it almost impossible for the forces of darkness to deceive him. You gain a +3k0 bonus to the roll for your Rank One ability to detect the Taint and to the roll for your Rank Two ability. In addition, you may learn one Kiho. (If the optional rule allowing Kiho for non-Brotherhood monks is in effect, this Kiho does not count against the maximum number of Kiho you can learn, although it is subject to their other mechanical limitations such as Mastery Level.)"}, {"id": "crab_to_shatter_the_darkness", "nome": "To Shatter The Darkness", "rank": 5, "descricao": "The Witch-Hunter is now the true nemesis of Jigoku's forces, able to strike down his enemies with unmatched power. You gain a +4k1 bonus to your attack and damage rolls against Shadowlands creatures and against foes you know to be Tainted. This stacks with the attack bonus from your Rank One technique."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "crane_ob_daidoji_scout_school", "clanId": "crane", "nome": "Daidoji Scout School", "traco": "reflexes", "honra": "3.5", "tags": ["bushi", "crane_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": "Traps"}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": "Yumi"}, {"id": "stealth", "rank": 1, "enfase": "Sneaking"}], "tecnicas": [{"id": "crane_surveying_the_land", "nome": "Surveying The Land", "rank": 1, "descricao": "The Daidoji scouts are masters of observation and pursuit, tracking their opponents, harassing them, and delaying them with traps and ambushes. You gain +1k0 with Stealth and Hunting skill rolls. Any rural/improvised traps you create are exceptionally deadly, inflicting +1k1 extra damage."}, {"id": "crane_scouring_the_shadows", "nome": "Scouring The Shadows", "rank": 2, "descricao": "Daidoji scouts strike from concealment, hitting their opponents with swift and devastating attacks. When attacking an unaware opponent you gain a bonus of +2k0 to your attack roll."}, {"id": "crane_weaken_the_resistance", "nome": "Weaken The Resistance", "rank": 3, "descricao": "The Daidoji learn to strike with precision, hitting their opponents in weak spots and evading their armor. You may ignore any Reduction your opponent gains from wearing armor or from school techniques. (You cannot ignore the natural Reduction of creatures, or Reduction bestowed by magical or supernatural effects.) If you attack an opponent who has no Reduction from armor or techniques, you gain +1k0 to your damage rolls."}, {"id": "crane_strike_and_move", "nome": "Strike And Move", "rank": 4, "descricao": "The Daidoji scout strikes with the swiftness of the wind itself. You may make attacks as a Simple Action instead of a Complex Action when wielding a katana, wakizashi, knife, or bow. Your traps now inflict +2k1 extra damage."}, {"id": "crane_cunning_of_daidoji", "nome": "Cunning Of Daidoji", "rank": 5, "descricao": "The true master of the Daidoji scout school needs only a single strike, for his opponent never survives to see the second one. During a skirmish, you may spend a Void Point as a Free Action to attempt a deadly precision strike on your next attack (this may be done with a melee or a ranged attack, but cannot be done more than once in the same Turn). Any Maneuvers called on this attack require 1 less Raise (to a minimum of 1 Raise), and if you successfully hit you gain a bonus of +1k1 to your Damage roll. Furthermore, if your opponent is unaware of you, your Raises on this attack are not limited by your Void."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "crane_ob_kakita_artisan_school", "clanId": "crane", "nome": "Kakita Artisan School", "traco": "awareness", "honra": "5.5", "tags": ["artisan", "crane_artisan"], "pericias": [{"id": "courtier", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "games_sadane", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "crane_soul_of_the_artisan", "nome": "Soul Of The Artisan", "rank": 1, "descricao": "The Kakita Artisan is taught from earliest youth to focus on one specific form of art above all others, devoting himself to it heart and soul and pursuing the goal of absolute perfection within its forms. Of course, in keeping with Crane tradition the Artisan is also taught to be a ruthless critic to any artistic rivals. Select one of your three chosen School Skills (Acting, an Artisan skill, or a Perform skill) as the focus of your artistic training. This becomes your chosen art. When making skill rolls with your chosen art, you gain a +2k0 bonus and your Raises are not limited by your Void. Any time you are using Games: Sadane to criticize someone else's art or performance, you gain a Free Raise on your skill roll."}, {"id": "crane_the_souls_dream", "nome": "The Soul's Dream", "rank": 2, "descricao": "The Kakita Artisan is taught to use his art to affect those around them, inspiring emotions and shifting the views of the audience. When presenting a public performance or display of you chosen art, you may make a Contested Social Roll of [chosen art]/Awareness against the Etiquette (Courtesy)/Willpower of the audience members. Those audience members who fail their rolls are profoundly swayed and their emotions shift in a direction you desire—becoming friendlier, more hostile, calmer, or whatever other emotional shift your art is designed to evoke. This emotional shift normally lasts a number of hours equal to your Insight Rank. Note that not all persons are equally susceptible to the impact of art—the GM may rule that a particular individual is affected for a shorter period of time, or award a bonus to the resistance roll for persons whose emotions are difficult to manipulate. The GM should normally have each individual audience member roll separately to resist this technique (this should always be done for PCs or important NPCs), but with large groups of ordinary NPCs the GM can opt to save time by making a single roll for most or all of them."}, {"id": "crane_free_the_spirit", "nome": "Free The Spirit", "rank": 3, "descricao": "You may select a second of your three chosen School Skills as a chosen art, and all Technique bonuses and effects which applied to your first chosen art now apply to it as well. The bonus to your chosen art skill rolls increases to +2k1."}, {"id": "crane_undying_name", "nome": "Undying Name", "rank": 4, "descricao": "Your art is now so magnificent that you can make and break the reputations of others by depicting or referencing them in your work. You may create a piece of art referring to another person by rolling [chosen art]/Awareness at a TN equal to 20 plus 5x their Glory Rank. With a success, you may either increase (if your art is complimentary) or decrease (if it is critical) their Glory by up to 5 points, plus an additional 5 points for every Raise you make on the roll. You may call two additional Raises to inflict a gain of Infamy on the target instead of a Glory change. You may not target the same person with this technique more than once every six months. Furthermore, persons of high station cannot have their reputations damaged by artists lacking in prestige—the target's Status Rank cannot exceed your Glory or Status Rank (whichever is higher)."}, {"id": "crane_gift_beyond_price", "nome": "Gift Beyond Price", "rank": 5, "descricao": "You art is now so perfect that a gift of it can profoundly change another person's attitude toward you and your clan. Once per month, you may give a gift of your chosen art to someone from another clan or faction. Make a Contested Social Roll of your [chosen art]/Awareness against their Etiquette (Courtesy)/Willpower. (The GM may award Free Raises to you or the target of this technique based on the type and subject of the art and the attitudes and beliefs of the target—some people are easier to sway than others.) With a success, you permanently alter their attitude toward your clan/faction in a favorable direction. With a failure, the target becomes aware of your attempt to manipulate his emotions, and his attitude toward your clan/ faction permanently shifts in a hostile direction."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "lion_ob_matsu_beastmaster_school", "clanId": "lion", "nome": "Matsu Beastmaster School", "traco": "agility", "honra": "5.5", "tags": ["bushi", "lion_bushi"], "pericias": [{"id": "animal_handling", "rank": 2, "enfase": ""}, {"id": "battle", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "iaijutsu", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "lion_one_with_the_pride", "nome": "One With The Pride", "rank": 1, "descricao": "You have trained in the highly secretive dojo of the Matsu Beastmasters and have forged a bond with one of the legendary Lion warcats. The lion will accompany you wherever you go and follows basic commands without question. No lion will ever attack you without being compelled to do so in some way. You may direct one of your warcats to Attack as a Complex Action. Any one warcat who is not attacking will use the Guard Action to protect you."}, {"id": "lion_heart_of_the_beast", "nome": "Heart Of The Beast", "rank": 2, "descricao": "Your training with the warcats has increased your physical abilities as well as your mental bond with your lions. An additional lion joins your pride. You and your companion lions gain the creature trait of Swift 2 (as described in the L5R 4th Edition core rules, page 320), and all of your lions gain an additional Wound Rank that changes the end of their progression from a normal lion's to: 36: +15, 60: Dead."}, {"id": "lion_the_ferocity_within", "nome": "The Ferocity Within", "rank": 3, "descricao": "You strike as fiercely as the lions with whom you have trained. When wielding a katana, wakizashi, magari-yari, nage-yari, or any knife, or when fighting unarmed, you may make melee attacks as a Simple Action. Additionally, you may direct one of your warcats to Attack as a Simple Action."}, {"id": "lion_all_as_one", "nome": "All As One", "rank": 4, "descricao": "The fury of the beastmaster and his pride is a whispered legend among your clan's enemies, and for good reason. Members of your pride may make two claw attacks per Round instead of the normal one. You and all members of your pride gain a bonus of +2k1 on all damage rolls made when fighting alongside one another. Finally, when you direct a warcat to Attack (a Complex Action for lions), the warcat may also make a Simple Move Action during the same Round."}, {"id": "lion_with_the_soul_of_a_lion", "nome": "With The Soul Of A Lion", "rank": 5, "descricao": "United by your leadership and companionship, your pride has become fearsome indeed. An additional lion joins your pride. All of your warcats gain +10 Armor TN, +2 Reduction, and +2 Fear."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "mantis_ob_yoritomo_shugenja_school", "clanId": "mantis", "nome": "Yoritomo Shugenja School", "traco": "perception", "honra": "4.5", "tags": ["shugenja", "mantis_shugenja"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "sailing", "rank": 1, "enfase": "Navigation"}], "tecnicas": [{"id": "mantis_child_of_the_sea", "nome": "Child Of The Sea", "rank": 1, "descricao": "The family line of the Yoritomo who possess the talent for magic have a strong bond with the sea and with weather as a whole. You may expend one spell slot to alter the wind conditions in your current location by one degree. If you also spend a Void Point, you may instead shift the entire weather status one degree. You may expend a maximum combined total of spell slots and/or Void Points equal to your School Rank each Round to enact these shifts. These shifts affect an area a number of miles equal to your School Rank in all directions from your current location. You gain a Free Raise on all Thunder spells."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "mantis_ob_mantis_brawler_school", "clanId": "mantis", "nome": "Mantis Brawler School", "traco": "agility", "honra": "3.5", "tags": ["bushi", "mantis_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "commerce", "rank": 1, "enfase": ""}, {"id": "intimidation", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}, {"id": "sailing", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "mantis_way_of_the_drunken_fist", "nome": "Way Of The Drunken Fist", "rank": 1, "descricao": "The basic techniques of the Mantis Brawlers are based on the need to prevail in chaotic fights on tilting ship decks… or when reeling drunk through a sake house. Brawlers are tough and slippery fighters who evade the grip of their enemies while striking them at every opportunity. If you are Prone, you do not suffer any penalties to your Armor TN or to your attacks with Small weapons (or when unarmed). You still gain the Prone Armor TN bonus against ranged attacks. Also, you gain a bonus of +1k0 to rolls made to take control of Grapples and to your damage rolls with unarmed strikes, improvised weapons, and Small weapons."}, {"id": "mantis_drunk_loses_his_sandal", "nome": "Drunk Loses His Sandal", "rank": 2, "descricao": "Mantis Brawlers learn to be swift and flexible fighters who attack their foes from unexpected directions, often deliberately offering the appearance of weakness in order to create openings. If you successfully perform the Feint maneuver, you may choose to reduce the extra damage from the Feint by 5 in order to add +5 to your Armor TN until the start of your next Turn; if you were Prone when you performed the Feint, you add +10 instead. Also, immediately after an enemy attack resolves against you (whether or not the attack hit or inflicted damage on you), you may take a Free Action to become Prone."}, {"id": "mantis_drunk_never_falls", "nome": "Drunk Never Falls", "rank": 3, "descricao": "The third lesson of the Mantis Brawler is to win even when exhausted, dead drunk, or clubbed on the head. During a skirmish, you do not suffer any penalties for being Fatigued or Dazed, nor do you suffer any penalties for intoxication. If you become Stunned, you may still take one Simple Action per Round."}, {"id": "mantis_two_drunks_dance", "nome": "Two Drunks Dance", "rank": 4, "descricao": "The erratic bobbing, squirming, and weaving of the Mantis Brawler creates additional opportunities for him to attack his foe. You may attack as a Simple Action when fighting unarmed, with an improvised weapon, or with a Small weapon."}, {"id": "mantis_drunk_pounds_a_door", "nome": "Drunk Pounds A Door", "rank": 5, "descricao": "The final lesson of the Mantis Brawler is to strike so hard his foe never gets the chance to strike back. When making a melee attack you may spend a Void Point to deliver a fierce shattering blow; this attack gains a bonus of +4k1 to both the attack roll and the damage roll. If you are Prone, the bonus is +4k2 instead."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "mantis_ob_tsuruchi_bounty_hunter_school", "clanId": "mantis", "nome": "Tsuruchi Bounty Hunter School", "traco": "agility", "honra": "4.5", "tags": ["bushi", "mantis_bushi"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": "Tracking"}, {"id": "intimidation", "rank": 1, "enfase": ""}, {"id": "investigation", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "lore_underworld", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "mantis_a_hunters_sense", "nome": "A Hunter's Sense", "rank": 1, "descricao": "A Tsuruchi bounty hunter is well known as a fierce and terrible opponent of all who seek to evade justice, and even those who are without guilt find them intimidating. You gain a bonus of +1k1 to any Intimidation Skill Roll used against someone of lower caste who you believe can help you find your prey. When interacting with samurai, this bonus is reduced to +1k0 but applies to all Social Skill Rolls, not just Intimidation. Also, when you are hunting a particular target, you may roll additional unkept dice equal to your School Rank on any Hunting or Investigation Skill Rolls used to track the quarry down."}, {"id": "mantis_no_prey_escapes", "nome": "No Prey Escapes", "rank": 2, "descricao": "A true master of the Tsuruchi method has an encyclopedic knowledge of criminals throughout the Empire and can use them as tools to capture his prey. You may spend a Void Point to automatically succeed at a Lore: Underworld Skill Roll to identify any criminals in an area who you might be able to press for information regarding your prey. You lose Honor as normal for associating with such individuals, however."}, {"id": "mantis_justice_of_the_wasp", "nome": "Justice Of The Wasp", "rank": 3, "descricao": "The Tsuruchi hunters are merciless, but have a reputation for bringing their prey back alive to suffer a proper sentence for their criminal acts. When facing an opponent who has been declared guilty of a crime by an Imperial or a higher Mantis authority, you may make the Disarm or Knockdown Maneuvers for one Raise less than normal. If you successfully execute one of these Maneuvers against an opponent, that opponent is automatically Dazed."}, {"id": "mantis_twin_sting_strikes", "nome": "Twin Sting Strikes", "rank": 4, "descricao": "The justice of a Tsuruchi is swift and without mercy. You may make ranged attacks as a Simple Action when wielding a yumi. Additionally, if facing any target decreed guilty of a crime by an Imperial or a higher Mantis authority, you may also make melee attacks as a Simple Action when wielding a katana or any knife."}, {"id": "mantis_eyes_of_the_wasp", "nome": "Eyes Of The Wasp", "rank": 5, "descricao": "The worst truth a bounty hunter learns is that anyone can be a fugitive; thus a bounty hunter makes careful assessments of everyone he meets. When you identify a samurai using a Lore: Heraldry Skill Roll, you not only learn his Glory but also his Honor Rank and all Social and Mental Disadvantages. Also, any opponent who may be targeted by your Rank 3 Technique is now automatically Dazed if you successfully hit them with an attack, regardless of whether or not you use a Disarm or Knockdown Maneuver on them."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "phoenix_ob_asako_henshin_school", "clanId": "phoenix", "nome": "Asako Henshin School", "traco": "willpower", "honra": "5.5", "tags": ["monk", "phoenix_monk"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "jiujutsu", "rank": 1, "enfase": ""}, {"id": "lore_elements", "rank": 1, "enfase": "*any"}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 2, "enfase": ""}], "tecnicas": [{"id": "phoenix_the_four_mysteries", "nome": "The Four Mysteries", "rank": 1, "descricao": "The first lesson of the mysterious Henshin is the relationship between the individual and the Elements that comprise all things. You may, as a Simple Action, increase or decrease both Traits associated with one of your Rings by an amount equal to your School Rank. This lasts for a number of minutes equal to your Insight Rank and may be done a total number of times per day equal to five times your Insight Rank. You may instead increase or decrease the Traits of another in a similar manner, but only by an amount equal to half your School Rank, rounding down (to a minimum of 1). Altering the Traits of an unknowing or unwilling target requires a Contested Willpower Roll. Traits reduced in this manner do not affect a target's Rings (and thus do not change Wound Ranks when the Earth Ring is targeted, etc.)."}, {"id": "phoenix_the_riddle_of_earth", "nome": "The Riddle Of Earth", "rank": 2, "descricao": "The stoic and straightforward kami of Earth are the simplest to entertain with one's riddles, and their blessings are potent indeed. As a Simple Action, you may invoke this Technique and gain Earth's blessing; you are immune to all Conditional Effects (excluding Grappled and Mounted) for a number of hours equal to your Earth Ring."}, {"id": "phoenix_the_riddle_of_air", "nome": "The Riddle Of Air", "rank": 3, "descricao": "The capricious spirits of Air can be delighted into conferring their blessings upon you. As a Simple Action, you may invoke the blessing of Air. The blessing lasts a number of hours equal to your School Rank. For the duration of this effect, you cannot be deceived by any illusion or other false images, and can perceive them as transparent falsehoods. If an illusion is created by a spell of higher Mastery Level than your Insight Rank, you and the spell's caster must engage in a Contested Air Roll. If you are defeated, you do not perceive the falsehood of the illusion."}, {"id": "phoenix_the_riddle_of_fire", "nome": "The Riddle Of Fire", "rank": 4, "descricao": "The wrathful spirits of Fire can be entertained by your riddles, if only briefly. As a Complex Action you may invoke Fire's blessings to increase the number of kept dice on an unarmed damage roll (which is normally 0k1) to your Fire Ring. This effect lasts a number of Rounds equal to your School Rank. Alternatively, when an opponent strikes you with a melee attack, you may spend a Void Point to force a Contested Fire Ring Roll. If you are successful, the number of damage dice your opponent rolls is reduced by your Fire Ring."}, {"id": "phoenix_the_riddle_of_water", "nome": "The Riddle Of Water", "rank": 5, "descricao": "The mercurial spirits of Water can confer their speed and fluidity in exchange for your riddles. You must succeed at a Lore: Elements (Water) / Water Skill Roll against TN 20. If successful, you may take one Complex and one Simple"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "scorpion_yogo_wardmaster_school", "clanId": "scorpion", "nome": "Yogo Wardmaster", "traco": "intelligence", "honra": "1.5", "tags": ["shugenja", "scorpion_shugenja"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": "Cipher"}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "investigation", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "scorpion_way_of_the_wardmaster", "nome": "Way of the Wardmaster", "rank": 1, "descricao": "The Yogo are masters at creating wards for later use. When you cast any spell with the Wards keyword, you may Raise a number of times equal to the spell's Mastery Level to instead place the spell into a paper ward. Once this is done, the paper ward will hold the spell “latent” until you activate it (as a Simple Action) by placing it on a target. Only you may activate your wards. The ward sticks to the target and immediately discharge the spell, whose duration is measured normally from that moment. If an area-effect spell is discharged onto a living target, it will only affect that target. Placing a paper ward on an unwilling target requires an unarmed melee attack using a roll of Spellcraft / Agility. An active ward may be physically torn/destroyed, which instantly ends any ongoing spell effects; this requires a Simple Action. You cannot recover the spell slot of a spell which has been cast into a paper ward until after the ward is discharged. If a ward is damaged or destroyed before it is discharged, it loses all power and you may regain the spell slot normally."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "scorpion_shosuro_actors_school", "clanId": "scorpion", "nome": "Shosuro Actors", "traco": "awareness", "honra": "1.5", "tags": ["ninja", "scorpion_ninja"], "pericias": [{"id": "acting", "rank": 1, "enfase": ""}, {"id": "etiquette", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": "Deceit"}, {"id": "stealth", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "scorpion_the_first_face", "nome": "The First Face", "rank": 1, "descricao": "The Shosuro Actor begins his career by learning the basics of deception and mimicry, and takes his first steps on the path of infiltrating the Empire. You learn one persona. Any time you spend a Void Point on an Acting or Sincerity (Deceit) Skill roll, you a bonus of +3k1 instead of the normal +1k1."}, {"id": "scorpion_the_subtle_sting", "nome": "The Subtle Sting", "rank": 2, "descricao": "Shosuro Actors are expected to serve their clan as both infiltrators and assassins. You gain a bonus of +2k0 to your attack rolls when wielding a Small weapon."}, {"id": "scorpion_the_second_face", "nome": "The Second Face", "rank": 3, "descricao": "The Actor’s training has now advanced enough to make him a far more flexible and capable infiltrator. You learn a second persona. In addition, you may now spend two Void Points (rather than just one) when enhancing a Skill roll with any of your School Skills. This stacks with the effects of your Rank One ability."}, {"id": "scorpion_the_vipers_kiss", "nome": "The Vipers Kiss", "rank": 4, "descricao": "The Shosuro Actor intensifies his martial training to enable swift and deadly assassinations of his targets. You may attack as a Simple Action instead of a Complex Action when using a Small-sized weapon."}, {"id": "scorpion_the_third_face", "nome": "The Third Face", "rank": 5, "descricao": "The Shosuro Actor is now a true master of deception, infiltration, and murder. You gain a third persona. In addition, if you attack a foe who is unaware or does not expect danger from you, your Raises are not limited by your Void."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "spider_goju_ninja_school", "clanId": "spider", "nome": "Goju Ninja", "traco": "agility", "honra": "0.0", "tags": ["ninja", "scorpion_ninja"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "ninjutsu", "rank": 1, "enfase": ""}, {"id": "stealth", "rank": 2, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": "Deceit"}], "tecnicas": [{"id": "spider_the_cloak_of_night", "nome": "The Cloak Of Night", "rank": 1, "descricao": "The first lesson a Goju masters is the art of wrapping oneself in shadow, gaining concealment from enemies in exchange for making direct action more difficult. You may increase your Armor TN up to a maximum amount equal to your School Rank x 5. The TN of all your rolls other than Athletics, Defense, and Stealth Skill Rolls is increased by the same amount. Activating this Technique is a Simple Action and it lasts for the duration of the skirmish."}, {"id": "spider_melting_into_shadow", "nome": "Melting Into Shadow", "rank": 2, "descricao": "A Goju is not merely protected by the darkness but part of it, and can blend easily within it. You gain bonus rolled dice equal to your School Rank on any Stealth Skill Roll. Any uncontested roll made by an opponent trying to detect you automatically has its TN increased by an amount equal to your School Rank x 5. You gain one Free Raise on all attack rolls made against opponents who are unaware of your presence."}, {"id": "spider_the_shadowed_blade", "nome": "The Shadowed Blade", "rank": 3, "descricao": "The Goju is a swift and merciless foe. You may make an attack as a Simple Action rather than a Complex Action when attacking with knives or any weapon that uses the Ninjutsu Skill. Alternatively, when wielding shuriken, you may take a Complex Action to make a number of ranged attacks equal to your School Rank."}, {"id": "spider_step_within_shadow", "nome": "Step Within Shadow", "rank": 4, "descricao": "As all darkness is one with the Goju, so too can the Goju use the darkness to move between shadows without crossing the space in between. You may enter any shadow large enough to conceal an individual of your size and emerge from any other similarly-sized shadow nearby. This is considered a Simple Move Action. The range of this movement is equal to your School Rank x 100 feet."}, {"id": "spider_shadow_upon_the_moon", "nome": "Shadow Upon The Moon", "rank": 5, "descricao": "A true Goju no longer even vaguely resembles anything human. Your facial features are permanently erased, leaving only a tell-tale eggshell mask in their place. In darkness or shadows, you may dissolve your physical body into a vague cloud of inky vapor. This is a Simple Action; changing back into corporeal form is a Free Action. You may move at your full speed while in incorporeal form but may not physically interact with any object or individual and cannot be harmed by anything except crystal. You may pass through solid matter in a thickness of up to your School Rank x 5 in inches. You gain +5 to your Initiative Score during the first Round (only) each time you change back to your corporeal form."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "spider_ninube_shugenja_school", "clanId": "spider", "nome": "Ninube Shugenja", "traco": "awareness", "honra": "0.0", "tags": ["shugenja", "spider_shugenja"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}, {"id": "sincerity", "rank": 1, "enfase": "Lying"}, {"id": "stealth", "rank": 2, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "spider_mask_of_the_nothing", "nome": "Mask of the Nothing", "rank": 1, "descricao": "As a Complex Action you may expend a spell slot to dissolve your physical self and become a shadow. As a shadow you are invisible in darkness and gain a bonus of +5k0 to your Stealth Skill Rolls under all other circumstances. You are immune to most mundane attacks, but crystal and magic can affect you. Magical attacks that involve crystal or generate light double their rolled damage dice against you. When in shadow form, if you suffer damage that would kill you, you instead return to physical form at once with either half of your Wounds or with the Wounds you possessed when you entered shadow form, whichever is lower; you are Stunned when this happens. You may not inflict damage on others in any way while in shadow form, but you may cast non-damaging spells and can speak in the form of a disembodied whisper. You gain a Free Raise on all Nothing spells. You may not cast maho spells."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "unicorn_meishodo_horiuchi_shugenja_school", "clanId": "unicorn", "nome": "Meishodo/Horiuchi Shugenja School", "traco": "stamina", "honra": "4.5", "tags": ["shugenja", "unicorn_shugenja"], "pericias": [{"id": "calligraphy", "rank": 1, "enfase": ""}, {"id": "craft_meishodo", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": "Spell Research"}], "tecnicas": [{"id": "unicorn_mysteries_of_meishodo", "nome": "Mysteries of Meishodo", "rank": 1, "descricao": "Meishodo is a mixture of gaijin and Rokugani magic, resulting in a fast and powerful method of calling the kami. Shugenja studying these methods learn to create meishodo amulets, keyed to invoke the elements in specific ways. You may create a magical amulet by making a successful roll of Craft: Meishodo/Ring, using the Ring for the desired spell. The TN of this roll is equal to 15 plus 5x the spell's Mastery Level. Creating a meishodo requires a number of hours equal to the spell's Mastery Level. If the roll is successful, you create a small charm imbued with the prayer to the kami that will cast the chosen spell. Each meishodo stores only one spell, and is used in place of the scroll normally required to cast the spell. Casting a spell through a meishodo requires only one Complex Action, regardless of the Mastery Level of the spell. You do not have to make a Spell Casting Roll to cast the spell, but the spell cannot gain any benefits from Raises (not even Free Raises). You expend a spell slot as normal. You may only create meishodo from spells of a Mastery Level equal or less than your Shugenja School Rank, and can never create meishodo from spells of Mastery Level 4, 5 or 6. Other shugenja may use your meishodo if they are proficient in meishodo magic (e.g. trained in this school)."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "unicorn_moto_vindicator_school", "clanId": "unicorn", "nome": "Moto Vindicator School", "traco": "willpower", "honra": "3.5", "tags": ["bushi", "unicorn_bushi"], "pericias": [{"id": "horsemanship", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "investigation", "rank": 1, "enfase": "Notice"}, {"id": "kenjutsu", "rank": 1, "enfase": ""}, {"id": "kyujutsu", "rank": 1, "enfase": ""}, {"id": "lore_shadowlands", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "unicorn_purity_of_the_breath", "nome": "Purity of the Breath", "rank": 1, "descricao": "The Vindicator knows the only way to combat the Shadowlands is to maintain integrity in the face of the foulest corruption. At the beginning of each Round, you may choose one of two effects to apply until the end of the Round. You may reduce your TN penalties from Wound Ranks by an amount equal to your School Rank plus your Willpower. Or, you may instead choose to add a bonus to your Armor TN equal to your School Rank plus your Willpower. If you are in a skirmish against creatures of the Shadowlands, the chosen bonus is doubled."}, {"id": "unicorn_facing_the_dark_within", "nome": "Facing the Dark Within", "rank": 2, "descricao": "The Vindicator learns to hone his senses so that he is never surprised by those who serve the darkness. You gain a +2k0 bonus to all Investigation rolls. This bonus is increased to +2k1 if you are specifically attempting to notice effects of the Shadowlands Taint."}, {"id": "unicorn_justice_of_our_ancestors", "nome": "Justice of our Ancestors", "rank": 3, "descricao": "The Vindicator's rage at his foes knows no bounds. You may make melee attacks as a Simple Action instead of a Complex Action."}, {"id": "unicorn_avenging_our_own", "nome": "Avenging our Own", "rank": 4, "descricao": "The Vindicator's fury is provoked the most when it is directed at those creatures he once called his brothers. You gain a bonus of +2k0 to your attack and damage rolls against any enemy who has attacked you in this skirmish and against any creature with the Shadowlands Taint whether it has attacked you or not."}, {"id": "unicorn_bloodied_but_unbowed", "nome": "Bloodied but Unbowed", "rank": 5, "descricao": "The Vindicator can push on past physical limits once his goal is in sight. Once per skirmish, you may choose to keep fighting despite your injuries. Activating this Technique is a Free Action. Once it is active, while making melee attacks you gain a bonus to the total of your damage rolls equal to the TN penalties you are suffering from Wound Ranks. (This uses the default Wound penalties, ignoring modifications from Advantages, spells, or other such effects.) The effects of this Technique last for two full Rounds. You may choose to extend the effects of this Technique for an additional Round by taking ten Wounds."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "yobanjin_warrior", "clanId": "various", "nome": "Yobanjin Warrior", "traco": "agility", "honra": "4.5", "tags": ["bushi", "ronin", "ronin_bushi", "yobanjin"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "crossbow", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": "Yobanjin"}, {"id": "swordsmanship_ring_sword", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "yobanjin_strength_of_the_unbowed", "nome": "Strength of the Unbowed", "rank": 1, "descricao": "The Yobanjin focus their training on the preferred weapons of their people and on the strength found in their Rujia philosophy. You gain a +1k0 bonus to your Swordsmanship and Crossbow Skill rolls. Once per skirmish, you may add your \"Integrity\" Rank to the total of either a Skill roll or a Damage roll with a ring-sword or a crossbow. (The \"Integrity Rank\" of the Yobanjin represents their adherence to the Rujia philosophy rather than Bushido, and is used mechanically in the same manner as Honor.)"}], "livro": "The Imperial Archives"}, {"id": "yobanjin_shaman_shugenja", "clanId": "various", "nome": "Yobanjin Shaman (Shugenja)", "traco": "willpower", "honra": "4.5", "tags": ["shugenja", "ronin", "ronin_shugenja", "yobanjin"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "defense", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "knives", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": "Yobanjin"}], "tecnicas": [{"id": "yobanjin_spirits_of_the_mountain", "nome": "Spirits of the Mountain", "rank": 1, "descricao": "Yobanjin shamans are able to cast Elemental spells without scrolls, but can only cast spells of Mastery Rank 1, 2, or 3. (At the GM's option, spells which are specific to Rokugani culture may be excluded.) Once per year, a shaman may summon a wyrm and bind it to an amulet."}], "livro": "The Imperial Archives"}, {"id": "unicorn_moto_death_priests", "clanId": "unicorn", "nome": "Moto Death Priests", "traco": "willpower", "honra": "3.5", "tags": ["shugenja", "unicorn_shugenja"], "pericias": [{"id": "athletics", "rank": 1, "enfase": ""}, {"id": "horsemanship", "rank": 1, "enfase": ""}, {"id": "hunting", "rank": 1, "enfase": ""}, {"id": "lore_theology", "rank": 1, "enfase": ""}, {"id": "meditation", "rank": 1, "enfase": ""}, {"id": "spellcraft", "rank": 1, "enfase": ""}], "tecnicas": [{"id": "unicorn_blessings_of_the_shitien_yenwang", "nome": "Blessings of the Shi-Tien Yen-Wang", "rank": 1, "descricao": ""}], "livro": "Imperial Histories"}, {"id": "crane_children_of_doji", "clanId": "crane", "nome": "Children of Doji", "traco": "", "honra": "", "tags": ["advanced", "courtier", "crane_courtier", "crane_advanced"], "pericias": [], "tecnicas": [{"id": "crane_children_of_doji_social_butterfly", "nome": "Social Butterfly", "rank": 1, "descricao": "A Child of Doji makes friends like others breathe and is able to call upon them with the mere mention of a name. When making any Contested Social Skill roll, you gain a bonus of +Xk0, where X equals the number of Allies you possess in this court with a Devotion of 2 or greater (this bonus cannot exceed your Insight Rank in dice). Also, if you have at least three such Allies in this court, you may expend (lose) one of those Allies to gain the Darling of the Court Advantage for the remainder of this season (spring, winter, etc)."}, {"id": "crane_children_of_doji_all_is_fair", "nome": "All is Fair", "rank": 2, "descricao": "A key skill of the Children of Doji is the ability to reach beyond the courts to control the field of battle through their political influence. A rikugunshokan who is leading his army against the Crane may suddenly find that favorable terrain has been deemed sacrosanct and the war must be fought on less advantageous ground, or that a key supply shipment has been diverted elsewhere. Conversely, an ally of the Crane may find a legion of Imperial troops arriving to aid his cause, or a duelist cutting down the opposing commander for a personal slight. You may manipulate a neutral or friendly court to favor or oppose a military conflict happening elsewhere (you cannot, obviously, manipulate the court of your enemy). You must have at least five Allies of Devotion 2 or higher in the court, and must spend a week speaking and maneuvering in the court, after which you may make a roll of Courtier (Manipulation) / Awareness at TN 40. A successful roll awards a Free Raise on Battle Skill Rolls to the commander of the side you favor, with an additional such award granted for each Raise you make on the Courtier roll. If your activities are being opposed by a representative of the other side in the conflict, your Courtier roll becomes a Contested Roll against that opponent. You may only influence each military campaign with this Technique once (GM’s discretion), and each Free Raise is expended once the commander uses it. If the commander does not use the Free Raises by the end of the campaign, they are lost."}, {"id": "crane_children_of_doji_gild_the_lily", "nome": "Gild the Lily", "rank": 3, "descricao": "The Crane comprehend that the easiest way to maintain a strong network of allies is to regularly offer them favor. Conversely, the best way to flex your political muscle against an obstinate enemy is the denial of favor. You may grant any of your Allies a boon, which takes the form of any Social or Material Advantage with an Experience Point value of up to your Honor Rank. (The GM may veto any Advantage that seems inappropriate.) This is done by spending an hour in court speaking with the ally, then spending a Void Point and making a Courtier (Manipulation)/Awareness roll at a TN of 20 + (5x Experience Point value of Advantage). The effects of the boon last one month. You may use the same method to deny an enemy the effects of a Social Advantage they possess (limited to the same Experience Point cost). You converse with the court at large for an hour, then spend a Void Point and make a Contested Social Skill Roll of your Courtier (Manipulation) / Awareness versus the enemy’s Etiquette (Courtesy) / Awareness. With a success, the enemy cannot use that Advantage for one month. You may not target the same individual with this technique more than once a month."}], "livro": "Sword and Fan"}], "caminhos": [{"id": "crab_defender", "nome": "Crab Defender", "clanId": "crab", "tecnicas": [{"id": "crab_warrior_of_earth", "nome": "Warrior of Earth", "rank": 2, "descricao": "The Defenders are taught there is more than one way to win a duel. Rather than try to strike faster than their opponents, Defenders learn to call on their own Earth to endure the foe's first strike, allowing them to defeat their enemy in a longer fight. During the Strike step of an iaijutsu duel, you are considered to have additional Reduction equal to your Earth x3."}], "requisitos": [{"campo": "awareness", "tipo": "trait", "min": "3", "texto": "Awareness: 3"}, {"campo": "agility", "tipo": "trait", "min": "3", "texto": "Agility: 3"}, {"campo": "iaijutsu", "tipo": "skill", "min": "4", "texto": "Iaijutsu: 4"}, {"campo": "crab", "tipo": "tag", "min": null, "texto": "Member of Crab Clan"}, {"campo": "crab_the_way_of_the_crab", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_torchs_flame_flickers", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "crab_hiruma_snipers", "nome": "Hiruma Snipers", "clanId": "crab", "tecnicas": [{"id": "the_crabs_eye", "nome": "The Crab's Eye", "rank": 4, "descricao": "The Hiruma Snipers are trained to strike at specific weak points in their targets, getting their arrows past both mortal armor and monstrous shells and carapaces. You may attack with a yumi as a simple action. When making a ranged attack with a yumi, you may ignore all of the target's natural Reduction (e.g. Reduction from armor or natural protection) and half that much Reduction from magical effects."}], "requisitos": [{"campo": "reflexes", "tipo": "trait", "min": "4", "texto": "Reflexes: 4"}, {"campo": "kyujutsu", "tipo": "skill", "min": "3", "texto": "Kyujutsu: 5"}, {"campo": "crab_hummingbird_wings", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_veil_of_the_spirits", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "crab_falcons_strike", "nome": "The Falcon's Strike", "clanId": "crab", "tecnicas": [{"id": "the_crabs_eye", "nome": "Spotting the Prey", "rank": 2, "descricao": "The Falcon's Strike is taught to use the bushi's deep awareness of their surroundings to strike the target regardless of concealment. When making a ranged attack with a bow, you may use your Perception in place of your Reflexes for attack rolls. When using a yumi, you may also use your Perception in place of the bow's Strength for damage rolls."}], "requisitos": [{"campo": "kyujutsu", "tipo": "skill", "min": "3", "texto": "Kyujutsu (Yumi): 3"}, {"campo": "crab_the_falcons_eyes", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_torchs_flame_flickers", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_dance_the_razors_edge", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "crane_asahina_archer", "nome": "Asahina Archer", "clanId": "crane", "tecnicas": [{"id": "crane_no_regrets", "nome": "No Regrets", "rank": 4, "descricao": "Asahina Archers are taught to minimize the influence of their family's traditional pacifism and focus on defeating their enemies swiftly so that wars may be ended equally swiftly. Their technique allows them to call on their own inherent Air, delivering precisely accurate shots. When making an archery attack, you may make Called Shots for one less Raise (to a minimum of 1) and add half your Air (rounded down) in unkept dice to your attack rolls."}], "requisitos": [{"campo": "air", "tipo": "ring", "min": "3", "texto": "Air Ring: 3"}, {"campo": "kyujutsu", "tipo": "skill", "min": "5", "texto": "Kyujutsu: 5"}, {"campo": "crane", "tipo": "tag", "min": null, "texto": "Member of Crane Clan"}, {"campo": "crane_asahina", "tipo": "tag", "min": null, "texto": ""}, {"campo": "crane_daidoji", "tipo": "tag", "min": null, "texto": ""}, {"campo": "crane_strike_beneath_the_veil", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crane_breath_of_the_law", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "crane_daidoji_trading_council", "nome": "Daidoji Trading Council", "clanId": "crane", "tecnicas": [{"id": "crane_the_golden_path", "nome": "The Golden Path", "rank": 3, "descricao": "The members of the Trading Council are taught to detect virtually any possible opportunity for commercial gain, to exploit markets to their advantage, and to crush mercantile rivals from other clans. Once per month you may wage commercial warfare against a rival merchant by making a Contested Roll of Commerce (Merchant) / Awareness against the rival merchant patron. If you succeed, you inflict a loss on that merchant, a number of koku equal to the amount by which your roll exceeded theirs. If you lose the Contested Roll, you lose half that amount of koku. If the GM allows you to purchase additional Advantages (or Ranks in existing Advantages) after character creation, you may purchase Gentry, Wealthy, and Servants for 1 less Experience Point (to a minimum of 1)."}], "requisitos": [{"campo": "commerce", "tipo": "skill", "min": "3", "texto": "Commerce (Merchant): 3"}, {"campo": "crane", "tipo": "tag", "min": null, "texto": "Member of Crane Clan"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Gentry or Wealthy Advantage (may be waived by the GM for an individual who has distinguished himself as a merchant in other ways)"}, {"campo": "crane_doji_courtier_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_daidoji_iron_warriors", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_ob_daidoji_scout_school", "tipo": "school", "min": "2", "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "mantis_tsuruchi_master_bowman", "nome": "Tsuruchi Master Bowman", "clanId": "mantis", "tecnicas": [{"id": "the_way_of_the_archer", "nome": "The Way of the Archer", "rank": 6, "descricao": "Tsuruchi was perhaps the greatest archer in the history of Rokugan, and his final technique pushes the limits of what can be achieved with the bow. When using a bow, your range is increased by 150' (this is applied before applying the 50% range bonus for Kyujutsu Rank 5). Your Raises with a bow are no longer limited by your Void Ring (or Skill Rank if you have Great Potential), and you may perform Called Shots for half the normal number of Raises (rounded up)."}], "requisitos": [{"campo": "kyujutsu", "tipo": "skill", "min": "7", "texto": "Kyujutsu: 7"}, {"campo": "mantis_tsuruchis_eye", "tipo": "rule", "min": null, "texto": ""}, {"campo": "mantis_eyes_of_the_wasp", "tipo": "rule", "min": null, "texto": ""}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be selected by the Tsuruchi sensei to learn this Technique"}], "livro": "Book of Air (Livro do Ar)"}, {"id": "monks_kaze_do_fighter", "nome": "Kaze-Do Fighter", "clanId": "monks", "tecnicas": [{"id": "monks_the_way_of_air", "nome": "The Way of Air", "rank": 2, "descricao": "The students of Kaze’s ancient techniques learn how to use the speed of their opponents against them while evading enemy weapons. When you are fighting unarmed, any opponent attacking you with a melee weapon suffers a penalty of –Xk0 to his attacking Skill Roll, where X equals his Air Ring. This penalty cannot apply to more opponents within the same Round than your Insight Rank."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "3", "texto": "Jiujutsu (Kaze-do) 3"}, {"campo": "2", "tipo": "rank", "min": null, "texto": "Must be at Rank 2"}], "livro": "Book of Air (Livro do Ar)"}, {"id": "scorpion_saigos_blades", "nome": "Saigo's Blades", "clanId": "scorpion", "tecnicas": [{"id": "saigos_technique", "nome": "Saigo's Technique", "rank": 3, "descricao": "A true Scorpion duelist knows that intimidation and deception are the keys to victory. When dueling any opponent that you have previously used the Intimidation Skill upon successfully, you gain a bonus of +5 to the total of your roll during the Assessment Phase of the duel. Additionally, by spending a Void Point, you may report one statistic of your choice as being one rank higher during the Assessment Phase."}], "requisitos": [{"campo": "iaijutsu", "tipo": "skill", "min": "3", "texto": "Iaijutsu: 3"}, {"campo": "scorpion_pincers_and_tail", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "unicorn_yomanri_archer", "nome": "Unicorn Yomanri Archer", "clanId": "unicorn", "tecnicas": [{"id": "the_way_of_yomanri", "nome": "The Way of Yomanri", "rank": 4, "descricao": "Yomanri practitioners use a distinctive form of archery which relies on careful aiming rather than swift instinctive shooting. When using a yumi or dai-kyu, you may choose to spend one or more consecutive Simple Actions aiming your shot before you fire the arrow. Each such Simple Action awards either a +1k1 bonus to your attack roll or a +1k0 bonus to your damage roll (your choice). The maximum number of Simple Actions spent aiming cannot exceed your Agility Rank; moreover, if you are interrupted all benefits from the aiming are lost. This technique cannot be used while you are in the Center Stance."}], "requisitos": [{"campo": "agility", "tipo": "trait", "min": "4", "texto": "Agility: 4"}, {"campo": "kyujutsu", "tipo": "skill", "min": "5", "texto": "Agility: 5"}, {"campo": "unicorn_the_four_winds_strike", "tipo": "rule", "min": null, "texto": ""}, {"campo": "unicorn_desert_wind_strike", "tipo": "rule", "min": null, "texto": ""}, {"campo": "unicorn_sensing_the_breeze", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "taoist_archer", "nome": "Taoist Archer", "clanId": "various", "tecnicas": [{"id": "flight_of_innocence", "nome": "Flight of Innocence", "rank": 5, "descricao": "The Taoist Archers practice their art blindfolded. When making archery attacks, you ignore all TN and dice penalties for being Blind, for having a Missing Eye, or for the target being concealed by darkness, magical illusion, camouflage, and similar visual obstructions. Penalties for physical obstacles and obstructive conditions (such as the target being Prone, a normal or magical wind, etc.) are applied normally. In addition, when wielding a bow you may spend a Void Point for a +1k1 bonus on damage."}], "requisitos": [{"campo": "void", "tipo": "ring", "min": "4", "texto": "Void Ring: 4"}, {"campo": "meditation", "tipo": "skill", "min": "4", "texto": "Meditation: 4"}, {"campo": "lore_theology", "tipo": "skill", "min": "4", "texto": "Lore: Theology: 3"}, {"campo": "kyujutsu", "tipo": "skill", "min": "5", "texto": "Kyujutsu (Yumi): 5"}, {"campo": "ronin", "tipo": "tag", "min": null, "texto": ""}, {"campo": "monks_brotherhood", "tipo": "tag", "min": null, "texto": ""}, {"campo": "*monks_brotherhood", "tipo": "school", "min": "4", "texto": ""}, {"campo": "*ronin", "tipo": "school", "min": "4", "texto": ""}], "livro": "Book of Air (Livro do Ar)"}, {"id": "defender_of_the_brotherhood", "nome": "Defender of the Brotherhood", "clanId": "monks", "tecnicas": [{"id": "harmony_in_chaos", "nome": "Harmony in Chaos", "rank": 2, "descricao": "The power of Earth grants infinite patience and endurance, strengthening the inherent tranquillity of monastic reserve and thus allowing a Defender to deliver telling remarks within the courts. Any time you spend a Void Point on an Etiquette or Courtier Social Skill roll, you gain a bonus of +Xk1 to the roll (where X is your Willpower) instead of the normal +1k1."}], "requisitos": [{"campo": "willpower", "tipo": "trait", "min": "3", "texto": "Willpower 3"}, {"campo": "courtier", "tipo": "skill", "min": "3", "texto": "Courtier 3"}, {"campo": "Etiquette", "tipo": "skill", "min": "4", "texto": "Etiquette 4"}, {"campo": "*monks_brotherhood", "tipo": "school", "min": "1", "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "hiruma_slayers", "nome": "Hiruma Slayers", "clanId": "crab", "tecnicas": [{"id": "crab_deny_the_horde", "nome": "Deny the Horde", "rank": 4, "descricao": "The Slayer technique utilizes the masakari to deliver a terrifying barrage of precise and lethal blows on the foe, using it equally well in either hand. You suffer no penalties for using a masakari in your off-hand (although you still suffer normal penalties for wielding two weapons). You may attack as a Simple Action with a masakari. When using a masakari in the Full Attack Stance against any foe, or in the Attack Stance against a Shadowlands creature or a foe you know to be Tainted, you gain an additional +3k0 bonus to your damage rolls."}], "requisitos": [{"campo": "heavy_weapons", "tipo": "skill", "min": "5", "texto": "Heavy Weapons (Masakari)5"}, {"campo": "crab_hummingbird_wings", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_veil_of_the_spirits", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crab_sumai_wrestler", "nome": "Crab Sumai Wrestler", "clanId": "crab", "tecnicas": [{"id": "way_of_sumai", "nome": "Way of Sumai", "rank": 2, "descricao": "While most Rokugani treat Sumai wrestling as a sport, the Crab have never forgotten that it originated as a combat art. When rolling to control a Grapple, you gain a +1k0 bonus (+2k0 if you are Large). If you choose to inflict damage in a Grapple (e.g. the “hit” option), you gain a +1k1 bonus to the Damage Roll. Special: Enrolling in this Path automatically allows your character to get rid of the Small Disadvantage at no point cost. If you are not Small, you automatically gain Large at no point cost. If you are already Large, you are refunded the point cost of the Advantage."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "4", "texto": "Jiujtsu (Sumai) 4"}, {"campo": "crab_the_way_of_the_crab", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_the_way_of_the_carp", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crab_kaiu_siegemaster", "nome": "Kaiu Siegemaster", "clanId": "crab", "tecnicas": [{"id": "the_hammer_of_kaiu", "nome": "The Hammer of Kaiu", "rank": 5, "descricao": "During a siege, you may add or subtract your entire School Rank to the total of your rolls on the Mass Battle Table (this replaces the Kaiu Engineering Rank 4 ability to add or subtract half your School Rank). If you are on the defending side in a siege, you gain a +2k0 bonus to any Engineering (Siege) rolls you make to operate siege weaponry, and the Reduction of any structures on your side of the siege is increased by 50%."}], "requisitos": [{"campo": "battle", "tipo": "skill", "min": "5", "texto": "Battle (Mass Battle) 5"}, {"campo": "engineering", "tipo": "skill", "min": "5", "texto": "Engineering (Siege) 5"}, {"campo": "crab_the_path_of_war", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crab_crystal_masters", "nome": "Kuni Crystal Masters", "clanId": "crab", "tecnicas": [{"id": "strike_of_purity", "nome": "Strike of Purity", "rank": 2, "descricao": "The Crystal Masters learn how to awaken the spiritual power of crystal and use it to strengthen their spells. When you learn this technique, one piece of crystal which you possess becomes awakened and is then used to empower your spells with the essence of crystal. (If this piece of crystal is lost or destroyed, you cannot use this Technique until you acquire another one – it is the GM’s discretion how much time and effort this will require.)When casting a Fire or Earth spell that inflicts damage (e.g. Jade Strike, Fury of Osano-Wo, etc) you may spend a Void Point to channel the spell through your awakened crystal and infuse the spell with the essence of crystal. This adds one additional Complex Action to the casting time of the spell. The spell does an additional +1k1 damage and is now considered to be Crystal for the purpose of what foes can be damaged by it, whether it can penetrate Invulnerability or Creature Reduction, and so forth. Special: Must possess a piece of pure crystal. Player must have approval from GM to become a Crystal Master."}], "requisitos": [{"campo": "earth", "tipo": "ring", "min": "5", "texto": "Earth 5"}, {"campo": "spellcraft", "tipo": "skill", "min": "5", "texto": "Spellcraft 5"}, {"campo": "lore_elements", "tipo": "skill", "min": "5", "texto": "Lore:Elements (Crystal) 5"}, {"campo": "crab_kuni_shugenja", "tipo": "school", "min": "3", "texto": "Replaces Kuni Shugenja 4"}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crab_yasuki_extortionist", "nome": "Yasuki Extortionist", "clanId": "crab", "tecnicas": [{"id": "do_me_a_favor", "nome": "Do Me A Favor", "rank": 4, "descricao": "The Extortionists specialize in rooting out the financial weaknesses of potential customers and then pressuring them into calling on Yasuki assistance. If you have supplied something your target needs, whether money or material goods (this could be achieved through role-play and/or by using the Yasuki Rank 1 and Rank 3 Techniques), you may make a Contested Social Roll of your Intimidation (Control) / Willpower against their Etiquette (Courtesy) / Willpower. With a success, they find the arrangement has left them deeply in debt to you. You may either inflict an Obligation on that person (if the GM judges they have the ability to pay you back) or a Blackmail on them (if the GM judges they cannot pay you back). The default point value of the Disadvantage in either case is 3, but the GM may modify this if circumstances make it appropriate"}], "requisitos": [{"campo": "willpower", "tipo": "trait", "min": "4", "texto": "Willpower 4"}, {"campo": "commerce", "tipo": "skill", "min": "4", "texto": "Commerce 4"}, {"campo": "intimidation", "tipo": "skill", "min": "5", "texto": "Intimidation 5"}, {"campo": "crab_wiles_of_the_carp", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crab_the_severed_hand", "nome": "The Severed Hand", "clanId": "crab", "tecnicas": [{"id": "strength_of_bamboo", "nome": "Strength of Bamboo", "rank": 4, "descricao": "The former warriors of the Severed Hand have learned to rely on the indomitable strength of Earth to resist the tricks, temptations, and blandishments of enemy courtiers. When rolling to resist an opponent’s Social Skill or Courtier Technique, you may use Willpower as your Trait instead of the Trait normally used. In cases where this Technique clashes with another (such as the Bayushi Rank 4 Technique), the GM has discretion as to which Technique trumps the other. Special: Your character must be reassigned to the courts due to a physical inability to continue serving the clan in war, e.g. a debilitating injury (GM’s discretion, but obvious examples include Missing Limb and Lame)."}], "requisitos": [{"campo": "crab_two_pincers_one_mind", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_hummingbird_wings", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_fury_of_the_avalanche", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_veil_of_the_spirits", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_the_path_of_stone", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crane_daidoji_heavy_regulars", "nome": "Daidoji Heavy Regulars", "clanId": "crane", "tecnicas": [{"id": "crane_way_of_the_iron_crane", "nome": "Way of the Iron Crane", "rank": 4, "descricao": "The Heavy Regulars use their experience serving alongside the Crab on the Kaiu Wall to inform their own training in heavy weapons, enhancing their defensive position against enemy attacks and striking back hard against charging foes. When wielding a heavy weapon in the Attack stance, you may add +1k1 to your attack rolls against any opponent who is in the Attack or Full Attack Stances. When wielding a heavy weapon in the Defense or Full Defense stances, you may add your Heavy Weapons Skill Rank to your Armor TN."}], "requisitos": [{"campo": "heavy_weapons", "tipo": "skill", "min": "5", "texto": "Heavy Weapons 5"}, {"campo": "crane_strike_beneath_the_veil", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "dragon_tamori_weaponsmith", "nome": "Tamori Weaponsmith", "clanId": "dragon", "tecnicas": [{"id": "soul_of_the_stone", "nome": "Soul of the Stone", "rank": 2, "descricao": "A true Scorpion duelist knows that intimidation and deception are the keys to victory. When dueling any opponent that you have previously used the Intimidation Skill upon successfully, you gain a bonus of +5 to the total of your roll during the Assessment Phase of the duel. Additionally, by spending a Void Point, you may report one statistic of your choice as being one rank higher during the Assessment Phase."}], "requisitos": [{"campo": "craft_weaponsmithing", "tipo": "skill", "min": "3", "texto": "Craft: Weaponsmithing 3"}, {"campo": "dragon_tamori_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "katana_of_fire", "tipo": "spell", "min": null, "texto": ""}, {"campo": "tetsubo_of_earth", "tipo": "spell", "min": null, "texto": ""}, {"campo": "bo_of_water", "tipo": "spell", "min": null, "texto": ""}, {"campo": "yari_of_air", "tipo": "spell", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "fox_child of chikushudo", "nome": "Child of Chukushudo", "clanId": "fox", "tecnicas": [{"id": "born_of_the_earth", "nome": "Born of the Earth", "rank": 3, "descricao": "A master of earth’s intricacies can project his mind into the soil and be born again in the form of an animal. If you are sitting upon the bare earth, you may sacrifice two Earth spell slots and make a Meditation Skill Roll (TN 15). After ten minutes of meditation, you fall into a deep trance and a natural animal erupts forth from the ground before your body. Your mind inhabits and control this animal form until you choose to end the effect, your real body is harmed or disturbed, or the animal form is killed – in any of those circumstances, the animal form crumbles into dirt and your consciousness returns to your real body. You must choose any one natural animal, either from the Book of the Void in the L5R RPG core rulebook or Chapter One of the sourcebook Enemies of the Empire, as the form you adopt. If the animal form has higher physical or mental Trait Ranks than you, you use the animal form’s Traits – otherwise, you use your own. You gain any and all abilities of the creature, but cannot speak (and thus cannot cast spells) while in the animal’s body."}], "requisitos": [{"campo": "hunting", "tipo": "skill", "min": "3", "texto": "Hunting 3"}, {"campo": "lore_spirit_realms", "tipo": "skill", "min": "2", "texto": "Lore:Spirit Realms (Chikushudo) 2"}, {"campo": "fox_kitsune_shugenja", "tipo": "school", "min": "2", "texto": "Replaces Kitsune Shugenja 3"}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "lion_akodo_siege_strategist", "nome": "Akodo Siege Strategist", "clanId": "lion", "tecnicas": [{"id": "broken_by_tactics", "nome": "Broken by Tactics", "rank": 4, "descricao": "The Akodo family’s mastery of warfare does extend to sieges, and while their expertise in that domain is not so great as the Kaiu, they have attacked enough castles over the centuries to make it a specific topic of study at the Akodo War College. When you are on the attacking side in a siege, your expertise makes it easier for your side to overcome the castle’s defenses. When rolling on the Mass Battle Table under those circumstances, you always receive a Heroic Opportunity, regardless of the normal result. Any structures on the opposing side suffer a 50% penalty to their Reduction, due to your superior understanding of their weaknesses (this penalty is applied after any defending bonuses to their Reduction)."}], "requisitos": [{"campo": "battle", "tipo": "skill", "min": "6", "texto": "Battle (Mass Battle) 6"}, {"campo": "engineering", "tipo": "skill", "min": "4", "texto": "Engineering (Siege) 4"}, {"campo": "lion_the_eyes_of_the_general", "tipo": "rule", "min": null, "texto": ""}, {"campo": "lion_strength_of_my_ancestors", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "mantis_child of chikushudo", "nome": "Child of Chukushudo", "clanId": "mantis", "tecnicas": [{"id": "born_of_the_earth", "nome": "Born of the Earth", "rank": 3, "descricao": "A master of earth’s intricacies can project his mind into the soil and be born again in the form of an animal. If you are sitting upon the bare earth, you may sacrifice two Earth spell slots and make a Meditation Skill Roll (TN 15). After ten minutes of meditation, you fall into a deep trance and a natural animal erupts forth from the ground before your body. Your mind inhabits and control this animal form until you choose to end the effect, your real body is harmed or disturbed, or the animal form is killed – in any of those circumstances, the animal form crumbles into dirt and your consciousness returns to your real body. You must choose any one natural animal, either from the Book of the Void in the L5R RPG core rulebook or Chapter One of the sourcebook Enemies of the Empire, as the form you adopt. If the animal form has higher physical or mental Trait Ranks than you, you use the animal form’s Traits – otherwise, you use your own. You gain any and all abilities of the creature, but cannot speak (and thus cannot cast spells) while in the animal’s body."}], "requisitos": [{"campo": "hunting", "tipo": "skill", "min": "3", "texto": "Hunting 3"}, {"campo": "lore_spirit_realms", "tipo": "skill", "min": "2", "texto": "Lore:Spirit Realms (Chikushudo) 2"}, {"campo": "mantis_kitsune_shugenja", "tipo": "school", "min": "2", "texto": "Replaces Kitsune Shugenja 3"}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "mantis_yoritomo_sculptors", "nome": "Yoritomo Sculptors", "clanId": "mantis", "tecnicas": [{"id": "watanabes_legacy", "nome": "Watanabe's Legacy", "rank": 2, "descricao": "The Yoritomo Sculptors hone their wood-carving skills on ship-board before graduating to actual training in their organization’s tiny school. You gain a +1k1 bonus when using the Skills of Artisan: Sculpture and Craft: Sculpture, and you may ignore any circumstantial or environmental penalties (distractions, weather, noise, etc) to your rolls with those two Skills."}], "requisitos": [{"campo": "*mantis_bushi", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*mantis_courtier", "tipo": "school", "min": "1", "texto": ""}, {"campo": "artisan_sculpture", "tipo": "skill", "min": "4", "texto": "Artisan: Sculpture 4"}, {"campo": "craft_sculpture", "tipo": "skill", "min": "4", "texto": "Craft: Sculpture 4"}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "mantis_yoritomo_emissaries", "nome": "Yoritomo Emissaries", "clanId": "mantis", "tecnicas": [{"id": "intrepid_negotiator", "nome": "Intrepid Negotiator", "rank": 4, "descricao": "Where the standard Yoritomo training focuses on browbeating foes, the Emissary learns to leaven this aggression with the calm patience of the Earth, outlasting opponents’ anger and thus finding peaceful solutions to potentially violent confrontations. When making an Etiquette or Sincerity roll, you may spend a Void Point to add your Willpower in unkept dice to the roll. If the roll is specifically using Etiquette (Courtesy), you add your Willpower in kept dice instead."}], "requisitos": [{"campo": "etiquette", "tipo": "skill", "min": "4", "texto": "Etiquette (Courtesy) 4"}, {"campo": "mantis_command_the_winds", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "phoenix_shiba_armorsmith", "nome": "Shiba Armorsmiths", "clanId": "phoenix", "tecnicas": [{"id": "brilliant_steel", "nome": "Brilliant Steel", "rank": 2, "descricao": "A Shiba armorsmith is adept at the creation of beautiful armor, and consequently is also adept at using armor effectively on the battlefield. You gain a +1k0 bonus when making Craft rolls to create armor. When you are wearing armor and spend a Void Point to increase your Armor TN by 10, you may increase your Armor TN by an additional amount equal to twice your Earth Ring."}], "requisitos": [{"campo": "craft_armorsmithing", "tipo": "skill", "min": "3", "texto": "Craft: Armorsmithing 3"}, {"campo": "defense", "tipo": "skill", "min": "3", "texto": "Defense 3"}, {"campo": "phoenix_the_way_of_the_phoenix", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "unicorn_bariqu_wrestler", "nome": "Unicorn Bariqu Wrestler", "clanId": "unicorn", "tecnicas": [{"id": "way_of_the_ujikhai", "nome": "Way of the Ujik-Hai", "rank": 2, "descricao": "A bariqu wrestler relies on his use of unconventional locks, holds, and maneuvers to defeat his foes, rather than just on raw strength. If your opponent in a Grapple does not have the Bariqu Emphasis of Jiujutsu, you gain a bonus of +1k1 when rolling to control the Grapple. If you have a higher Agility Rank than your opponent in a Grapple, you gain a +2k0 bonus when rolling to control the Grapple. These bonuses stack with each other."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "3", "texto": "Jiujutsu (Bariqu) 3"}, {"campo": "unicorn_the_way_of_the_unicorn", "tipo": "rule", "min": null, "texto": ""}, {"campo": "unicorn_the_way_of_the_kirin", "tipo": "rule", "min": null, "texto": ""}, {"campo": "unicorn_purity_of_the_breath", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "unicorn_iuchi_couriers", "nome": "Iuchi Couriers", "clanId": "unicorn", "tecnicas": [{"id": "beyond_the_wind", "nome": "Beyond the Wind", "rank": 2, "descricao": "You can shape the Earth as you ride, lending speed and endurance to your steed. With a five minute ritual and a successful Meditation Skill Roll (TN 15), you may bless your horse or the horse of another rider. For a number of hours equal to your Earth Ring, the horse will never suffer movement penalties based on terrain, nor will it suffer the effects of fatigue. The maximum number of horses which may benefit from this Technique at the same time is equal to your Earth Ring."}], "requisitos": [{"campo": "horsemanship", "tipo": "skill", "min": "3", "texto": "Horsemanship 3"}, {"campo": "way_of_the_land", "tipo": "merit", "min": null, "texto": "Way of the land Advantage"}, {"campo": "unicorn_iuchi_shugenja", "tipo": "school", "min": "1", "texto": "Replaces Iuchi Shugenja 2"}], "livro": "Book of Earth (Livro da Terra)"}, {"id": "crab_knife_fighters_hiruma", "nome": "Crab Knife-Fighters (Hiruma)", "clanId": "crab", "tecnicas": [{"id": "crab_one_blade_both_hands", "nome": "One Blade, Both Hands", "rank": 3, "descricao": "The Crab knife-fighting technique emphasizes using the empty hand to grasp, control, and distract the opponent, setting him up for the knife hand to deliver the lethal blow. When fighting with one hand open and a tanto, you add 3k1 to your damage with tanto and may ignore all effects of your opponent's armor. (If your opponent is a creature with inherent Reduction, you may ignore 5 points of that Reduction.)"}], "requisitos": [{"campo": "knives", "tipo": "skill", "min": "3", "texto": "Knives 3"}, {"campo": "crab_wolfs_little_lesson", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_run_like_the_wind", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "crab_knife_fighters_hida", "nome": "Crab Knife-Fighters (Hida)", "clanId": "crab", "tecnicas": [{"id": "crab_one_blade_both_hands", "nome": "One Blade, Both Hands", "rank": 4, "descricao": ""}], "requisitos": [{"campo": "knives", "tipo": "skill", "min": "3", "texto": "Knives 3"}, {"campo": "crab_two_pincers_one_mind", "tipo": "rule", "min": null, "texto": ""}, {"campo": "crab_fury_of_the_avalanche", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "crab_student_of_hitsudo", "nome": "Student of Hitsu-Do", "clanId": "crab", "tecnicas": [{"id": "dragon_the_way_of_fire", "nome": "The Way of Fire", "rank": 2, "descricao": ""}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "4", "texto": "Jiujutsu (Hitsu-do) 4"}, {"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "crab_to_see_the_darkness", "tipo": "rule", "min": null, "texto": "Replaces Kuni Witch Hunter Rank 2"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must have access to a Hitsu-do dojo"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "asahina_fire_sculptor", "nome": "Asahina Fire Sculptor", "clanId": "crane", "tecnicas": [{"id": "the_inner_shape_of_fire", "nome": "The Inner Shape of Fire", "rank": 2, "descricao": "An Asahina Fire Sculptor is capable of creating beautiful but fleeting shapes rendered in fire, heat, light, or smoke. You may expend a Fire spell slot and make an Artisan (Sculpture) / Fire roll (base TN is 20, adjusted by the GM depending on the complexity of the sculpture being created). The sculpture will last a number of minutes equal to your Fire Ring, but requires full concentration during that time (i.e. you may do nothing except Free Actions). The sculpture vanishes instantly when the time elapses or you cease concentrating. The GM should award suitable Glory for a successful Fire sculpture “performance.” Special: A GM who wishes to represent the greater degree of control a Fire Sculptor has over the Element of Fire may opt to allow a Fire Sculptor to gain one Free Raise on a Fire spell once per day."}], "requisitos": [{"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "artisan", "tipo": "skill", "min": "2", "texto": "Artisan (Sculpture) 2"}, {"campo": "bat_komori_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "crane_asahina_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "crab_kuni_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "dragon_tamori_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "dragonfly_tonbo_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "fox_kitsune_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "imperial_seppun_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "lion_kitsu_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "mantis_moshi_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "mantis_kitsune_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "phoenix_isawa_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "phoenix_agasha_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "scorpion_soshi_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "snake_chuda_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "spider_chuda_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "unicorn_iuchi_shugenja_school", "tipo": "school", "min": "1", "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "dragon_hojatsus_legacy", "nome": "Hojatsu's Legacy", "clanId": "dragon", "tecnicas": [{"id": "dragon_strike_when_you_cannot", "nome": "Strike When You Cannot", "rank": 4, "descricao": "The student of Hojatsu's last technique learns how to use intellect and aggression to disrupt an opponent's rythm in an iaijutsu duel. During the Assessment stage of a duel, you may take a Free Action and spend a Void Point to force a Contested Kenjutsu /Fire roll with your opponent. If you win the roll, your opponent cannot spend Void Points on the Focus roll for that duel."}], "requisitos": [{"campo": "iaijutsu", "tipo": "skill", "min": "5", "texto": "Iaijutsu 5"}, {"campo": "dragon_strong_and_swift", "tipo": "rule", "min": null, "texto": ""}, {"campo": "dragon_master_of_steel", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "dragon_student_of_hitsudo", "nome": "Student of Hitsu-Do", "clanId": "dragon", "tecnicas": [{"id": "dragon_the_way_of_fire", "nome": "The Way of Fire", "rank": 2, "descricao": "The practitioner of Hitsu-do learns to harness his inner Fire chi, using it to empower his strikes - but this has a price, since such use of one's own Fire is also harmful. When making an unarmed attack, you may opt to call on your inner fire, but you suffer Wounds equal to your Fire x2. (Any Wound Penalties from this damage are applied after your attack roll is completed.) In return, your unarmed damage for that attack has a base DR of 0k[Fire] instead of 0k1. (This does not stack with the unarmed damage bonus from the Advantage Hands of Stone.) For mechanical purposes, using the Hitsu-do technique as using a Mystical Kiho. Special: The Hitsu-do makes it easier for its students to master the ways of Fire. Your Fire Ring is considered to be 1 Rank higher for the purpose of learning Fire Kiho."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "4", "texto": "Jiujutsu (Hitsu-do) 4"}, {"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "dragon_the_gift_of_the_lady", "tipo": "rule", "min": null, "texto": "Replaces Kikage Zumi Rank 2"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must have access to a Hitsu-do dojo"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "dragon_the_transcendent_brotherhood", "nome": "The Transcendent Brotherhood", "clanId": "dragon", "tecnicas": [{"id": "dragon_apotheosis_of_fire", "nome": "Apotheosis of Fire", "rank": 2, "descricao": "Members of the Transcendent Brotherhood seek to use pain as a means of achieving clarity of thought and spirit. Once per day, you may spend at least one hour in deep meditation and make a Meditation / Fire Roll against a TN 20. With a success, you harden yourself against physical harm done by fire and heat, although you still feel all the pain of being burned. (GMs may opt to impose partial or temporary TN penalties to represent the effects of the pain.) For a number of hours equal to your Fire Ring, you are immune to damage from normal, mundane fires and heat (not magica or extreme natural heat sources such as molten lava). One Raise on this Meditation roll will make you immune to magical sources of fire; two Raises will make you immune to damage from any source of fire, even a volcano. While experiencing the pain of being burned, and for ten minutes afterward, your intense focus and clarity of thought grant you a bonus equal to your Fire Ring to the total of all Awareness, Perception and Intelligence-based Trait and Skill Rolls."}], "requisitos": [{"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "earth", "tipo": "ring", "min": "3", "texto": "Earth 3"}, {"campo": "meditation", "tipo": "skill", "min": "3", "texto": "Meditation 3"}, {"campo": "dragon_blood_of_the_kami", "tipo": "rule", "min": null, "texto": ""}, {"campo": "dragon_the_gift_of_the_lady", "tipo": "rule", "min": null, "texto": ""}, {"campo": "dragon_swift_fist_subtle_heart", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "hare_ujina_skirmishers", "nome": "Ujina Skirmishers", "clanId": "hare", "tecnicas": [{"id": "hare_master_of_the_quick_blade", "nome": "Master of the Quick Blade", "rank": 3, "descricao": "The Ujina are trained to fight with a tanto in each hand, cutting their foes to death with swift and deadly strikes. When fighting with a knife in each hand, you gain a +1k0 bonus to your Initiative rolls and a +1k1 bonus to damage rolls with knives."}], "requisitos": [{"campo": "knives", "tipo": "skill", "min": "3", "texto": "Knives (Tanto) 3"}, {"campo": "hare_speed_of_the_hare", "tipo": "rule", "min": null, "texto": "Replaces Hare Bushi 2"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "lion_the_ikoma_historians", "nome": "The Ikoma Historians", "clanId": "lion", "tecnicas": [{"id": "lion_the_past_and_the_present", "nome": "The Past and the Present", "rank": 3, "descricao": "The Ikoma Historians are tasked with comprehensively recording the official histories of the Empire - and also with concealing inconvenient aspects of that history. You are expected to always be ready to record the events around you, and as such you are trained to memorize and perfectly recall anything worty of inclusion in the historical records. When you take this Path, you acquire the Advantage Forbidden Knowledge (Empire's True History). You gain a Free Raise on all Calligraphy rolls and you may roll Lore: History / Intelligence at TN 25 to accurately recount any incident you have witnessed and any story you have heard, down to the smallest detail - including details you may have missed at the time."}], "requisitos": [{"campo": "lore_history", "tipo": "skill", "min": "5", "texto": "LOre: History 5"}, {"campo": "lion_the_heart_of_the_lion", "tipo": "rule", "min": null, "texto": ""}, {"campo": "lion_the_lion_cannot_fail", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "mantis_whirlwind_fighters", "nome": "Mantis Whirlwind Fighters", "clanId": "mantis", "tecnicas": [{"id": "mantis_waves_rush_to_shore", "nome": "Waves Rush to Shore", "rank": 4, "descricao": "Whirlwind Fighters are a constant blur of motion, using their swift and relentless strikes both to deflect their opponents' attack and to break through their defenses. When fighting with a kama in each hand, you may add your Knives Skill Rank to your Armor TN, and gain a bonus of 3k0 to your damage rolls with kama."}], "requisitos": [{"campo": "knives", "tipo": "skill", "min": "5", "texto": "Knives (Kama) 5"}, {"campo": "mantis_strike_of_the_mantis", "tipo": "rule", "min": null, "texto": "Replaces Yoritomo Bushi 4"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "monks_student_of_hitsudo", "nome": "Student of Hitsu-Do", "clanId": "monks", "tecnicas": [{"id": "monks_the_way_of_fire", "nome": "The Way of Fire", "rank": 2, "descricao": "The practitioner of Hitsu-do learns to harness his inner Fire chi, using it to empower his strikes - but this has a price, since such use of one's own Fire is also harmful. When making an unarmed attack, you may opt to call on your inner fire, but you suffer Wounds equal to your Fire x2. (Any Wound Penalties from this damage are applied after your attack roll is completed.) In return, your unarmed damage for that attack has a base DR of 0k[Fire] instead of 0k1. (This does not stack with the unarmed damage bonus from the Advantage Hands of Stone.) For mechanical purposes, using the Hitsu-do technique as using a Mystical Kiho. Special: The Hitsu-do makes it easier for its students to master the ways of Fire. Your Fire Ring is considered to be 1 Rank higher for the purpose of learning Fire Kiho."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "4", "texto": "Jiujutsu (Hitsu-do) 4"}, {"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "monks", "tipo": "rule", "min": null, "texto": "Must be a Brotherhood Monk"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be at Rank 2"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must have access to a Hitsu-do dojo"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "phoenix_student_of_hitsudo", "nome": "Student of Hitsu-Do", "clanId": "phoenix", "tecnicas": [{"id": "phoenix_the_way_of_fire", "nome": "The Way of Fire", "rank": 2, "descricao": "The practitioner of Hitsu-do learns to harness his inner Fire chi, using it to empower his strikes - but this has a price, since such use of one's own Fire is also harmful. When making an unarmed attack, you may opt to call on your inner fire, but you suffer Wounds equal to your Fire x2. (Any Wound Penalties from this damage are applied after your attack roll is completed.) In return, your unarmed damage for that attack has a base DR of 0k[Fire] instead of 0k1. (This does not stack with the unarmed damage bonus from the Advantage Hands of Stone.) For mechanical purposes, using the Hitsu-do technique as using a Mystical Kiho. Special: The Hitsu-do makes it easier for its students to master the ways of Fire. Your Fire Ring is considered to be 1 Rank higher for the purpose of learning Fire Kiho."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "4", "texto": "Jiujutsu (Hitsu-do) 4"}, {"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "phoenix_the_four_mysteries", "tipo": "rule", "min": null, "texto": "Replaces Asako Henshin Rank 2"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must have access to a Hitsu-do dojo"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "phoenix_agasha_alchemists", "nome": "Agasha Alchemists", "clanId": "phoenix", "tecnicas": [{"id": "phoenix_fury_of_the_elements", "nome": "Fury of the Elements", "rank": 3, "descricao": "You may store a Fire spell with the Area of Effect \"one target person\" or \"one target creature\" in an alchemical preparation for later use. The stored spell may be activated instantly by anyone as either a Simple Action (to drink a potion) or a Complex Action (to throw it, using Athletics (Throwing) / Agility). By spending a Spell Slot for another Element (except Void), you may also give a spell stored in this manner an additional Elemental keyword. For example, by spending an Earth slot, you could cause the stored spell to be both Fire and Earth, or just Earth, for all purposes related to the type of Elemental keyword associated with the spell. A spell may only be given one additional Elemental keyword this way."}], "requisitos": [{"campo": "spellcraft", "tipo": "skill", "min": "3", "texto": "Spellcraft 3"}, {"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "phoenix_elements_of_all_things", "tipo": "rule", "min": null, "texto": "Must be Agasha Shugenja"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be Rank 3"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "phoenix_the_inferno_guard", "nome": "The Inferno Guard", "clanId": "phoenix", "tecnicas": [{"id": "phoenix_menacing_flames", "nome": "Menacing Flames", "rank": 3, "descricao": "Members of the Inferno Guard learn how to employ certain Fire spells to maximize the apparent threat they represent to opponents. When casting any Fire spell that does not list \"one target creature\" or \"one target individual\" as its Area of Effect, you may spend a Void Point or expend an additional Spell Slot to give the spell an additional effect of Fear X, where X is the Mastery Level of the spell."}], "requisitos": [{"campo": "battle", "tipo": "skill", "min": "3", "texto": "Battle (Mass Battle) 3"}, {"campo": "fire", "tipo": "ring", "min": "3", "texto": "Fire 3"}, {"campo": "phoenix_isawas_gift", "tipo": "rule", "min": null, "texto": "Must be Isawa Shugenja"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be at Rank 2 with a Fire Affinity"}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "scorpion_shosuro_assassins", "nome": "Shosuro Assassins", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_the_hidden_blade", "nome": "The Hidden Blade", "rank": 6, "descricao": "The Assassins are the elite killers of the Shosuro shinobi orders, trained to kill their targets with a single precise stab or slice. When attacking a surprised or unaware opponent with a knife, you may activate this Technique by spending a Void Point (as a Free Action). Your attack will target a vital spot, and any Raises for damage you make on that target are kept dice (+1k1 per Raise) insted of unkept (+1k0)."}], "requisitos": [{"campo": "stealth", "tipo": "skill", "min": "5", "texto": "Stealth 5"}, {"campo": "knives", "tipo": "skill", "min": "5", "texto": "Knives 5"}, {"campo": "scorpion_the_final_silence", "tipo": "rule", "min": null, "texto": ""}, {"campo": "scorpion_the_third_face", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Fire (Livro do Fogo)"}, {"id": "monks_abbot", "nome": "Abbot", "clanId": "monks", "tecnicas": [{"id": "the_reverence_of_wisdom", "nome": "The Reverence of Wisdom", "rank": 4, "descricao": "Your fellow monks have chosen to honor you by elevating you to the position of abbot at your monastery. Within the Brotherhood, you are now considered to be Status 4.0. When interacting with members of your own Order, you gain +1k1 to all Social Skill rolls (except Temptation). With outsiders of all types, you add +1k0 to those rolls instead. Note: If the GM is using the Duty Points system from Appendix One of the L5R 4th Edition supplement Emerald Empire, this Path awards 10 Duty Points."}], "requisitos": [{"campo": "*monks_brotherhood", "tipo": "school", "min": "3", "texto": ""}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "monks_order_of_ebisu", "nome": "Order of Ebisu", "clanId": "monks", "tecnicas": [{"id": "the_voice_of_humility", "nome": "The Voice of Humility", "rank": 3, "descricao": "The monks of the Order of Ebisu spend their time among the peasants, seeking enlightenment by sharing the simple work of the heimin. However, on those occasions when they offer counsel to the samurai caste or make appeals on behalf of the peasants, their humble labors grant them an aura of serene enlightened harmony which even the most stubborn or callous samurai finds difficult to resist. In order to use this Technique, you must spend time working alongside the peasants at humble tasks (e.g. utilizing the Craft Skills associated with this Path). For each week you spend laboring in this manner, you gain a bonus Void Point which you may only spend on those Craft Skills, on Medicine Skill Rolls made to help peasants/hinin, or on Social Skill Rolls made against samurai. The maximum number of these bonus Void Points you may “hold” are equal to your Void Rank."}], "requisitos": [{"campo": "courtier", "tipo": "skill", "min": "3", "texto": "Courtier 3"}, {"campo": "monks_the_temples_of_the_thousand_fortunes_monk_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "monks_order_of_jurojins_blessing", "tipo": "school", "min": "2", "texto": ""}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "phoenix_sesai_ninja", "nome": "Sesai Ninja", "clanId": "phoenix", "tecnicas": [{"id": "anything_for_the_phoenix", "nome": "Anything for the Phoenix", "rank": 2, "descricao": "When on a battlefield, you gain +1k1 to all Stealth rolls and a Free Raise on all attack rolls made by surprise. When performing dishonorable acts on behalf of the Phoenix Clan, you lose half the normal amount of Honor (rounded up)."}], "requisitos": [{"campo": "stealth", "tipo": "skill", "min": "3", "texto": "Stealth 3"}, {"campo": "phoenix_shiba_bushi_school", "tipo": "school", "min": "1", "texto": ""}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "phoenix_dragon_channeler", "nome": "Dragon Channeler", "clanId": "phoenix", "tecnicas": [{"id": "beseech_the_dragons", "nome": "Beseech The Dragons", "rank": 6, "descricao": "You lose any Affinities and Deficiencies you had prior to becoming a Dragon Channeler, instead gaining an Affinity for Dragon spells. Your normal spell slots are reduced by 2 in each Ring; in return, you gain three “Dragon Spell Slots” which can only be used to invoke the powers of the Dragons via Dragon Spells. You may spend Void Points to cast additional Dragon spells when your slots are exhausted. Dragon spell slots do not recover from rest – you may only regain them by sustained meditation (two hours of uninterrupted meditation and Meditation/ Void at TN 30 to regain one slot). GM’s Option: Some GMs may wish to create a connection between the Dragon Channelers and the Chosen by the Oracles Advantage (due to the link between the Oracles and the Dragons). If this is desired, a character with Chosen by the Oracles starts with four Dragon Spell slots rather than three."}], "requisitos": [{"campo": "*any", "tipo": "ring", "min": "5", "texto": "Any Ring at Rank 5"}, {"campo": "*any", "tipo": "ring", "min": "4", "texto": "Any Ring at Rank 4"}, {"campo": "*any", "tipo": "ring", "min": "4", "texto": "Any Ring at Rank 4"}, {"campo": "meditation", "tipo": "skill", "min": "5", "texto": "Meditation 5"}, {"campo": "spellcraft", "tipo": "skill", "min": "5", "texto": "Spellcraft 5"}, {"campo": "lore_theology", "tipo": "skill", "min": "5", "texto": "Lore: Theology 5"}, {"campo": "more", "tipo": "rpg", "min": null, "texto": "Either personally chosen by the Elemental Dragons or personally trained by an existing Dragon Channeler."}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "ronin_hateru_ninja", "nome": "Hateru Ninja", "clanId": "ronin", "tecnicas": [{"id": "the_false_dragon", "nome": "The False Dragon", "rank": 2, "descricao": "The Hateru specialize in pretending to be Dragon samurai, and have actually infiltrated the Kitsuki family in order to keep tabs on the clan. When using the Acting Skill to play the role of a Dragon samurai, you gain a +2k1 bonus. You gain a Free Raise on any Skill roll made for the purpose of either avoiding leaving clues to your identity or creating false clues to lead enemies away from you."}], "requisitos": [{"campo": "acting", "tipo": "skill", "min": "3", "texto": "Acting 3"}, {"campo": "stealth", "tipo": "skill", "min": "3", "texto": "Stealth 3"}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "ronin_the_ghosts_of_the_forest", "nome": "The Ghosts of the Forest", "clanId": "ronin", "tecnicas": [{"id": "walk_among_the_trees", "nome": "Walk Among the Trees", "rank": 2, "descricao": "The enigmas of the forest at Nazo Mori are more familiar to you than almost anyone else in the Empire. Whenever you are within a woodland area, you gain a Free Raise on all Athletics, Hunting, and Stealth Rolls. If you are within sight of Nazo Mori, you also gain a bonus of +1k0 on any roll involving the Perception Trait (these effects can stack)."}], "requisitos": [{"campo": "lore_spirit_realms", "tipo": "skill", "min": "2", "texto": "Lore: Spirit Realms 2"}, {"campo": "way_of_the_land", "tipo": "merit", "min": null, "texto": "Way of the land Advantage"}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "scorpion_fading_shadows", "nome": "Fading Shadows", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_unravel_the_shadow", "nome": "Unravel The Shadow", "rank": 5, "descricao": "The shugenja of the Fading Shadows are trained to perceive the lies and distortions of the Nothing and to disrupt the powers of the Shadowspawn by exploiting their vulnerability to the Void. As a Simple Action, you may spend a Void Point to try to strip away the false identity of any Shadowspawn and other minions of the Nothing within your sight, revealing them for what they are. This requires a Contested Roll of your Void against their Willpower. With a success, the creatures are revealed as what they truly are, and are unable to reassume a false identity as long as they remain in your sight. As a Free Action, you may spend a Void Point when you cast a spell or make a physical attack. That spell/attack will have full effect on a minion of the Nothing, regardless of normal resistances or immunities."}], "requisitos": [{"campo": "void", "tipo": "ring", "min": "4", "texto": "Void 4"}, {"campo": "spellcraft", "tipo": "skill", "min": "5", "texto": "Spellcraft 5"}, {"campo": "forbidden_knowledge_lying_darkness", "tipo": "merit", "min": null, "texto": "Forbidden Knowledge (Lying Darkness)"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be inducted into the Hidden Moon Dojo (exact circumstances up to the GM, but only Scorpion characters of irreproachable loyalty and discretion will even be considered)"}, {"campo": "*scorpion_shugenja", "tipo": "school", "min": "4", "texto": "Replaces any Scorpion shugenja 5"}], "livro": "Book of Void (Livro do Vazio)"}, {"id": "monks_the_servants_of_mercy", "nome": "The Servants of Mercy", "clanId": "monks", "tecnicas": [{"id": "monks_mercys_touch", "nome": "Mercy's Touch", "rank": 4, "descricao": "So long as you remain absolutely pacifistic and aid all victims with equal care, your Medicine rolls heal an additional +2k1 Wounds. If you ever forsake the path of absolute pacifism (that is, if you ever voluntarily engage in violence against another creature) you lose this benefit forever. You may not learn any Kiho this Rank."}], "requisitos": [{"campo": "medicine", "tipo": "skill", "min": "5", "texto": "Medicine (Wound Treatment) 5"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Oath of absolute pacifism"}, {"campo": "*monks_monk", "tipo": "school", "min": "3", "texto": ""}, {"campo": "monks_order_of_jurojins_blessing", "tipo": "school", "min": "3", "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "crane_student_of_mizu_do", "nome": "Student of Mizu-Do", "clanId": "crane", "tecnicas": [{"id": "the_way_of_water", "nome": "The Way of Water", "rank": 3, "descricao": "Masters of Mizu-do techniques are able to avoid nearly any strike, subduing their attackers by using their own strength against them. When performing a Grapple, you use your opponent’s Strength Rank in place of your own. While you are in the Defense or Full Defense stance, when a melee attack misses you, you may immediately take a Free Action to spend a Void Point and make a Jiujutsu (Mizu-do) / Strength roll against a TN of the opponent’s attack roll, but using the opponent’s Strength Rank in place of your own. If you succeed in this roll, you may either immediately Throw the opponent (as per the option in Grappling) or immediately take control of a Grapple against the opponent."}], "requisitos": [{"campo": "jiujutsu", "tipo": "skill", "min": "4", "texto": "Jiujutsu (Mizu-Do) 4"}, {"campo": "water", "tipo": "ring", "min": "3", "texto": "Water 3"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Access to a Mizu-do sensei"}, {"campo": "*monks_brotherhood", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_doji_courtier_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_ob_kakita_artisan_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_asahina_shugenja_school", "tipo": "school", "min": "2", "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "crane_daidoji_spy_master", "nome": "Daidoji Spy Master", "clanId": "crane", "tecnicas": [{"id": "crane_truth_in_shadows", "nome": "Truth in Shadows", "rank": 3, "descricao": "You gain the Spy Network Advantage for no points; if you already possess Advantage, you may use it twice as this often. You gain a +2k0 bonus to Stealth, Investigation, and Temptation rolls. When you use Low Skills or otherwise perform moderately dishonorable actions on behalf of the Crane Clan, you lose half the normal amount of Honor, rounded up (you still lose normal amounts of Honor for actions which are not for the Crane and for truly heinous actions like murder, betrayal, or blasphemy)."}], "requisitos": [{"campo": "crane_daidoji", "tipo": "tag", "min": null, "texto": "Must be a member of the Daidoji family"}, {"campo": "crafty", "tipo": "merit", "min": null, "texto": ""}, {"campo": "honor", "tipo": "trait", "min": null, "texto": ""}, {"campo": "crane_daidoji_iron_warrior_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_daidoji_scout", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crane_doji_courtier_school", "tipo": "school", "min": "2", "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "dragon_kitsukis_eye", "nome": "Kitsuki's Eye", "clanId": "dragon", "tecnicas": [{"id": "dragon_the_eye_sees_all", "nome": "The Eye Sees All", "rank": 6, "descricao": "Your ability to perceive details and recognize their significance has been refined to the point of seeming preternatural. Any time you enter an area (room, courtyard, garden, etc), you may spend a Void Point and take a minute to observe the area, after which you make a Perception Roll at TN 25. With a success, you spot any tracks, handprints, out-of-place items, or other such visual clues in the area. You may call a Raise on the roll to gain additional clues (GM’s choice as to what they are) from other senses, such as hearing and scent (one Raise per sense). You may call two Raises to know if there is anything physically hidden in the area (although you will not know exactly where it is). You are also extremely difficult to surprise. You gain a bonus of +2k2 to any rolls made to avoid being surprised."}], "requisitos": [{"campo": "dragon_the_eyes_betray_the_heart", "tipo": "rule", "min": null, "texto": "Must attain Rank 5 in the Kitsuki Investigator School and be recruited into the Eye by its sensei."}], "livro": "Book of Water (Livro da Água)"}, {"id": "imperial_seppun_astrologer", "nome": "Seppun Astrologers", "clanId": "imperial", "tecnicas": [{"id": "imperial_the_wisdom_of_the_heavens", "nome": "The Wisdom of the Heavens", "rank": 4, "descricao": "The sage-priests of the Seppun Astrologers are capable of finding great wisdom in the alignments of the Celestial Heavens, and their recognition of previously unnoticed patterns can bring joy… or doom… to the mortal world. Once per month, you may clarify a person’s place in the great tapestry of fate and thereby confer one Spiritual Advantage or Spiritual Disadvantage on that person. (This is a ritual effect and cannot be performed during a skirmish.) This effect lasts for one month or until you use this Technique on a different person, whichever comes first. If you are attempting to confer a Disadvantage, you must also succeed at a Contested Void Roll against the target."}], "requisitos": [{"campo": "divination", "tipo": "skill", "min": "4", "texto": "Divination (Astrology) 4"}, {"campo": "lore_omens", "tipo": "skill", "min": "5", "texto": "Lore: Omens 5"}, {"campo": "imperial_seppun_shugenja_school", "tipo": "school", "min": "3", "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "lion_disciples_of_the_river", "nome": "Disciples of the River", "clanId": "lion", "tecnicas": [{"id": "lion_servant_of_the_river", "nome": "Servant of the River", "rank": 3, "descricao": "The Disciples of the River take the concept of Water magic much more literally than do most of the Kitsu family. Their approach is more like that of a Phoenix, although none would ever admit such (and they would be insulted by the comparison). When casting a Water spell while standing within one hundred feet of a naturally occurring river, you gain one Free Raise on that spell."}], "requisitos": [{"campo": "lion_kitsu_shugenja_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "way_of_the_land", "tipo": "merit", "min": null, "texto": "Way of the land Advantage for an area with a river."}], "livro": "Book of Water (Livro da Água)"}, {"id": "mantis_student_of_cliffs_edge", "nome": "Student of Cliff's Edge", "clanId": "mantis", "tecnicas": [{"id": "howl_of_the_cliffs_edge_3", "nome": "Howl of the Cliff's Edge", "rank": 3, "descricao": "The Mantis who train at Cliff’s Edge Dojo are particularly fond of using the kusarigama to trip, disarm, and otherwise disable their foes. When using a kusarigama to make a Knockdown or Disarm maneuver, you gain a +2k1 bonus to your attack roll. You may call three Raises on an attack with a kusarigama to Entangle an opponent up to 15’ away (as per the Entangled condition in the L5R 4th Edition Core rulebook, page 89). The condition lasts until you voluntarily release the foe (as a Free Action), or the foe succeeds in a Contested Strength Roll against you (as a Simple Action)."}, {"id": "howl_of_the_cliffs_edge_4", "nome": "Howl of the Cliff's Edge", "rank": 4, "descricao": "The Mantis who train at Cliff’s Edge Dojo are particularly fond of using the kusarigama to trip, disarm, and otherwise disable their foes. When using a kusarigama to make a Knockdown or Disarm maneuver, you gain a +2k1 bonus to your attack roll. You may call three Raises on an attack with a kusarigama to Entangle an opponent up to 15’ away (as per the Entangled condition in the L5R 4th Edition Core rulebook, page 89). The condition lasts until you voluntarily release the foe (as a Free Action), or the foe succeeds in a Contested Strength Roll against you (as a Simple Action)."}], "requisitos": [{"campo": "agility", "tipo": "trait", "min": "4", "texto": "Agility: 4"}, {"campo": "chain_weapons", "tipo": "skill", "min": "5", "texto": "Chain Weapons: 5"}, {"campo": "mantis_strike_of_the_mantis", "tipo": "rule", "min": null, "texto": ""}, {"campo": "mantis_no_prey_escapes", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "dragonfly_kawaru_sages", "nome": "Kawaru Sages", "clanId": "dragonfly", "tecnicas": [{"id": "phoenix_the_veil_of the_future", "nome": "The Veil of the Future", "rank": 2, "descricao": "The Kawaru Sages have mastered the art of reading the sixty-four hexagrams of kawaru in order to divine what will happen in the near future, enhancing their forecasts with the aid of the kami of Water. At the beginning of each day, you may spend one hour in meditation and make a Divination Skill Roll, at a basic TN of 15. If successful, you gain a +1k0 bonus die, and you may Raise on the roll to gain addition bonus dice up to your Water Ring. You may spend these +1k0 bonus dice on any Spell Casting Rolls made during the rest of the day. Unused dice are lost at nightfall."}], "requisitos": [{"campo": "divination", "tipo": "skill", "min": "3", "texto": "Divination (Kawaru) 3"}, {"campo": "drgonfly_tonbo_shugenja_school", "tipo": "school", "min": "1", "texto": "Replaces Tonbo Shugenja 2"}], "livro": "Book of Water (Livro da Água)"}, {"id": "phoenix_the_acolytes_of_snow", "nome": "The Acolytes of Snow", "clanId": "phoenix", "tecnicas": [{"id": "phoenix_the_maidens_icy_grasp", "nome": "The Maiden's Icy Grasp", "rank": 2, "descricao": "The Acolytes of Snow recognize that the icy touch of the Snow Maiden allows Water to mirror the strength and power of Earth. You may cast the following Earth spells as Water spells: Armor of Earth, Armor of the Emperor, Be the Mountain, Bonds of Ningen-do, Earth’s Stagnation, Grasp of Earth, Major Binding, Minor Binding, and Wall of Earth. The spells create their physical effects from ice instead of from earth or stone, and the Acolytes usually rename these spells to incorporate “Ice” into their titles."}, {"id": "phoenix_the_maidens_icy_grasp", "nome": "The Maiden's Icy Grasp", "rank": 3, "descricao": "The Acolytes of Snow recognize that the icy touch of the Snow Maiden allows Water to mirror the strength and power of Earth. You may cast the following Earth spells as Water spells: Armor of Earth, Armor of the Emperor, Be the Mountain, Bonds of Ningen-do, Earth’s Stagnation, Grasp of Earth, Major Binding, Minor Binding, and Wall of Earth. The spells create their physical effects from ice instead of from earth or stone, and the Acolytes usually rename these spells to incorporate “Ice” into their titles."}], "requisitos": [{"campo": "lore_yuki_no_onna", "tipo": "skill", "min": "3", "texto": ""}, {"campo": "water", "tipo": "affinity", "min": null, "texto": ""}, {"campo": "phoenix_isawa_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*phoenix_shugenja", "tipo": "school", "min": "2", "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "phoenix_kawaru_sages", "nome": "Kawaru Sages", "clanId": "phoenix", "tecnicas": [{"id": "phoenix_the_veil_of the_future", "nome": "The Veil of the Future", "rank": 2, "descricao": "The Kawaru Sages have mastered the art of reading the sixty-four hexagrams of kawaru in order to divine what will happen in the near future, enhancing their forecasts with the aid of the kami of Water. At the beginning of each day, you may spend one hour in meditation and make a Divination Skill Roll, at a basic TN of 15. If successful, you gain a +1k0 bonus die, and you may Raise on the roll to gain addition bonus dice up to your Water Ring. You may spend these +1k0 bonus dice on any Spell Casting Rolls made during the rest of the day. Unused dice are lost at nightfall."}], "requisitos": [{"campo": "divination", "tipo": "skill", "min": "3", "texto": "Divination (Kawaru) 3"}, {"campo": "*phoenix_shugenja", "tipo": "school", "min": "1", "texto": "Replaces any Phoenix Shugenja 2"}], "livro": "Book of Water (Livro da Água)"}, {"id": "ronin_the_scales_of_the_carp", "nome": "The Scales of the Carp", "clanId": "ronin", "tecnicas": [{"id": "ronin_swimming_beneath_the_waves", "nome": "Swimming Beneath the Waves", "rank": 3, "descricao": "The Scales of the Carp operate beneath the level where most samurai take notice, and are adept at convincing the authorities – especially those on either side of the Crab-Crane border – to ignore their activities. You gain a +1k0 bonus to all Temptation (Bribery) rolls. If the roll is against a Crab or Crane samurai, the bonus is +1k1 instead, and if the samurai agrees to the bribe you may (with the GM’s permission) spend a Void Point to gain him as an Ally with 1 point of Devotion. He will remain an Ally permanently unless you betray him or otherwise break the alliance."}], "requisitos": [{"campo": "commerce", "tipo": "skill", "min": "3", "texto": "Commerce 3"}, {"campo": "lore_underworld", "tipo": "skill", "min": "3", "texto": "Lore: Underworld 3"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be recruited into the Scales by existing members"}], "livro": "Book of Water (Livro da Água)"}, {"id": "scorpion_the_scorpions_tail", "nome": "The Scorpion's Tail", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_the_tails_reach_3", "nome": "The Tail's Reach", "rank": 3, "descricao": "The Scorpion’s Tail dojo teaches students several effective ways to employ the kusarigama and its brethren. If you use any chain weapon as a climbing tool, you gain a +1k1 bonus to any Athletics rolls made for that purpose. You may attack with a kusarigama at a distance of up to 15’ from your target. Also, any time you attack with a kusarigama, you may call three Raises on the attack to inflict the Lame Disadvantage on your opponent – the Disadvantage lasts until the Wounds from the attack are healed."}, {"id": "scorpion_the_tails_reach_4", "nome": "The Tail's Reach", "rank": 4, "descricao": "The Scorpion’s Tail dojo teaches students several effective ways to employ the kusarigama and its brethren. If you use any chain weapon as a climbing tool, you gain a +1k1 bonus to any Athletics rolls made for that purpose. You may attack with a kusarigama at a distance of up to 15’ from your target. Also, any time you attack with a kusarigama, you may call three Raises on the attack to inflict the Lame Disadvantage on your opponent – the Disadvantage lasts until the Wounds from the attack are healed."}], "requisitos": [{"campo": "athletics", "tipo": "skill", "min": "4", "texto": "Athletics 4"}, {"campo": "chain_weapons", "tipo": "skill", "min": "4", "texto": "Chain Weapons 4"}, {"campo": "scorpion_pincers_and_tail", "tipo": "rule", "min": null, "texto": ""}, {"campo": "scorpion_steel_within_silk", "tipo": "rule", "min": null, "texto": ""}], "livro": "Book of Water (Livro da Água)"}, {"id": "crab_toritaka_exorcist", "nome": "Toritaka Exorcist", "clanId": "crab", "tecnicas": [{"id": "crab_warrior_of_earth", "nome": "Purge the Darkness", "rank": 2, "descricao": "You can sense the presence of dangerous spirits (ghosts, gaki, yokai, creatures from the spirit realms, etc) by making an Investigation (Notice) / Perception roll. The base TN for this roll is 20, but may be increased by the GM for spirits which are exceptionally difficult to notice. You may make two Raises on the roll to learn the specific nature of the spirit you detect (e.g. a yorei, a gaki, etc). You may take a Complex Action to attempt an exorcism on someone who is possessed by a ghost, gaki, oni, kitsune-tsuki, or similar entity. You expend one spell slot and make a Contested Willpower roll against the spirit; if you first place an exorcism ward on the target (see sidebar), you gain +2k2 on the roll. With a success, you force the spirit to leave the body it is possessing; it cannot attempt to re-possess that same person for at least 24 hours."}], "requisitos": [{"campo": "willpower", "tipo": "trait", "min": "3", "texto": "Willpower: 3"}, {"campo": "perception", "tipo": "trait", "min": "3", "texto": "Perception: 3"}, {"campo": "calligraphy", "tipo": "skill", "min": "3", "texto": "Calligraphy: 3"}, {"campo": "crab_gaze_into_shadow", "tipo": "rule", "min": null, "texto": ""}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "crane_kakita_jester", "nome": "Kakita Jester", "clanId": "crane", "tecnicas": [{"id": "crane_the_art_of_mockery", "nome": "The Art of Mockery", "rank": 5, "descricao": "The Kakita Jester is tasked with sardonically puncturing the pretense and arrogance of court, reminding all present of their flawed and mortal natures. You may publicly mock a suitable target (someone hypocritical, arrogant, dishonorable, or otherwise deserving of your attention) by means of speech, dance, song, or other such methods. This requires a Contested Roll of your [chosen art] / Awareness against the target’s Etiquette (Courtesy) / Willpower. If you lose the roll, you lose points of Glory equal to the target’s Status Rank. If you win the roll, the target loses face in public, suffering a loss of Glory points equal to your Glory Rank, and a loss of Honor points equal to half as much (rounded up). You may not target the same person with this Technique more than once per month."}], "requisitos": [{"campo": "crane_undying_name", "tipo": "rule", "min": null, "texto": ""}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "dragon_kitsuki_debater", "nome": "Kitsuki Debater", "clanId": "dragon", "tecnicas": [{"id": "dragon_the_ebb_and_flow_of_deception", "nome": "The Ebb and Flow of Deception", "rank": 3, "descricao": "The Kitsuki Debater represents his clan in enemy courts across the Empire, fighting for every small advantage he can win for the Dragon. You can see the flow of a conversation and discern what topic may force your opponent to tell a lie. Make an Etiquette (Conversation)/Awareness roll at a TN 20, plus any Raises you wish to call. (The base TN of this roll may be modified at the GM’s discretion, based on the opponent, the nature of the conversation, and other applicable circumstances.) If you succeed, you switch the topic of conversation to something uncomfortable for your opponent. He must roll Sincerity/Awareness at a TN of 20 plus 5 for every Raise you successfully called. ( Again, the GM may apply circumstantial modifiers as needed.) If he fails the roll he is visibly discomfited by the conversational trap, and suffers a -1k1 penalty to his next Social Skill Roll against you."}], "requisitos": [{"campo": "courtier", "tipo": "skill", "min": "3", "texto": "Courtier: 3"}, {"campo": "etiquette", "tipo": "skill", "min": "5", "texto": "Etiquette (Conversation): 5"}, {"campo": "dragon_wisdom_the_wind_brings", "tipo": "rule", "min": null, "texto": ""}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "dragon_the_dragon_flame", "nome": "The Dragon's Flame", "clanId": "dragon", "tecnicas": [{"id": "dragon_rain_of_death", "nome": "Rain of Death", "rank": 4, "descricao": "The Dragon’s Flame knows accuracy comes from finding tranquility within. You gain a +1k0 bonus to attack rolls, or +2k2 while using a bow."}], "requisitos": [{"campo": "kyujutsu", "tipo": "skill", "min": "5", "texto": "Kyujutsu: 3"}, {"campo": "*dragon_bushi", "tipo": "school", "min": "3", "texto": ""}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "dragon_togashi_defender", "nome": "Togashi Defender", "clanId": "dragon", "tecnicas": [{"id": "dragon_power_within_and_without", "nome": "Power Within and Without", "rank": 3, "descricao": "The isezumi knows the kami cannot aid any man if he proves himself an unworthy physical vessel. While unarmored and with no Kiho or Tattoos active, you gain Reduction equal to 3 plus your Void Ring. You gain one additional Tattoo."}], "requisitos": [{"campo": "dragon_body_of_stone", "tipo": "rule", "min": null, "texto": ""}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "lion_akodo_kensai", "nome": "Akodo Kensai", "clanId": "lion", "tecnicas": [{"id": "lion_the_heart_of_the_sword", "nome": "The Heart of the Sword", "rank": 4, "descricao": "The Akodo Kensai navigates the battlefield with his katana in his hands. He remains untouched by the enemies around him, for he can direct the flow of combat with his own attacks. While using a sword and in the Attack Stance, you may increase your Armor TN by your Honor Rank against the first melee attack each Combat Round. Additionally, once per skirmish you may activate a Kata as a Free Action."}], "requisitos": [{"campo": "iaijutsu", "tipo": "skill", "min": "4", "texto": "Iaijutsu: 4"}, {"campo": "kenjutsu", "tipo": "skill", "min": "5", "texto": "Kenjutsu: 5"}, {"campo": "prodigy", "tipo": "rule", "min": null, "texto": "Prodigy Advantage"}, {"campo": "kenjutsu", "tipo": "skill", "min": "6", "texto": "Kenjutsu: 6"}, {"campo": "prodigy", "tipo": "rule", "min": null, "texto": "Prodigy Advantage"}, {"campo": "iaijutsu", "tipo": "skill", "min": "5", "texto": "Iaijutsu: 5"}, {"campo": "*lion_bushi", "tipo": "school", "min": "3", "texto": "Replaces any Lion Bushi 4"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "lion_lion_scout", "nome": "Lion Scout", "clanId": "lion", "tecnicas": [{"id": "lion_shadow_unseen", "nome": "Shadow Unseen", "rank": 2, "descricao": "The Lion Scout cultivates all the skills required to fulfill his tasks, setting aside his own honor for his clan. You may move at a normal rate while using the Stealth Skill, and you gain a +1k0 bonus to Stealth Skill Rolls and all Agility-based Bugei Skills."}], "requisitos": [{"campo": "battle", "tipo": "skill", "min": "2", "texto": "Battle: 2"}, {"campo": "hunting", "tipo": "skill", "min": "3", "texto": "Hunting: 3"}, {"campo": "*lion_bushi", "tipo": "school", "min": "1", "texto": "Replaces any Lion Bushi 2"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "lion_lion_paragon", "nome": "Lion Paragon", "clanId": "lion", "tecnicas": [{"id": "lion_pure_and_dedicated", "nome": "Pure and Dedicated", "rank": 3, "descricao": "The Lion Paragon lives by the tenets of Bushido, and the strength of his devotion allows him to push himself beyond his physical limits. You may make melee attacks as a Simple Action instead of a Complex Action. However, if you choose to do so, you may only make one attack that Turn. (This prohibits you from making any additional attacks, even with the Extra Attack Maneuver.) Once per skirmish, you may spend a Void Point as a Free Action to activate this Technique. Your Honor Rank is considered to be double for the purpose of your other School Techniques. (For example, if you are a Matsu Bushi, you add double your Honor Rank to all damage rolls from your Rank 1 Technique.) This effect may increase your Honor Rank above 10, but does not stack with any other effects that modify Technique bonuses; in such a case, choose the highest modifier. The effects of this Technique end when the encounter ends."}], "requisitos": [{"campo": "kenjutsu", "tipo": "skill", "min": "5", "texto": "Kenjutsu: 5"}, {"campo": "void", "tipo": "ring", "min": "4", "texto": "Void Ring: 4"}, {"campo": "honor", "tipo": "trait", "min": "7", "texto": "Honor Rank: 7"}, {"campo": "*lion_bushi", "tipo": "school", "min": "2", "texto": "Replaces any Lion Bushi 3"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "mantis_moshi_guardian_of_the_sun", "nome": "Moshi Guardian of the Sun (Path)", "clanId": "mantis", "tecnicas": [{"id": "mantis_defender_as_the_sun", "nome": "Defender as the Sun", "rank": 1, "descricao": "The Guardians of the Sun take an oath to repel all attacks against their sacred charges. When defending a Moshi personage or holding in a skirmish, you may choose to either gain a bonus of +1k0 to your attack roll or to add an additional +1k1 to the Armor TN of a person or object you are defending with the Guard Action. You make this determination at the start of your Turn during each Round of the skirmish."}], "requisitos": [], "livro": "Great Clans (Grandes Clãs)"}, {"id": "mantis_kitsune_ranger", "nome": "Kitsune Ranger", "clanId": "crab", "tecnicas": [{"id": "mantis_one_with_the_wild", "nome": "One With the Wild", "rank": 2, "descricao": "Although they do not possess an ability to speak to the kami, the Kitsune rangers are at home in the wilderness like few others in the Empire. You gain a Free Raise on all Hunting Skill Rolls and on any Stealth Skill Rolls made while in a rural environment. Additionally, you gain a bonus of +2k0 on any Contested Roll involving detection, whether you are avoiding detection or attempting to detect a hidden opponent."}], "requisitos": [{"campo": "hunting", "tipo": "skill", "min": "3", "texto": "Hunting: 3"}, {"campo": "*mantis_bushi", "tipo": "school", "min": "1", "texto": "Replaces any Mantis Bushi 2"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Prior to the Kitsune joining the Mantis Clan, this Technique may be taken as a Rank 2 Path by any bushi-trained Kitsune, regardless of school—including those who do not have a school. This Technique can also be taken as a Rank 2 Ronin Technique for any ronin characters who possess a Ally Advantage associated with the Kitsune family."}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "scorpion_kuroiban", "nome": "Kuroiban", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_the_black_watch", "nome": "The Black Watch", "rank": 4, "descricao": "You have been taught to sense the presence of the Taint through your connection to the kami. Any time you target someone with a spell (including a benign or helpful spell) you may expend an additional spell slot (in any Element) and take a Free Action to make a Contested Willpower roll with the target. If you succeed in the roll, you can sense whether or not the target is Tainted (e.g. has at least one full Rank of Taint). Normally this technique can only be triggered with targeted spells that have an instantaneous effect. However, if you are trained in the Yogo Shugenja School you may also use this technique with your wards, activating it when the ward is placed. If the spell has a duration, you may only use the technique at the moment you place the ward."}], "requisitos": [{"campo": "willpower", "tipo": "trait", "min": "4", "texto": "Willpower: 3"}, {"campo": "lore_maho", "tipo": "skill", "min": "3", "texto": "Lore: Maho: 3"}, {"campo": "lore_shadowlands", "tipo": "skill", "min": "3", "texto": "Lore: Shadowlands: 3"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must have been chosen to serve in the secret order of the Kuroiban."}, {"campo": "*scorpion_shugenja", "tipo": "school", "min": "3", "texto": "Replaces any Scorpion shugenja 4"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "spider_chuda_necromancer", "nome": "Chuda Necromancer", "clanId": "spider", "tecnicas": [{"id": "spider_the_dead_do_not_rest", "nome": "The Dead Do Not Rest", "rank": 4, "descricao": "The Chuda are unparalleled masters of undeath. As a Simple Action you may expend a spell slot of any element to immediately create from existing corpses a number of zombies equal to your Taint Rank. These undead will obey simple commands from you. They last for one week or until you choose to dismiss your power over them—either way, at that point the corpses disintegrate into rot and dust. (Statistics for zombies can be found on page 331 of the L5R RPG 4th Edition rulebook.)"}], "requisitos": [{"campo": "willpower", "tipo": "trait", "min": "4", "texto": "Willpower: 3"}, {"campo": "lore_shadowlands", "tipo": "skill", "min": "3", "texto": "Lore: Shadowlands: 3"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Knowledge of the maho spell Summon Undead Champion"}, {"campo": "spider_chuda_shugenja_school", "tipo": "school", "min": "2", "texto": "Replaces Chuda Shugenja 3"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "unicorn_ide_trader", "nome": "Ide Trader", "clanId": "unicorn", "tecnicas": [{"id": "unicorn_brisk_economy", "nome": "Brisk Economy", "rank": 2, "descricao": "The Ide Trader is a master of the merchant class, extending his control across the land. You cannot lose Honor or Glory for using the Commerce skill in public. You may attempt to persuade someone to become a new mercantile partner for your clan by rolling Courtier (Manipulation) / Awareness with a bonus to the roll equal to double your Commerce Skill Rank. For persuading a commoner the suggested TN is 25, increased by the GM as appropriate if the target is hostile. Persuading a samurai requires a Contested Roll against the target’s Etiquette (Courtesy) / Willpower, with the target gaining a bonus equal to double his Commerce Skill Rank. (Some samurai targets may gain additional bonuses or even be immune to this Technique due to unshakable loyalties—the GM has final say in such matters.) If you succeed in the roll, the target agrees to become a part of your network of connections and commercial assets. You may immediately gain the target as a free Ally with 1 point of Devotion. If you are using the optional Way of the Daimyo rules found in the L5R RPG 4th Edition supplement Emerald Empire, taking this Path earns you a Duty Point."}], "requisitos": [{"campo": "commerce", "tipo": "skill", "min": "3", "texto": "Commerce: 3"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "must pursue a career as a merchant patron"}, {"campo": "unicorn_the_heart_speaks", "tipo": "rule", "min": null, "texto": "Replaces Ide Emissary 2"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "unicorn_moto_fanatic", "nome": "Moto Fanatic", "clanId": "unicorn", "tecnicas": [{"id": "unicorn_recless_abandon", "nome": "Reckless Abandon", "rank": 4, "descricao": "The Moto Fanatic charges into the thick of battle with no thought to his own safety. If you are in the Full Attack Stance, you may spend a Void Point as a Simple Action to activate this Technique. You gain Reduction equal to your School Rank so long as you remain in the Full Attack Stance."}], "requisitos": [{"campo": "unicorn_desert_wind_strike", "tipo": "rule", "min": null, "texto": "Moto Bushi School 4"}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "unicorn_utaku_horse_master", "nome": "Utaku Horse Master", "clanId": "unicorn", "tecnicas": [{"id": "unicorn_master_of_the_open_plains", "nome": "Master of the Open Plains", "rank": 2, "descricao": "The Utaku men devote themselves to raising and training horses, and are without question the greatest in Rokugan at this task. Indeed, the Unicorn claim that in all their travels across the world they have never encountered better. You gain a +2k0 bonus to all Animal Handling, Horsemanship, and Hunting rolls."}], "requisitos": [{"campo": "unicorn_utaku", "tipo": "tag", "min": null, "texto": "Must be a male of the Utaku family"}, {"campo": "*unicorn_bushi", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*unicorn_shugenja", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*unicorn_monk", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*unicorn_courtier", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*unicorn_ninja", "tipo": "school", "min": "1", "texto": ""}], "livro": "Great Clans (Grandes Clãs)"}, {"id": "scorpion_maskmaker", "nome": "Scorpion Maskmaker", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_conceal_the_eyes", "nome": "Conceal the Eyes", "rank": 2, "descricao": "The artisans who craft masks for Scorpion samurai know how to direct attention away from the wearer's face (and any social cues it might reveal) to the distracting mask itself. Once every three months, you may craft a mask which is especially effective at concealing thoughts and emotions; this mask matches the abilities of the Inheritance Advantage with the Sincerity Skill (L5R 4th Edition Core rulebook, page 150-151), and creating it requires two Raises on your Craft: Maskmaking roll. Also, your experience at using masks to conceal emotions teaches you how to read others' intentions without relying on facial expressions. You gain a +2k0 bonus on any Social Skill roll to detect falsehood or concealed intentions in others."}], "requisitos": [{"campo": "craft_maskmaking", "tipo": "skill", "min": "5", "texto": "Craft: Maskmaking 5"}, {"campo": "sincerity", "tipo": "skill", "min": "3", "texto": "Sincerity (Deceit) 3"}, {"campo": "scorpion_bayushi_courtier_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "scorpion_soshi_shugenja_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "scorpion_yogo_wardmaster_school", "tipo": "school", "min": "1", "texto": ""}], "livro": "The Imperial Archives"}, {"id": "spider_susumu_courtier", "nome": "Susumu Courtier", "clanId": "spider", "tecnicas": [{"id": "spider_the_way_of_victory", "nome": "The Way of Victory", "rank": 1, "descricao": "Susumu courtiers learn how to use the Code of Shourido to strengthen their own efforts in court and to ferret out and intensify the selfish impulses of other samurai. You gain the Student of Shourido Advantage for free (if for some reason you already possess this Advantage, the Experience Point cost is refunded). After a few minutes' conversation with another samurai, you may make a Contested Social roll of your Temptation/Willpower against your opponent's Etiquette/Willpower; with a success, you detect whether the character has any personal flaws which would make him amenable to the appeal of Shourido. (You do not learn the specific nature of the flaws, merely whether they exist.)"}], "requisitos": [{"campo": "spider_daigotsu_courtier_school", "tipo": "school", "min": "0", "texto": "Replaces Daigotsu Courtier 1"}], "livro": "The Imperial Archives"}, {"id": "crab_hiruma_yojimbo", "nome": "Hiruma Yojimbo", "clanId": "crab", "tecnicas": [{"id": "hiruma_yojimbo_crabs_shell", "nome": "The Crab's Shell", "rank": 3, "descricao": "Those Hiruma tasked with protecting the lives of important Crab personages understand that the best and most effective means of defending them is to destroy their enemies as quickly as possible. After making a successful melee attack, you may immediately perform the Guard Action as a Free Action (if your charge is close enough for you to Guard). If you do so, you may add the amount by which your attack roll exceeded your opponent’s Armor TN to the Armor TN of your charge until your next Turn."}], "requisitos": [{"campo": "crab_hiruma_bushi_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crab_ob_hiruma_scout_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "defense", "tipo": "skill", "min": "3", "texto": "Defense: 3"}], "livro": "Strongholds of the Empire"}, {"id": "crab_yasuki_enforcer", "nome": "Yasuki Enforcer", "clanId": "crab", "tecnicas": [{"id": "yasuki_enforcer_gentle_encouragement", "nome": "Gentle Encouragement", "rank": 2, "descricao": "The enforcers of the Yasuki family know how to threaten in such a way that thoroughly cows any potential opponent. You may make a Contested Roll against any individual, using your Willpower / Intimidation against their Willpower / Etiquette. If you are successful, you gain a bonus of +1k0 on all attack rolls made against that individual during the first Round of combat against them during your next skirmish. Each successful Raise made on this Contested Roll increases your bonus by an additional +1k0. If this Technique is activated during a skirmish, the initial Contested Roll is a Complex Action"}], "requisitos": [{"campo": "crab_yasuki_courtier_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "crab_ob_hida_pragmatist_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "intimidation", "tipo": "skill", "min": "3", "texto": "Intimidation: 3"}], "livro": "Strongholds of the Empire"}, {"id": "crane_elite_spearman", "nome": "Crane Elite Spearman", "clanId": "crane", "tecnicas": [{"id": "crane_talons_of_the_daidoji", "nome": "Talons of the Daidoji", "rank": 2, "descricao": "The ferocity of the Crane spearmen is well known upon the battlefield, as is their ability to pin and immobilize those who would threaten the clan. When using a spear to attack an opponent, if you strike an opponent who has not yet acted this round, he must make two Raises to successfully attack you for the remainder of this Round."}], "requisitos": [{"campo": "crane_daidoji_iron_warriors", "tipo": "school", "min": "1", "texto": ""}, {"campo": "crane_ob_daidoji_scout_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "spears", "tipo": "skill", "min": "3", "texto": "Spears 3"}], "livro": "Strongholds of the Empire"}, {"id": "crane_doji_warrior_poet", "nome": "Doji Warrior-Poet", "clanId": "crane", "tecnicas": [{"id": "crane_fan_and_sword", "nome": "Fan & Sword", "rank": 2, "descricao": "A warrior-poet understands that focus is the one and only key to not only victory, but enlightenment as well. When you spend a Void Point to augment an Iaijutsu Skill Roll or a Perform: Poetry Skill Roll, you gain a bonus of +2k1 instead of +1k1. Additionally, whenever you are victorious in a duel or a poetry contest, you gain one additional point of Glory. If you were championing someone else, that person also gains one additional point of Glory. This is in addition to any normal amount being rewarded."}], "requisitos": [{"campo": "crane_kakita_bushi_school", "tipo": "school", "min": "1", "texto": "Replaces Kakita Bushi 2"}, {"campo": "iaijutsu", "tipo": "skill", "min": "2", "texto": "Iaijutsu 2"}, {"campo": "perform_poetry", "tipo": "skill", "min": "2", "texto": "Perform: Poetry 2"}], "livro": "Strongholds of the Empire"}, {"id": "dragon_mirumoto_sentinel_rank3", "nome": "Mirumoto Sentinel (Rank 3)", "clanId": "dragon", "tecnicas": [{"id": "dragon_master_the_land_rank3", "nome": "Master the Land", "rank": 3, "descricao": "A Mirumoto Sentinel is intimately familiar with the land he is tasked with patrolling, and can use its every resource to his advantage. When you are in a province for which you possess the Way of the Land Advantage, you may select any three Bugei Skills you possess. While in the selected province, you gain a bonus of +1k0 to Skill Rolls using those Skills. You may select different Skills for each province for which you possess the Way of the Land Advantage. Additionally, you may make a Contested Void Roll against one opponent at the beginning of a skirmish, before Initiative is rolled. That opponent’s Water Ring is considered one rank lower for the purpose of determining Move Action distances for the remainder of the skirmish."}], "requisitos": [{"campo": "dragon_ob_mirumoto_taoist_swordsman", "tipo": "school", "min": "2", "texto": "Replaces Taoist Swordsman 3"}, {"campo": "way_of_the_land", "tipo": "rule", "min": null, "texto": "Way of the Land Advantage"}], "livro": "Strongholds of the Empire"}, {"id": "dragon_mirumoto_sentinel_rank4", "nome": "Mirumoto Sentinel (Rank 4)", "clanId": "dragon", "tecnicas": [{"id": "dragon_master_the_land_rank4", "nome": "Master the Land", "rank": 4, "descricao": "A Mirumoto Sentinel is intimately familiar with the land he is tasked with patrolling, and can use its every resource to his advantage. When you are in a province for which you possess the Way of the Land Advantage, you may select any three Bugei Skills you possess. While in the selected province, you gain a bonus of +1k0 to Skill Rolls using those Skills. You may select different Skills for each province for which you possess the Way of the Land Advantage. Additionally, you may make a Contested Void Roll against one opponent at the beginning of a skirmish, before Initiative is rolled. That opponent’s Water Ring is considered one rank lower for the purpose of determining Move Action distances for the remainder of the skirmish."}], "requisitos": [{"campo": "dragon_mirumoto_bushi_school", "tipo": "school", "min": "3", "texto": "Replaces Mirumoto Bushi 4"}, {"campo": "way_of_the_land", "tipo": "rule", "min": null, "texto": "Way of the Land Advantage"}], "livro": "Strongholds of the Empire"}, {"id": "dragon_water_hammer_smith", "nome": "Water Hammer Smith", "clanId": "dragon", "tecnicas": [{"id": "dragon_child_of_the_water", "nome": "Child of the Water", "rank": 2, "descricao": "Water Hammer City, and the path of the smith has been made open to you. You may spend a Void Point to add double your Water Ring to the total of all Craft Skills you make for the rest of the day. If you are a shugenja, you may instead pay this cost by spending a Water spell slot. You may only benefit from a single use of this Technique at a time (i.e. you cannot spent two Void Points at different times during the day and gain two bonuses equal to three times your Void Point)."}], "requisitos": [{"campo": "*dragon_bushi", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*dragon_shugenja", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*dragon_monk", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*dragon_courtier", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*dragon_ninja", "tipo": "school", "min": "1", "texto": ""}, {"campo": "*craft", "tipo": "skill", "min": "3", "texto": "Any one Craft Skill at 3 or higher"}], "livro": "Strongholds of the Empire"}, {"id": "fox_kitsune_artisan", "nome": "Kitsune Artisan", "clanId": "fox", "tecnicas": [{"id": "kitsune_artisan_beauty_of_the_world", "nome": "The Beauty of the World", "rank": 2, "descricao": "A master of the Kitsune naturalist art style can craft incredible beauty out of any aspect of the world, be it wood, stone, or whatever can be found in nature. When working with natural materials, you may expend an Earth spell slot to gain a bonus of +1k0 on any Artisan or Craft Skill Roll. You may expend a number of spell slots in this manner equal to your School Rank, and this may be used in conjunction with Void Points."}], "requisitos": [{"campo": "*artisan", "tipo": "skill", "min": "3", "texto": ""}, {"campo": "*craft", "tipo": "skill", "min": "3", "texto": ""}, {"campo": "kitsune_shugenja", "tipo": "school", "min": "1", "texto": "Replaces Kitsune Shugenja 2"}], "livro": "Strongholds of the Empire"}, {"id": "lion_ikoma_warden", "nome": "Ikoma Warden", "clanId": "lion", "tecnicas": [{"id": "lion_to_race_the_wind", "nome": "To Race the Wind", "rank": 2, "descricao": "A true warden understands that mounted warfare is as natural as fighting among the glorious Lion infantry. When Mounted, you gain a bonus of +1k0 to all Bugei Skill Rolls. Additionally, when spending a Void Point to augment a Horsemanship or Investigation Skill Roll, you gain a bonus of +2k2 instead of +1k1."}], "requisitos": [{"campo": "lion_akodo_bushi_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "lion_ob_the_ikoma_lions_shadow_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "horsemanship", "tipo": "skill", "min": "3", "texto": "Horsemanship 3"}], "livro": "Strongholds of the Empire"}, {"id": "lioness_legion", "nome": "Lioness Legion", "clanId": "lion", "tecnicas": [{"id": "lion_charge_of_the_pride", "nome": "Charge of the Pride", "rank": 2, "descricao": "The Lioness Legion is feared for many reasons, but the greatest among them is their fleetness on the field of battle. When in the Full Attack Stance, any movement you make during the course of the Round gains an additional 5 feet (this benefit is only gained once per Round). Additionally, as a Complex Move Action, you may move your Water Ring x25 feet."}], "requisitos": [{"campo": "lion_akodo_bushi_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "lion_matsu_berserker_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "lion_ob_matsu_beastmaster_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "athletics", "tipo": "skill", "min": "3", "texto": "Athletics 3"}], "livro": "Strongholds of the Empire"}, {"id": "mantis_tsuruchi_swordsman", "nome": "Tsuruchi Swordsman", "clanId": "mantis", "tecnicas": [{"id": "tsuruchi_ascendancy_of_steel", "nome": "Ascendancy of Steel", "rank": 4, "descricao": "A master of the Tsuruchi style is a flurry of movement and unrelenting assault. You may make a melee attack as a Simple Action rather than a Complex Action when wielding a sword."}], "requisitos": [{"campo": "mantis_tsuruchi_archer_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "mantis_ob_tsuruchi_bounty_hunter_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "kenjutsu", "tipo": "skill", "min": "3", "texto": "Kenjutsu: 3"}], "livro": "Strongholds of the Empire"}, {"id": "minor_clan_alliance_diplomat", "nome": "Minor Clan Alliance Diplomat", "clanId": "ronin", "tecnicas": [{"id": "the_courts_of_kudo_mura", "nome": "The Courts of Kudo Mura", "rank": 4, "descricao": "The diplomats of Kudo Mura are masters at dealing with the needs, desires, and whims of their superiors. When conversing with a samurai from one of the Great Clans or the Imperial Families, you gain +3k0 on all Contested Rolls using the skills of Etiquette or Sincerity."}], "requisitos": [{"campo": "*any", "tipo": "school", "min": "4", "texto": "Any Minor Clan School 4"}, {"campo": "more", "tipo": "rpg", "min": null, "texto": "Character must belong to a Minor Clan"}], "livro": "Strongholds of the Empire"}, {"id": "phoenix_asako_philosopher", "nome": "Asako Philosopher", "clanId": "phoenix", "tecnicas": [{"id": "the_winds_of_rhetoric", "nome": "The Winds of Rhetoric", "rank": 2, "descricao": "Those who study with the Nikesake sophists have learned to defuse almost any situation, as they have a superior understanding of how those with whom they enter debate think and seek solutions to various problems. You gain a bonus of +1k1 to the total of all Contested Social Skill Rolls using Etiquette."}], "requisitos": [{"campo": "courtier", "tipo": "skill", "min": "2", "texto": "Courtier (Rhetoric) 2"}, {"campo": "etiquette", "tipo": "skill", "min": "3", "texto": "Etiquette 3"}, {"campo": "phoenix_asako_loremaster_school", "tipo": "school", "min": "1", "texto": "Replaces Asako Loremaster 2"}], "livro": "Strongholds of the Empire"}, {"id": "phoenix_provincial_guard", "nome": "Provincial Guard", "clanId": "phoenix", "tecnicas": [{"id": "phoenix_maintaining_the_peace", "nome": "Maintaining the Peace", "rank": 2, "descricao": "A Shiba member of the Provincial Guard is skilled in protecting himself from all harm, regardless of its source. When in the Defense or Full Defense Stances and spending a Void Point to augment your Armor TN, you also add an amount to your Armor TN equal to your Etiquette Skill."}], "requisitos": [{"campo": "phoenix_shiba_bushi_school", "tipo": "school", "min": "1", "texto": "Replaces Shiba Bushi 2"}, {"campo": "defense", "tipo": "skill", "min": "2", "texto": "Defense 2"}, {"campo": "etiquette", "tipo": "skill", "min": "2", "texto": "Etiquette 2"}], "livro": "Strongholds of the Empire"}, {"id": "scorpion_weaponmaster_school", "nome": "Scorpion Weaponmaster", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_i_am_a_weapon", "nome": "I Am A Weapon", "rank": 4, "descricao": "A true weaponmaster understands the common thread between all weapons, and draws upon it. When wielding any melee weapon, a number of times per skirmish equal to your school rank, you may as a Free Action use any other melee Weapon Skill you possess for attack rolls using your current weapon. For example, you could spend a Void Point to use Kenjutsu when wielding a tetsubo if you had no ranks in Heavy Weapons. You gain no benefits from any Mastery Abilities or Emphases when utilizing this Technique. The effect lasts a number of Rounds equal to your School Rank, and while this Technique is in effect you may make melee attacks as a Simple Action rather than a Complex Action."}], "requisitos": [{"campo": "scorpion_bayushi_bushi_school", "tipo": "school", "min": "3", "texto": "Replaces Bayushi Bushi 4"}, {"campo": "*weapon", "tipo": "skill", "min": "2", "texto": "Any Weapon Skills at 2"}, {"campo": "*weapon", "tipo": "skill", "min": "2", "texto": "Any Weapon Skills at 2"}, {"campo": "*weapon", "tipo": "skill", "min": "2", "texto": "Any Weapon Skills at 2"}], "livro": "Strongholds of the Empire"}, {"id": "scorpion_shadow_blades", "nome": "Shadow Blades", "clanId": "scorpion", "tecnicas": [{"id": "scorpion_never_beyond_my_reach", "nome": "Never Beyond My Reach", "rank": 2, "descricao": "The flawless blend of warrior and assassin works unlocks a samurai’s true potential as a killer of men. You may make melee attacks as a Simple Action instead of a Complex Action when wielding a katana or any weapon with the Ninja keyword. When wielding a weapon with the Ninja keyword, you may also add +1k1 to your attack and damage rolls with that weapon."}], "requisitos": [{"campo": "scorpion_bayushi_bushi_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "scorpion_shosuro_infiltrator_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "ninjutsu", "tipo": "skill", "min": "3", "texto": "Ninjutsu 3"}], "livro": "Strongholds of the Empire"}, {"id": "spider_daigotsu_scout", "nome": "Daigotsu Scout", "clanId": "spider", "tecnicas": [{"id": "spider_the_cloak_of_shadows", "nome": "The Cloak of Shadows", "rank": 2, "descricao": "Although not as talented as the inhuman minions of the Shadow Dragon or the Lying Darkness, the Daigotsu scouts are still highly skilled in moving about without being detected. Stealth is now considered a School Skill for you, and you gain one additional Emphasis in the skill above any you may already possess, and in excess of the maximum normal number of Emphases you may posses. Your Move Actions are not reduced when using Stealth, and when using Stealth you may also ignore any terrain penalties that would normally reduce your Move Actions."}], "requisitos": [{"campo": "spider_daigotsu_bushi_school", "tipo": "school", "min": "1", "texto": "Replaces Daigotsu Bushi 2"}, {"campo": "stealth", "tipo": "skill", "min": "3", "texto": "Stealth 3"}], "livro": "Strongholds of the Empire"}, {"id": "spider_dark_path_sohei", "nome": "Dark Path Sohei", "clanId": "spider", "tecnicas": [{"id": "spider_walk_upon_the_dark_path", "nome": "Walk upon the Dark Path", "rank": 2, "descricao": "Even the most devout member of the Brotherhood of Shinsei would attest that there is no one true path to enlightenment, and certain members of the Order of the Spider seem to bear out that theory. You gain two Kiho, for which you must meet all normal prerequisites. These Kiho do not count against the normal number of Kiho you may learn as determined by your School Rank."}], "requisitos": [{"campo": "spider_order_of_the_spider_monk", "tipo": "school", "min": "1", "texto": "Order of the Spider 2"}, {"campo": "theology", "tipo": "skill", "min": "3", "texto": "Theology 3"}], "livro": "Strongholds of the Empire"}, {"id": "unicorn_calm_heart_duelist", "nome": "Calm Heart Duelist", "clanId": "unicorn", "tecnicas": [{"id": "unicorn_calm_heart_conquers", "nome": "The Calm Heart Conquers", "rank": 3, "descricao": "A soul of serenity can overcome even the most stalwart opponent. You gain a bonus of +1k0 to the total of any Iaijutsu Skill Roll when you are not striking to kill your opponent, whether in a duel to first blood or a skirmish. You may make melee attacks as a Simple Action instead of a Complex Action when you are wielding a katana or wakizashi."}], "requisitos": [{"campo": "*unicorn_bushi", "tipo": "school", "min": "2", "texto": "Any Unicorn Bushi School, Rank 3"}, {"campo": "iaijutsu", "tipo": "skill", "min": "3", "texto": "Iaijutsu: 3"}, {"campo": "lore_law", "tipo": "skill", "min": "1", "texto": "Lore: Law: 1"}], "livro": "Strongholds of the Empire"}, {"id": "unicorn_ide_caravan_master", "nome": "Ide Caravan Master", "clanId": "unicorn", "tecnicas": [{"id": "unicorn_ide_the_gilded_road", "nome": "The Gilded Road", "rank": 1, "descricao": "A true master of the caravan path can forge lasting bonds with his customers, and has reaped the rewards of his travels. You gain a bonus of +1k1 on all Commerce Skill Rolls. You also gain this bonus on all Social Skill Rolls made with your customers. You gain one level of the Wealthy Advantage and one instance of the Way of the Land Advantage for free."}], "requisitos": [{"campo": "unicorn_ide_emissary_school", "tipo": "school", "min": "0", "texto": "Ide Emissary School, Rank 1"}, {"campo": "commerce", "tipo": "skill", "min": "2", "texto": "Commerce: 2"}], "livro": "Strongholds of the Empire"}, {"id": "crab_tsurus_legion", "nome": "Tsuru’s Legion", "clanId": "crab", "tecnicas": [{"id": "tsurus_legion_overrun", "nome": "Overrun", "rank": 2, "descricao": "Special: Admission to Tsuru’s Legion adds a steed (Rokugani pony) to your outfit if you do not already possess one. The cavalry of Tsuru’s Legion are trained to deliver decisive attacks at the critical moment of a battle. When you are mounted, you may perform the Knockdown maneuver for one less Raise and you may spend a Void Point to add +Xk0 to an attack roll with a weapon, where X is your mount’s Strength."}], "requisitos": [{"campo": "crab_hiruma_bushi_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "crab_hida_bushi_school", "tipo": "school", "min": "1", "texto": ""}, {"campo": "horsemanship", "tipo": "skill", "min": "3", "texto": "Horsemanship: 3"}], "livro": "Sword and Fan"}, {"id": "crab_yasuki_taskmaster", "nome": "The Yasuki Taskmasters", "clanId": "crab", "tecnicas": [{"id": "yasuki_taskmaster_fear_is_a_gift", "nome": "Technique: Fear is a Gift", "rank": 3, "descricao": "The Yasuki long ago concluded the best method to get peasant soldiers to face the horrors of the Shadowlands was to make the ashigaru more frightened of their officers than of their enemies. The Taskmasters embrace Intimidation as a Skill with many more applications than others might expect. You treat Intimidation as a Bugei Skill rather than a Low Skill. You may use Willpower as your Trait on any Battle Skill roll, and may use your Intimidation Rank in place of your Battle Rank when rolling for Step 2: Determination on the Mass Battle Table. Finally, any soldiers (samurai, peasant, or otherwise) under your military command may add your Intimidation Skill Rank to the total of any rolls they make to resist Fear effects."}], "requisitos": [{"campo": "crab_yasuki_courtier_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "crab_ob_hida_pragmatist_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "crab_hida_bushi_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "intimidation", "tipo": "skill", "min": "5", "texto": "Intimidation: 5"}, {"campo": "willpower", "tipo": "skill", "min": "4", "texto": "Intimidation: 4"}, {"campo": "battle", "tipo": "skill", "min": "3", "texto": "Battle: 3"}], "livro": "Sword and Fan"}, {"id": "crane_doji_apologist", "nome": "Doji Apologist", "clanId": "crane", "tecnicas": [{"id": "shinjo_magistrate_eyes_of_the_vigilant", "nome": "All Is Forgiven", "rank": 4, "descricao": "The Apologists can smooth over incidents that would ordinarily disgrace other samurai. You can erase the damage done by a Minor Breach of Etiquette (including any associated Glory or Status loss) with a Social Skill Roll of Etiquette (Courtesy) / Awareness at TN 25. You may reduce a Major Breach of Etiquette to a Minor Breach by successfully calling 2 Raises on this roll. With 5 Raises, you can reduce a Blasphemous Breach of Etiquette to a Major Breach – subject to the GM’s permission (some violations are simply too severe to be mitigated). The Apologist must act promptly in order to resolve an incident before its consequences become set in stone. In general, a Minor Breach can only be repaired within a number of hours equal to twice your Insight Rank, while a Major Breach must be repaired within that many minutes, and a Blasphemous Breach must be mitigated immediately after it takes place. (The GM may adjust these times if it seems appropriate to the specific circumstances.) GM’s Note: The Apologist can only cover for the errors of others, not for himself. The GM may choose to reduce the Honor loss for a breach of etiquette that has been mitigated, to represent the character recovering a sense of moral worth through the mitigation of the error, but the character should always lose at least 1 point of Honor."}], "requisitos": [{"campo": "crane_doji_courtier_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "etiquette", "tipo": "skill", "min": "5", "texto": "Etiquette (Courtesy) 5"}], "livro": "Sword and Fan"}, {"id": "dragon_the_dragons_wind", "nome": "The Dragon's Wind", "clanId": "dragon", "tecnicas": [{"id": "way_of_the_horse_and_bow", "nome": "Way of the Horse and Bow", "rank": 4, "descricao": "The Mirumoto horse archers train with their mounts in the rugged lands of the Dragon, allowing them to ride through territory where other cavalry forces do not dare to tread. While you are mounted, your steed treats Moderate terrain as Basic terrain, and Difficult terrain as Moderate terrain. You may attack with a bow as a Simple Action while you are mounted. Special Note: Joining this Path adds a steed (Rokugani pony) and a bow (Dai-Kyu) to your Outfit if you did not already possess them."}], "requisitos": [{"campo": "dragon_miromoto_taoist_swordsman_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "dragon_miromoto_bushi_school", "tipo": "school", "min": "4", "texto": ""}, {"campo": "horsemanship", "tipo": "skill", "min": "5", "texto": "Horsemanship: 5"}, {"campo": "kyujutsu", "tipo": "skill", "min": "5", "texto": "Kyujutsu (Dai-Kyu): 5"}], "livro": "Sword and Fan"}, {"id": "lion_lion_tactician_ikoma_tactician", "nome": "Lion Tactician (Ikoma Tactician)", "clanId": "lion", "tecnicas": [{"id": "the_commanders_fan", "nome": "The Commander’s Fan", "rank": 4, "descricao": "Lion officers usually carry a war-fan in order to use it for conveying orders on the battlefield. Early on, they discovered the fan could also be used to protect themselves when they came under attack on the battlefield. You gain a +1k1 bonus to Battle (Mass Battle) rolls in any situation where your war-fan makes it easier for you to convey orders (GM’s discretion). While you are carrying a war-fan (regardless of which hand you are using), you may add half your Warfans Skill Rank (rounded up) to your Armor TN. If you are in the Defense or Full Defense Stance, or you are ONLY carrying a war-fan, you may add your full Skill Rank instead. (These do not stack,and carrying two war-fans does not double the bonus.)"}], "requisitos": [{"campo": "lion_bushi", "tipo": "school", "min": "3", "texto": ""}, {"campo": "lion_ikoma_bard_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "battle", "tipo": "skill", "min": "4", "texto": "Battle: 4"}, {"campo": "war_fan", "tipo": "skill", "min": "4", "texto": "Warfan: 4"}, {"campo": "rpg", "tipo": "more", "min": null, "texto": "Must be at least a Gunso in rank."}], "livro": "Sword and Fan"}, {"id": "lion_ikoma_orators", "nome": "Ikoma Orators", "clanId": "lion", "tecnicas": [{"id": "ikoma_the_voice_of_bushido", "nome": "The Voice of Bushido", "rank": 3, "descricao": "The Orators use their speechmaking powers to draw attention to the honor of their side and the dishonor of their foes. You must give a speech (suggested of at least five minutes’ length) before a court or similar audience to activate this Technique. If you are targeting an ally with the speech, you roll Perform: Oratory / Awareness at TN 30. If you are targeting an enemy, you either make the same roll (if the enemy does not respond), or make a Contested Social Roll of your Perform: Oratory / Awareness against his Sincerity / Awareness (if he does respond). A successful speech for an ally grants that ally one of the Paragon of Bushido Advantages for one week, while a successful speech against an enemy inflicts one of the Failure of Bushido Disadvantages on that enemy for one week. (If the enemy character has the corresponding Paragon of Bushido Advantage, you instead deny the use of that Advantage for one week.) You cannot affect the same person with this Technique twice in the same month. GM’s Options: GMs who wish to add more depth to the Ikoma Orator’s abilities may choose to let the target’s Honor, Glory, and Infamy affect the rolls required to use the Voice of Bushido technique. When targeting an ally, the TN to bestow the Advantage is reduced by the target’s Honor Rank and Glory Rank, but increased by his Infamy Rank (if any). When targeting an enemy, the reverse applies – Honor and Glory increase the TN, while Infamy reduces it."}], "requisitos": [{"campo": "lion_ikoma_bard_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "sincerity", "tipo": "skill", "min": "4", "texto": "Sincerity: 4"}, {"campo": "lore_bushido", "tipo": "skill", "min": "3", "texto": "Lore: Bushido: 4"}, {"campo": "perform_oratory", "tipo": "skill", "min": "4", "texto": "Perform: Oratory: 4"}], "livro": "Sword and Fan"}, {"id": "lion_ikoma_scrapper", "nome": "Ikoma Scrapper", "clanId": "lion", "tecnicas": [{"id": "lion_every_scar_has_a_name", "nome": "Every Scar Has a Name", "rank": 4, "descricao": "The Scrapper learns that so long as he can call on the same courage and ruthlessness as Ikoma himself, he is never truly unarmed. You may attack as a Simple Action with unarmed strikes and improvised weapons (if you did not already have the ability to do so). Your vicious attacks can disorient and terrify your opponents. Once per skirmish, if you strike unarmed or with an improvised weapon, you may call two Raises to make your attack inflict a Fear effect on the target, with a Rank equal to your Insight Rank."}], "requisitos": [{"campo": "lion_akodo_bushi_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "lion_matsu_berserker_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "lion_ikoma_lions_shadow_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "lion_ikoma_bard_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "strength", "tipo": "trait", "min": "4", "texto": "Strength: 4"}, {"campo": "jiujutsu", "tipo": "skill", "min": "5", "texto": "Jiujutsu: 4"}], "livro": "Sword and Fan"}, {"id": "unicorn_war_dog_master", "nome": "Unicorn War-Dog Master", "clanId": "unicorn", "tecnicas": [{"id": "war_dog_master_ferocity_of_the_ki_rin", "nome": "Ferocity of the Ki-Rin", "rank": 4, "descricao": "Special: Enrolling in this Path grants you a pack of Unicorn War-Dogs (core rulebook, page 321). The total number of war-dogs you can have in your pack is equal to your Awareness. The War-Dog Masters learn how to train an entire pack of war-dogs and how to control and direct the pack in combat. As a Complex Action, you can roll Animal Handling (War Dogs) / Willpower at TN 20 to give your entire pack of War-Dogs a simple command (such as “Attack” or “Track” or “Hold Position”). You can Raise on this roll to convey more sophisticated commands, subject to the GM’s judgment and limitations. Also, when your War-Dogs carry out attacks which you have ordered them to make, they gain a +1k0 bonus to their attack and damage rolls."}], "requisitos": [{"campo": "unicorn_shinjo_bushi_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "unicorn_utaku_mounted_infantry_bushi_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "unicorn_moto_bushi_school", "tipo": "school", "min": "3", "texto": ""}, {"campo": "awareness", "tipo": "trait", "min": "3", "texto": "Awareness: 3"}, {"campo": "willpower", "tipo": "trait", "min": "4", "texto": "Willpower: 4"}, {"campo": "animal_handling", "tipo": "skill", "min": "3", "texto": "Animal Handling (War-Dogs): 5"}], "livro": "Sword and Fan"}, {"id": "unicorn_shinjo_magistrate", "nome": "Shinjo Magistrate", "clanId": "unicorn", "tecnicas": [{"id": "shinjo_magistrate_eyes_of_the_vigilant", "nome": "Eyes of the Vigilant", "rank": 2, "descricao": "The Magistrates are charged with rooting out and destroying criminals, traitors, and law-breakers of all sorts. When using Investigation to try to locate clues or to test another person’s truthfulness, you gain a +1k0 bonus. When tracking known criminals or traitors you gain a +1k0 to Hunting Skill rolls, and when attacking such persons you gain a +1k0 to all Weapon Skill Rolls. GM’s Option: The Unicorn Vigilant – In games set after the Hidden Emperor era, the GM can reflect the Unicorn Clan’s efforts to purge Kolat influence by increasing the Investigation bonus to +1k1 when opposing Kolat activities or agents."}], "requisitos": [{"campo": "unicorn_shinjo_bushi_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "unicorn_utaku_battle_maiden_bushi_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "unicorn_moto_bushi_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "unicorn_moto_vindicator_bushi_school", "tipo": "school", "min": "2", "texto": ""}, {"campo": "investigation", "tipo": "skill", "min": "3", "texto": "Investigation: 3"}, {"campo": "lore_law", "tipo": "skill", "min": "3", "texto": "Lore: Law 3"}], "livro": "Sword and Fan"}], "familias": [{"id": "peasant_koga", "clanId": "peasant", "nome": "Koga", "traco": "awareness", "livro": "Book of Void (Livro do Vazio)"}, {"id": "phoenix_sesai", "clanId": "phoenix", "nome": "Sesai (Shiba)", "traco": "agility", "livro": "Book of Void (Livro do Vazio)"}, {"id": "ronin_hateru", "clanId": "ronin", "nome": "Hateru", "traco": "intelligence", "livro": "Book of Void (Livro do Vazio)"}, {"id": "spider_ninube", "clanId": "spider", "nome": "Ninube", "traco": "reflexes", "livro": "Great Clans (Grandes Clãs)"}], "clans": [{"id": "various", "nome": "Various", "livro": "Book of Air (Livro do Ar)"}, {"id": "peasant", "nome": "Peasant", "livro": "Book of Void (Livro do Vazio)"}, {"id": "any_minor_clan", "nome": "Any Minor Clan", "livro": "Emerald Empire"}], "vantagens": [{"id": "reincarnated", "nome": "Reincarnated", "tipo": "spiritual", "custo": 6, "descricao": "Despite having passed through Meido, you retain some faint recollection of your previous life. You gain +1k0 to any three non-School Skills of your choice (subject to GM’s approval). Any time you spend a Void Point to enhance a roll using one of those Skills, you suffer the effects of the Anachronism disadvantage (from the L5R 4th Edition supplement Imperial Histories, page 241) for 1-10 hours. In addition, you will occasionally have dreams or vague memories from your previous life, which may or may not become relevant to your current existence. Note: GMs who allow Naga characters may also opt to make this Advantage available to Naga to represent the ancestral memories of the Akasha. If used in this way, it costs 7 points and does not impose the Anachronism penalty.", "livro": "Book of Void (Livro do Vazio)", "pagina": "191"}, {"id": "watanu_trained", "nome": "Watanu-Trained", "tipo": "mental", "custo": 1, "descricao": "The Watanu ronin of Iron Heart Village are well known throughout the region for their superior skills in smithing. Select one Craft Skill related to the creation of metallic goods (not weapons or armor). When making Skill Rolls to create such items, you gain a bonus of +1k1.", "livro": "Book of Void (Livro do Vazio)", "pagina": "195"}, {"id": "iron_heart_native", "nome": "Iron Heart Native", "tipo": "physical", "custo": 2, "descricao": "Your ancestors are from the region near Iron Heart Village, and the traits common to that region remain manifest in you. You gain a bonus of +1k0 to any Stamina Trait Roll or to any non-damage roll using the Strength Trait (including rolls to control Grapples).", "livro": "Book of Void (Livro do Vazio)", "pagina": "195"}, {"id": "laughing_plains_native", "nome": "Laughing Plains Native", "tipo": "mental", "custo": 2, "descricao": "You possess the traits indigenous to the people of Laughing Plains Village, from whence some distant ancestor of yours originated. Your dour and bleakly stoic outlook on life grants you a bonus of +5 when rolling to resist any Fear effect.", "livro": "Book of Void (Livro do Vazio)", "pagina": "195"}, {"id": "sacred_forest_native", "nome": "Sacred Forest Native", "tipo": "mental", "custo": 2, "descricao": "The spiritual folk of Sacred Forest Village consider you one of their own due to the nature of your ancestry, which includes someone from that region. You gain +1k0 to rolls with Lore: Theology and Lore: Spirit Realms.", "livro": "Book of Void (Livro do Vazio)", "pagina": "195"}, {"id": "the_world_of_the_daiymo", "nome": "The World of the Daimyo", "tipo": "social", "custo": 5, "descricao": "", "livro": "Emerald Empire", "pagina": ""}, {"id": "the_daiymos_path", "nome": "The Daimyo's Path ", "tipo": "social", "custo": 10, "descricao": "", "livro": "Emerald Empire", "pagina": ""}, {"id": "void_versatility", "nome": "Void Versatility", "tipo": "spiritual", "custo": 4, "descricao": "", "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "heartless", "nome": "Heartless", "tipo": "mental", "custo": 4, "descricao": "", "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "student_of_shourido", "nome": "Student of Shourido", "tipo": "mental", "custo": 9, "descricao": "Truly dedicated followers of the Way of Victory are able to prevail despite their rejection of Bushido. When rolling to resist Temptation, Intimidation, or Fear, you may choose to add +5 to your roll instead of adding your Honor Rank to the roll. If the optional Honor Roll rule (page 92 of the L5R 4th Edition Core rulebook) is being used, you may roll 5 dice instead of rolling dice equal to your Honor Rank. This Advantage costs 6 points for Spider characters.", "livro": "The Imperial Archives", "pagina": "96"}, {"id": "well_connected", "nome": "Well-Connected", "tipo": "social", "custo": 3, "descricao": "Characters who possess this Advantage are integrated into the fabric of a particular court so well that they can call on a large number of people for small acts of assistance. Choose one court when you purchase this Advantage. One time each session per level of the Advantage, you may roll Courtier / Awareness at TN 20. If successful, you gain the benefit of one minor favor from someone else at court. This favor should not be something that inconveniences the benefactor, and it will only be a small piece of information or a simple bit of assistance, but it will always be useful to some task you are currently pursuing. Courtiers may purchase this Advantage for one point less per Rank.", "livro": "The Imperial Archives", "pagina": "97"}, {"id": "broken_wave_citizen", "nome": "Broken Wave Citizen", "tipo": "social", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "clear_water_native", "nome": "Clear Water Native", "tipo": "social", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "dark_edge_native", "nome": "Dark Edge Native", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "imperial_city_citizen", "nome": "Imperial City Citizen", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "imperial_city_veteran", "nome": "Imperial City Veteran", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "inheritance_asahina_blade", "nome": "Inheritance: Asahina Blade", "tipo": "material", "custo": 9, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "inheritance_kobune", "nome": "Inheritance: Kobune", "tipo": "material", "custo": 10, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "nikesake_citizen", "nome": "Nikesake Citizen", "tipo": "social", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "ruined_city_shadow", "nome": "Ruined City Shadow", "tipo": "physical", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "stolen_identity", "nome": "Stolen Identity", "tipo": "social", "custo": 6, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "water_hammer_armor", "nome": "Water Hammer Armor", "tipo": "material", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "water_hammer_citizen", "nome": "Water Hammer Citizen", "tipo": "social", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "zakyo_toshi_citizen", "nome": "Zakyo Toshi Citizen", "tipo": "social", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "sage_of_the_sword_and_fan", "nome": "Sage of the Sword and Fan", "tipo": "mental", "custo": 7, "descricao": "", "livro": "Sword and Fan", "pagina": ""}, {"id": "strategist", "nome": "Strategist", "tipo": "mental", "custo": 5, "descricao": "", "livro": "Sword and Fan", "pagina": ""}], "desvantagens": [{"id": "uncentered", "nome": "Uncentered", "tipo": "spiritual", "custo": 2, "descricao": "Whether it is due to poor teaching, a lack of understanding on your part, or simply an absence of true harmony within your soul, you are incapable of mastering the deepest mysteries of the Void. You may not learn any Void Kiho and you cannot take the Ishiken-do or the Void Versatility Advantages.", "livro": "Book of Void (Livro do Vazio)", "pagina": "192"}, {"id": "enlightened_madness", "nome": "Enlightened Madness", "tipo": "spiritual", "custo": 4, "descricao": "", "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "debt", "nome": "Debt", "tipo": "social", "custo": 2, "descricao": "Whether through bad luck or simple imprudence, at some point you found yourself short of money and \"solved\" this problem by taking out a loan, either from a wealthy commoner or a fellow samurai. You are expected to repay this loan, and until you do, the shame of your indebted state hangs over you. For 2 points, your debt is equivalent to one quarter of your yearly stipend. For 4 points, you owe your entire yearly stipend, and for 8 points, you owe substantially more than that. If others learn about your debt, you will at a minimum lose Glory and your fellow samurai may come to look down on you. Moreover, even if you keep the debt secret, your creditor may decide to use it to pressure you into doing things on his behalf. This Disadvantage is worth one additional point for courtiers.", "livro": "The Imperial Archives", "pagina": "97"}, {"id": "bounty", "nome": "Bounty", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "broken_wave_stigma", "nome": "Broken Wave Stigma", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "clear_water_stigma", "nome": "Clear Water Stigma", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "dark_edge_reputation", "nome": "Dark Edge Reputation", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "nikesake_stigma", "nome": "Nikesake Stigma", "tipo": "social", "custo": 4, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "ruined_city_survivor", "nome": "Ruined City Survivor", "tipo": "material", "custo": 4, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "wanderer", "nome": "Wanderer", "tipo": "varies", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "water_hammer_stigma", "nome": "Water Hammer Stigma", "tipo": "social", "custo": 2, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}, {"id": "zayako_toshi_stigma", "nome": "Zakyo Toshi Stigma", "tipo": "social", "custo": 3, "descricao": "", "livro": "Strongholds of the Empire", "pagina": ""}], "ancestrais": [{"id": "ancestor_crab_hiruma", "nome": "Ancestor, Hiruma", "tipo": "ancestral", "custo": 11, "descricao": "The man who founded the Hiruma family was a pragmatic warrior who employed speed, precision, and stealth to defeat powerful foes. His guidance makes it easier to follow in his footsteps, granting you a +1k0 bonus to your Stealth, Kenjutsu, and Kyujutsu skill rolls. Demands: If Hiruma watches over you, you can never willingly betray the Crab Clan or he will abandon you. However, as a pragmatic warrior who eschews many of the niceties of Bushido he will also abandon you if your Honor Rank ever rises higher than 5.0.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "crab"}, {"id": "ancestor_crab_kaiu", "nome": "Ancestor, Kaiu", "tipo": "ancestral", "custo": 9, "descricao": "The legendary master craftsmen who forged the Crab Clan Ancestral Sword that slew Hatsu-Suru no Oni. Kaiu founded the most potent engineering school in the Empire and his descendants built the Great Carpenter Wall. Kaiu’s guidance grants you a +3k1 bonus (instead of +1k1) any time you spend a Void Point on a Craft or Engineering skill roll. In addition, once per game year you may call on Kaiu’s inspiration and roll an appropriate Craft skill at TN 50 to create a minor awakened nemuranai. The initial powers of this magical item are chosen by the GM, but should start out weak (e.g. +1k0 to skills or damage rolls, for example) until the spirits within the item grow stronger over time. Demands: Kaiu abhors mediocrity, laziness, and failure. You must never deliberately produce Craft/Engineering work that is less than your best. This obviously includes keeping low dice on a skill roll but will also have many subtler role-play applications; such situations should be adjudicated by the GM.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "crab"}, {"id": "ancestor_crane_doji_hayaku", "nome": "Ancestor, Doji Hayaku", "tipo": "ancestral", "custo": 7, "descricao": "Doji’s youngest son, the founder of the Daidoji family, was a skilled warrior who spent two years hunting for his lost sister Konishiko. He ultimately retrieved her sword (and her soul) from the Shadowlands, but in the process he lost his voice and his hair turned white. Hayaku’s guidance grants you a +1k1 bonus to Lore: Shadowlands rolls and a Free Raise on all attacks with Spears. Demands: You must honor Hayaku’s sacrifices by dyeing your hair white. You can never abandon, betray, or endanger a member of the Doji family (or your charge if you are a yojimbo)—if you do, Hayaku abandons you in fury.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "crane"}, {"id": "ancestor_crane_asahina", "nome": "Ancestor, Asahina", "tipo": "ancestral", "custo": 9, "descricao": "A powerful and talented Phoenix Clan Fire shugenja who forsook the ways of violence and married into the Crane Clan, Asahina became one of the Empire’s foremost advocates of peace. His family maintains his traditions to this day. Asahina’s spiritual guidance grants you a +1k0 bonus on Meditation rolls and a +1k1 bonus to Spell Casting Rolls when casting a non-damaging spell with the Craft or Defense keywords. Demands: Asahina expects you to live up to his ideals of absolute pacifism. If you ever willingly and deliberately harm a living creature, even a Tainted creature, he forsakes you.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "crane"}, {"id": "ancestor_dragon_agasha_gc", "nome": "Ancestor, Agasha", "tipo": "ancestral", "custo": 6, "descricao": "The founder of the Agasha family was an isolated researcher who studied the Elements and learned their secrets. Although much of her family joined the Phoenix, she remains loyal to the Dragon and appears only to those of her descendents found within that clan. Agasha’s insights into the true nature of the Elements grant you a +1k0 bonus to Spell Casting Rolls with non-Void spells and a +1k1 bonus to all Spellcraft Skill rolls. If you spend 10 points on Agasha as an Ancestor, you are one of her most favored descendents and learn the secret spell “Transmute.” Demands: Agasha was a pacifist, and if you ever serve in war she will abandon you. However, she was once kidnapped by goblins, so she will not abandon a descendent who wages war against the Shadowlands (only).", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "dragon"}, {"id": "ancestor_dragon_togashi_yamatsu", "nome": "Ancestor, Togashi Yamatsu", "tipo": "ancestral", "custo": 7, "descricao": "The tattooed man who captured Iuchiban’s soul during the Bloodspeaker’s second rampage has no direct blood descendents, but his spirit sometimes appears to guide later tattooed men—you may only take Yamatsu as an Ancestor if you are a member of the Dragon tattooed orders. Yamatsu’s favor grants two Ranks of Magic Resistance that only apply against maho. In addition, his courageous spirit grants you a +2k2 bonus to any Willpower roll to resist being possessed or magically controlled. Demands: Yamatsu will abandon you if you ever gain Taint of 1.0 or higher, or if you ever willingly use maho or a Shadowlands power.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "dragon"}, {"id": "ancestor_lion_kitsu", "nome": "Ancestor, Kitsu", "tipo": "ancestral", "custo": 6, "descricao": "The spirit once known as Soli Tendo, Kitsu took human form to found the Kitsu family and died in defense of the human clan he joined so reluctantly. A true-blooded descendent of Kitsu who gains his favor can detect the presence of spirits and spirit portals. (This is a Perception roll, normally TN 25, although the GM may raise it for obscure or well-hidden spirits or portals). In addition, Kitsu’s guidance grants you +1k1 to all Lore: Spirit Realms rolls. Demands: Kitsu abandons you if you ever willingly harm a non-corrupted member of the five ancient races (or one of their descendants), or if you ever willingly cooperate with a Tsuno.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "lion"}, {"id": "ancestor_lion_matsu_hitomi", "nome": "Ancestor, Matsu Hitomi", "tipo": "ancestral", "custo": 7, "descricao": "Hitomi was one of the greatest heroes of the Lion Clan, a woman of faultless honor and courage. If you are honored with her guidance, her unshakable faith in Bushido grants you a +1k1 bonus to all rolls to resist Temptation, Intimidation, and Fear effects. Demands: Hitomi abandons you if you ever knowingly betray your daimyo or the Lion Clan, or if your Honor ever drops below 5.0.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "lion"}, {"id": "ancestor_mantis_moshi_azami", "nome": "Ancestor, Moshi Azami", "tipo": "ancestral", "custo": 6, "descricao": "Moshi (formerly Isawa) Azami received the blessing of Lady Sun and shared her insight with her followers, leading the Centipede to become the most devout followers of the Sun Goddess anywhere in the Empire. Prior to the twelfth century Azami is solely an ancestor for the Centipede Clan. Her guidance bestows the favor of the Sun upon you—you suffer no ill effects from the Sun (e.g. dehydration, sunburn, etc) and gain Reduction of 5 against fire (normal or magical). Demands: Azami was a profoundly pious woman. She will leave you if you commit any act of impiety or blasphemy against the Fortunes or the Celestial Heavens (deliberately or accidentally).", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "mantis"}, {"id": "ancestor_mantis_osusuki_akomachi", "nome": "Ancestor, Osusuki & Akomachi", "tipo": "ancestral", "custo": 5, "descricao": "The two ancestors known as Osusuki and Akomachi were actually kitsune spirits who forged an alliance with the nascent Fox Clan. They took human form, one man and one woman, and married into the Kitsune family, bonding the two groups by blood forever. Their guidance will only be bestowed on members of the Kitsune family who can claim a direct blood connection. The attention of Osusuki and Akomachi allows you to speak with animals and animal shapeshifter spirits; furthermore, their wisdom allows you to always find food and water in the wilderness. Demands: Ososuki and Akomachi remain deeply tied to the animal spirits who birthed them. They will abandon you if you ever voluntarily or knowingly kill an animal or an animal spirit (except for self-defense, which they forgive).", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "mantis"}, {"id": "ancestor_phoenix_isawa", "nome": "Ancestor, Isawa", "tipo": "ancestral", "custo": 12, "descricao": "The man known as Isawa was unquestionably the greatest shugenja in Rokugan, perhaps in the world, at the time the Kami fell to earth. His power over the Elements was of such potency that Shiba, a son of the Heavens, bent knee and pledged to protect Isawa’s line for all time in order to gain his aid against Fu Leng. Those who are honored with Isawa’s guidance gain +1k1 on all Spellcraft (Spell Research) rolls and learn 1 additional spell each time they gain a Shugenja School Rank. Demands: Isawa was a proud man who believed his family’s magic superior to all others. He abandons you if you ever lose a magical or scholarly competition with someone who is not themselves of the Isawa family.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "phoenix"}, {"id": "ancestor_phoenix_naka_kaeteru", "nome": "Ancestor, Naka Kaeteru", "tipo": "ancestral", "custo": 10, "descricao": "The man called Kaeteru lived when the Empire was young. His thirst for knowledge led him to wander the Empire as a monk, learning all he could and passing it on to others who wished to learn as well. Although it was never his intention, he gathered many followers and students and became known as a great teacher. Eventually he was invited to the Phoenix lands so they might learn from him as well. Due to his incredible wisdom and experience, Kaeteru was named the first Grandmaster of the Elements by the Phoenix, and awarded the spiritual title of Naka. The first Grandmaster of the Elements spent much of his life in simple contemplation of the Elements. If you are honored with his guidance, his enlightened insights allow you to use the Meditation skill (two hours, skill roll at TN 30) to regain 1 Spell Slot in each Ring. Demands: Kaeteru was detached from mortal concerns and will abandon any descendent who becomes too involved in worldly matters. This may be represented mechanically by your character acquiring more than 3 Skill Ranks in Courtier or any Merchant or Low skill. Role-play can and should impact this as well, and the GM should adjudicate whether a character with Kaeteru’s guidance is involving himself too deeply in worldly affairs such as politics or money.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "phoenix"}, {"id": "ancestor_scorpion_yogo", "nome": "Ancestor, Yogo", "tipo": "ancestral", "custo": 6, "descricao": "The former Phoenix, originally husband to Asako, who was cursed by Fu Leng to betray the one he loved. Yogo joined the Scorpion Clan and started a new family there, studying the techniques that became Yogo ward magic. Yogo’s guidance grants you a +1k1 bonus to the Spell Casting Roll when casting any Wards spell, but due to your blood connection to him you automatically gain Bad Fortune: Yogo Curse for no points. Demands: Yogo abandons you if you ever fall in love, since this means you will succumb to his curse.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "scorpion"}, {"id": "ancestor_scorpion_soshi_saibankan", "nome": "Ancestor, Soshi Saibankan", "tipo": "ancestral", "custo": 5, "descricao": "The founder of Rokugan’s modern law-enforcement system was a clever and eccentric man who was nonetheless dedicated to maintaining law and order in a fractious Empire. The guidance of this famous judge grants you a bonus of +3k1 (rather than the usual +1k1) whenever you spend a Void Point on a roll using the Perception Trait or the Lore: Law skill. Demands: Saibankan was a loyal Scorpion but also a man deeply dedicated to upholding law and order. If you ever knowingly break the law or allow another to break it in your presence, Saibankan will abandon you… unless you did so on the orders of your superiors within the Scorpion Clan.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "scorpion"}, {"id": "ancestor_unicorn_otaku", "nome": "Ancestor, Otaku", "tipo": "ancestral", "custo": 7, "descricao": "The founder of the Otaku (later Utaku) family and the first Unicorn Clan Thunder, Otaku was a woman who founded a family led by women. She will only offer her guidance on women descended from her line. Otaku’s wisdom bestows an empathic connection to horses, granting you a +1k1 bonus to all Horsemanship skill rolls. Otaku’s ferocity and determination grant you a +1k0 bonus to attack rolls against male opponents Demands: Otaku will abandon you if you are ever deliberately cruel to a horse or if you ever challenge a man (whether to a duel or a competition) and then lose.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "unicorn"}, {"id": "ancestor_unicorn_iuchi", "nome": "Ancestor, Iuchi", "tipo": "ancestral", "custo": 8, "descricao": "Iuchi studied and mastered the ways of foreign magic, enabling the Unicorn to survive in the hostile world beyond the Burning Sands. His insights gave rise to the unique Unicorn style of magic known as meishodo. The guidance of Iuchi is bestowed on shugenja of his bloodline, and allows them to approach Rokugani spells in unconventional ways. While his spirit remains with you, you do not have a Deficient Element. Demands: So long as you wish to retain Iuchi’s favor, you may never pass up a chance to learn more about magic, even dangerous or blasphemous magic. Just because you know about it doesn’t mean you’ll use it, after all…", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "unicorn"}, {"id": "ancestor_spider_chuda_bikimi", "nome": "Ancestor, Chuda Bikimi", "tipo": "ancestral", "custo": 3, "descricao": "Chuda Bikimi was a corrupt, ruthless, and utterly evil maho-tsukai, a terrible phantom who moved throughout the Empire like a blade of darkness. He snatched victims from their beds, from their dojo, from all imaginable locations, never once seen by any save his victims. All those who were kidnapped met terrible fates in necromantic maho rituals. Even beyond death, Bikimi’s legacy persists and he bestows his sinister blessings on those engaged in similar evil schemes. His guidance grants you a +1k0 bonus to any Stealth Skill Roll. If you are a shugenja who practices maho, you may instead expend a spell slot to gain a +1k1 bonus to a Stealth Skill Roll. Demands: Bikimi has no respect for those who are foolish enough to expose themselves. If you ever willingly reveal yourself to an enemy, Bikimi will abandon you forever, with no chance to regain his favor.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "spider"}, {"id": "ancestor_spider_yogo_junzo", "nome": "Ancestor, Yogo Junzo", "tipo": "ancestral", "custo": 6, "descricao": "Once a lord of the Scorpion, Yogo Junzo’s fury at the dissolution of his clan following the Scorpion Clan Coup led him to betray his duty and open the Black Scrolls containing Fu Leng’s essence. He became a self-willed undead monstrosity and led a Shadowlands army into Rokugan, assailing temples and monasteries and putting dozens of great libraries to the torch. The effects of his campaign of destruction still haunt the Empire generations later. His dark blessings allow you to call on the most dire and blasphemous knowledge to enhance your power. For each Forbidden Knowledge Advantage you possess, you gain a bonus of +2 to the total of all Spellcasting Rolls, +4 if the roll is for casting a maho spell. You gain the same bonus for every Rank of Taint you possess. Demands: Junzo demands you follow him down the path of dark knowledge and ever-greater power. If you are ever presented with an opportunity to learn new forbidden knowledge (or to gain a new instance of the Forbidden Knowledge Advantage) and do not take it, even to preserve your reputation or secrecy, Junzo abandons you.", "livro": "Great Clans (Grandes Clãs)", "pagina": "", "cla4e": "spider"}], "katas": [{"id": "north_wind_style", "nome": "North Wind Style", "mastery": "4", "elemento": "air", "descricao": "You may add your Air Ring to the total of any attack roll made while attempting the Increased Damage Maneuver.", "requisitos": [], "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "south_wind_style", "nome": "South Wind Style", "mastery": "4", "elemento": "air", "descricao": "You may add your Air Ring to the total of any attack roll made while attempting the Called Shot or Knockdown Maneuvers.", "requisitos": [], "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "the_power_of_the_mountain", "nome": "The Power of the Mountain", "mastery": "3", "elemento": "earth", "descricao": "When this Kata is activated, you reduce your Armor TN by an amount up to your Earth Ring; this lasts until you deactivate the Kata. All damage rolls you make while this Kata is in effect have their totals increased by the same amount.", "requisitos": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "the_strength_of_the_mountain", "nome": "The Strength of the Mountain", "mastery": "3", "elemento": "earth", "descricao": "When this Kata is activated, you reduce your Initiative Score by an amount up to your Earth Ring. (This cannot reduce your Initiative below 0.) This Initiative penalty lasts until you deactivate the Kata. While this Kata is in effect, your Armor TN is increased by the same amount.", "requisitos": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "lee_of_the_stone", "nome": "Lee of the Stone", "mastery": "4", "elemento": "earth", "descricao": "While you are in the Defense or Full Defense Stances, your Armor TN is increased by an additional amount equal to your Earth Ring", "requisitos": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "strike_as_the_avalanche", "nome": "Strike as the Avalanche", "mastery": "3", "elemento": "earth", "descricao": "When using the Heavy Weapons Skill, your Strength is considered one Rank higher for the purposes of determining damage.", "requisitos": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "weathered_and_unbroken", "nome": "Weathered and Unbroken", "mastery": "5", "elemento": "earth", "descricao": "Your Water is considered two Ranks lower (to a minimum of 1) for the purpose of movement. All attack rolls made with the Heavy Weapons Skill gain the benefit of one Free Raise which may only be used for the Knockdown Maneuver.", "requisitos": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "waves_upon_the_breakers", "nome": "Waves upon the Breakers", "mastery": "3", "elemento": "water", "descricao": "This kata channels a samurai’s chi such that it enhances their natural strength and focus and brings it to bear on the battlefield. When this kata is active and you are wielding a weapon in which you have at least three skill ranks, your damage is increased by +1k0.", "requisitos": [], "livro": "Book of Water (Livro da Água)", "pagina": ""}, {"id": "leaves_in_the_stream", "nome": "Leaves in the Stream", "mastery": "3", "elemento": "water", "descricao": "This kata teaches the samurai to embrace the flowing speed of water, allowing him to move significantly faster across the battlefield. While this kata is active, you may reduce your Armor TN by up to 5 x your Water (but cannot reduce it below 5). In return, you may increase your maximum possible movement distance for the Round by the same amount.", "requisitos": [], "livro": "Book of Water (Livro da Água)", "pagina": ""}, {"id": "power_of_the_tsunami", "nome": "Lee Power of the Tsunami", "mastery": "4", "elemento": "water", "descricao": "While this kata is active, once per Round when attacking an opponent you may ignore an amount of Reduction equal to your Water Ring. For example, if you possess Water 4 and attack an opponent with Reduction 5 while this kata is active, once per Round that enemy would be treated as if he only possessed Reduction 1.", "requisitos": [], "livro": "Book of Water (Livro da Água)", "pagina": ""}, {"id": "strength_of_the_crab", "nome": "Strength Of The Crab", "mastery": "3", "elemento": "earth", "descricao": "While wearing Armor and in the Attack Stance, your armor provides an additional +2 Reduction", "requisitos": [{"campo": "crab_bushi", "tipo": "tag", "texto": "Crab Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_crane", "nome": "Strength Of The Crane", "mastery": "3", "elemento": "air", "descricao": "When fighting with a sword or spear you add an amount equal to your Honor Rank - 3 (minimum 1) to your Armor TN", "requisitos": [{"campo": "crane_bushi", "tipo": "tag", "texto": "Crane Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_dragon", "nome": "Strength Of The Dragon", "mastery": "3", "elemento": "fire", "descricao": "While wielding a katana in your main hand and a wakizashi in your off hand, you gain a +3 bonus to your Armor TN", "requisitos": [{"campo": "dragon_bushi", "tipo": "tag", "texto": "Dragon Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_lion", "nome": "Strength Of The Lion", "mastery": "3", "elemento": "water", "descricao": "One per Round during the Reactions stage, you may add +3 to the Initiative Score of one ally in a skirmish. This effect can stack, but the kata's benefit disappears immediately if the kata is no longer active", "requisitos": [{"campo": "lion_bushi", "tipo": "tag", "texto": "Lion Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "son_of_storms", "nome": "Son Of Storms", "mastery": "3", "elemento": "water", "descricao": "When attacking with a Small melee weapon, any Reduction an opponent possesses is decreased by 1", "requisitos": [{"campo": "lion_akodo_bushi_school", "tipo": "tag", "texto": "Akodo Bushi School"}, {"campo": "scorpion_shosuro_infiltrator_school", "tipo": "tag", "texto": "Shosuro Infiltrator School"}, {"campo": "mantis_yoritomo_bushi_school", "tipo": "tag", "texto": "Yoritomo Bushi School"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_mantis", "nome": "Strength of The Mantis", "mastery": "3", "elemento": "air", "descricao": "The attack penalty for ranged attacks fired against opponents currently in melee range is reduced by 3", "requisitos": [{"campo": "mantis_bushi", "tipo": "tag", "texto": "Mantis Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "dance_of_the_winds", "nome": "Dance Of The Winds", "mastery": "3", "elemento": "air", "descricao": "When wielding a polearm, or a spear, your Initiative Score is increased by 3", "requisitos": [{"campo": "crane_daidoji_iron_warriors", "tipo": "tag", "texto": "Daidoji Iron Warriors"}, {"campo": "phoenix_shiba_bushi_school", "tipo": "tag", "texto": "Shiba Bushi School"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_phoenix", "nome": "Strength Of The Phoenix", "mastery": "3", "elemento": "void", "descricao": "Once per Turn when you declare a Guard Action, you may increase the Armor TN of the person you are guarding by an additional +3", "requisitos": [{"campo": "phoenix_bushi", "tipo": "tag", "texto": "Phoenix Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_scorpion", "nome": "Strength Of The Scorpion", "mastery": "3", "elemento": "fire", "descricao": "Once per Turn after successfully making the Feint Maneuver, your damage total is increased by +3 Wounds", "requisitos": [{"campo": "scorpion_bushi", "tipo": "tag", "texto": "Scorpion Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_unicorn", "nome": "Strength Of The Unicorn", "mastery": "3", "elemento": "water", "descricao": "While you are mounted, your steed gains a bonus of +3 to its Armor TN and an additional 3 Reduction", "requisitos": [{"campo": "unicorn_bushi", "tipo": "tag", "texto": "Unicorn Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "art_of_ninjutsu", "nome": "Art of Ninjutsu", "mastery": "5", "elemento": "water", "descricao": "Once per Round you may calculate the distance of a Move Action as if your Water is equal to your Stealth Skill Rank. This does not change the maximum distance you can move in a Round", "requisitos": [{"campo": "spider_daigotsu_bushi_school", "tipo": "tag", "texto": "Daigotsu Bushi School"}, {"campo": "scorpion_bayushi_bushi_school", "tipo": "tag", "texto": "Bayushi Bushi School"}, {"campo": "crane_ob_daidoji_scout_school", "tipo": "tag", "texto": "Daidoji Scout School"}, {"campo": "shosuro_actor", "tipo": "tag", "texto": "Shosuro Actor School"}, {"campo": "scorpion_shosuro_infiltrator_school", "tipo": "tag", "texto": "Shosuro Infiltrator School"}, {"campo": "goju_ninja", "tipo": "tag", "texto": "Goju Ninja School"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}, {"id": "strength_of_the_spider", "nome": "Strength Of The Spider", "mastery": "3", "elemento": "earth", "descricao": "Once per Round if you successfully cause at least 15 Wounds to your opponent, he suffers a -3 penalty to the total of all rolls on his next Turn", "requisitos": [{"campo": "spider_bushi", "tipo": "tag", "texto": "Spider Bushi"}], "livro": "Great Clans (Grandes Clãs)", "pagina": ""}], "kihos": [{"id": "eye_of_the_eagle", "nome": "Eye of the Eagle", "mastery": "5", "elemento": "air", "tipo": "internal", "descricao": "The power of the wind can carry messages and information well beyond the boundaries of human weakness. Some natural creatures with an affinity for Air already possess remarkable abilities that go unnoticed and unappreciated, and certain monks can mimic these abilities. While this Kiho is active, you may as a Complex Action focus your chi by remaining utterly still and unmoving. Once this is done, so long as you maintain concentration and do not move from your current position, you can see a number of miles equal to your School Rank. The level of detail is sufficient to notice things like the physical characteristics of individuals, but not so acute as to allow for extremely fine detail, such as reading.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "the_winds_vision", "nome": "The Wind's Vision", "mastery": "4", "elemento": "air", "tipo": "internal", "descricao": "This Kiho was developed early on by the more martial sects of the Brotherhood, but was rarely learned or used until the Wind's Grace Order adopted it for use in its training. By focusing on the omnipresence of Air and letting go of mundane perception, you are able to fire an arrow at a target that is out of sight but may be in range. The arrow must still be able to travel in a straight line to the target—it will not suddenly pierce stone or turn corners, for example, but firing through a paper screen, amid total darkness, or through heavy smoke are all possible. You must know the target exists and its approximate location within 30 feet of its actual location.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "calling_the_east_wind", "nome": "Calling the East Wind", "mastery": "5", "elemento": "air", "tipo": "martial", "descricao": "The East Wind is generally considered exotic and fraught with mystery, most likely because it blows from the sea and the strange lands that exist somewhere far across its waters. This Kiho calls on that same wind to buoy the monk into the air and carry him to his opponent, delivering not an exotic or mysterious magical effect but rather simply a violent attack. When this Kiho is activated, you make a single unarmed kick attack. As part of this attack, you may leap through the air a significant distance, up to a maximum equal to your Air Ring x 10 feet. The power of this sudden movement adds an additional +1k0 damage to any successful attack landed as a result of this Kiho, and you gain one Free Raise toward use of the Knockdown Maneuver on this attack.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "censure_of_thunder", "nome": "Censure of Thunder", "mastery": "7", "elemento": "air", "tipo": "martial", "descricao": "The power of Thunder is not something that can be dismissed by any adherent of the Brotherhood, even those who favor the teachings of the Tao over the precepts of Fortunism. The Thunder Dragon, regardless of its dispensation, favors the bold and the heroic in all things, and those brothers who choose to face armed opponents with an empty hand are well within their rights to call upon its favor with this powerful Kiho. If you deliver a successful unarmed atemi strike while using this Kiho, your target immediately suffers 1k1 Wounds from the minor electrical shock that accompanies your touch. He also automatically drops his weapon as if suffering from a successful Disarm Maneuver, as your strike interrupts the flow of chi through his body. The target may spend two Void Points to negate the Disarm, but if he does so he suffers an additional 2k2 Wounds from the more severe electrical shock. The damage caused by this Kiho bypasses Reduction conferred by armor.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "hurricane_palm", "nome": "Hurricane Palm", "mastery": "7", "elemento": "air", "tipo": "martial", "descricao": "The raging force of a hurricane is nothing compared to the strength of a properly prepared spirit, or so the Tao of Shinsei says. Certainly there are many among the Brotherhood who seem able to prove such a point true. By externalizing their chi, certain monks are able to hurl away their foes, even those prepared for such an impact. After making a successful unarmed strike, you spend one Void Point. Your strike inflicts only half normal damage (rounded down), but it knocks your opponent back a number of feet equal to twice your Air Ring, after which he falls Prone. Any opponent successfully struck by this attack is moved by the Kiho's effect, even if they do not suffer any Wounds from the blow.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "touch_of_the_storm", "nome": "Touch of the Storm", "mastery": "6", "elemento": "air", "tipo": "martial", "descricao": "By drawing on the essence of the Elements themselves, a Brotherhood monk is capable of pulling the fury of the air from his surroundings and unleashing it upon an opponent. This Kiho requires a successful atemi strike. When such an attack is landed successfully, you make a Contested Air Roll against your opponent. If you are successful, your opponent suffers damage (with a DR equal to your Air Ring) in the form of a violent electrical discharge from the air around him. The damage from this Kiho ignores all forms of Reduction unless it specifically mentions electrical damage.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "inaris_wrath", "nome": "Inari's Wrath", "mastery": "8", "elemento": "air", "tipo": "mystical", "descricao": "It is in the Air that the essence of the seasons is contained. The warm humid air is what most people remember about summer, and the biting frigid wind is the most severe memory of winter. A true master of the paths of Air can draw it into his own body and use his chi to cool it, then exhale it and strike with all the wrath of Inari, the Fortune of Rice, whose wrathful aspect is the Frost Dragon. You must spend a Void Point as a Free Action to activate this Kiho, then as a Complex Action you take a deep breath and hold it. You unleash the breath on the following Round as a Complex Action. It creates a cone of freezing air extending a number of feet equal to your School Rank x 5, as broad at the end as your School Rank x 2 in feet. Any living creature caught within the area of effect suffers cold damage with a DR equal to your Air Ring. At the GM's discretion, certain physical materials may suffer damage as well.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "strike_through_the_wind", "nome": "Strike through the Wind", "mastery": "5", "elemento": "air", "tipo": "mystical", "descricao": "Most mortal souls never give a moment's consideration to the air they breathe and move through almost every second of their physical existence. The notion that Air can contain force or become as hard as steel is something they never even consider. Some monks, however, are able to transmit force through the Air as if it were an extension of their body. You channel the force of your blows through the air, striking targets at range as if they were at arm's length. You must spend a Void Point as a Free Action to activate this Kiho. While this Kiho is active, you make unarmed melee attacks as a Complex Action, and your melee attacks may target opponents as far away as your School Rank x 25 feet.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "thunders_word", "nome": "Thunder's Word", "mastery": "6", "elemento": "air", "tipo": "mystical", "descricao": "This strange Kiho was allegedly developed by the monks who adhere to teachings inspired by the founder of the Mantis Clan, Kaimetsu-Uo. The sect's name causes an obvious association with the Mantis Clan, which in turn leads many samurai to misinterpret its philosophies; in truth, the monks of Kaimetsu-Uo are generally rather introspective and are devoted primarily to the Fortunes. Which, truthfully, makes their development of this Kiho even stranger than its effect. This Kiho invokes the power of the Thunder Dragon, a patron of the Mantis Clan, and fills the lungs with the power of Thunder. As a Complex Action you draw a deep breath and shout a single word of power, a command filled with the essence of the Thunder Dragon itself. All living beings capable of hearing your shout must make a Contested Air Roll against you (each of them rolls separately and compares to a single roll by you). Those who fail the roll are Dazed for a number of rounds equal to your Air Ring.", "livro": "Book of Air (Livro do Ar)", "pagina": ""}, {"id": "shadowed_mountain", "nome": "Shadowed Mountain", "mastery": "6", "elemento": "earth", "tipo": "internal", "descricao": "Many sohei orders are considered reckless and wild by outsiders, and to some extent this is true. The Temple of Osano-Wo and the fierce warrior monks of the Spider Clan are brutal fighters who focus far more on offense than on protecting themselves. Many of them simply rely on their physical endurance to carry them through the fight, while others master the Shadowed Mountain Kiho to surprise and confuse their enemies. When this Kiho is activate, you may choose to enter the Full Defense Stance immediately before you are attacked. This does not have to be the first time you are attacked after activating this Kiho, but it may only be done once per activation. After you activate this kiho, you cannot change Stances during your next opportunity to do so (during your normal chance on your Turn or due to another effect). This Kiho lasts for the remainder of the day or until used.", "livro": "Book of Earth (Livro da Terra)", "pagina": "205"}, {"id": "depths_of_the_world", "nome": "Depths of the World", "mastery": "4", "elemento": "earth", "tipo": "internal", "descricao": "Earth and Water are similar in that they have seemingly endless depths to their power and influence. However, where Water is relentless in its strength and power, the Earth knows no bounds in its purity and focus. This basic Earth Kiho is taught to monks of all aspects of the Brotherhood, as it helps them re-focus and center their chi in stressful or dangerous situations. When this Kiho is activated, you may immediately roll to recover from a non-permanent Condition or other effect that allows rolls for recovery, such as Dazed. This Kiho can only be activated as a Complex Action, but may be activated (spending the Void point) even when you are not allowed to perform actions, such as when you are Stunned.", "livro": "Book of Earth (Livro da Terra)", "pagina": "206"}, {"id": "harmony_in_earth", "nome": "Harmony in Earth", "mastery": "6", "elemento": "earth", "tipo": "internal", "descricao": "More of a meditative art than many Kiho, Harmony in Earth is often used as a lesson in how to understand purity and harmony in the Realm of Mortals and the Celestial Order. This Kiho is a favorite of orders and sects that delve into the mysteries of the supernatural and mystical lore, though it is also known among several orders that face such threats in battle. By aligning his Earth with the natural world, the Monk gains the ability to perceive with an additional sense. When this Kiho is activated, you must remain perfectly still for a number of Turns equal to ten minus your Earth Ring. Once this is accomplished, you are immediately able to detect any spiritual and physical impurities within a range of fifty feet times your Earth for one Round. (“Impurity” in this sense is not confined to things such as the Taint, but encompasses anything that the GM judges to be out of place either physically or spiritually.) You learn the direction of the impurity, its general nature (Shadowlands Taint, poison, disease, things not native to Ningen-do), and its relative strength compared to others in the area. The GM may choose to allow you to make an appropriate Lore Skill roll for the subject in question to learn one more piece of useful information of his choice. You will only sense a total number of impurities equal to your Void, detecting the strongest ones first. This Kiho is not precise in pinpointing the location of the impurity. You will know a general direction but not a specific location. Intelligent beings who could be detected by this Kiho (such as the Lost) can attempt to defeat the Kiho’s power by making a Contested Earth Roll against you. (The GM may substitute a different type of Contested Roll if the specific circumstance seems in his judgment to require it.)", "livro": "Book of Earth (Livro da Terra)", "pagina": "206"}, {"id": "the_rolling_avalanche", "nome": "The Rolling Avalanche", "mastery": "5", "elemento": "earth", "tipo": "martial", "descricao": "The principles and strengths of Earth usually deal with the Element when it is at rest, but the fury of moving Earth can be a terrible thing. Sohei who focus on a study of Earth find this Kiho extremely useful, as it channels the usually benign Element into devastating power. This Kiho is delivered via an atemi attack that deals normal unarmed damage. However, if the strike is successful, your damage roll is increased by +Xk0, where X is your Earth Ring.", "livro": "Book of Earth (Livro da Terra)", "pagina": "206"}, {"id": "earth_palm", "nome": "Earth Palm", "mastery": "6", "elemento": "earth", "tipo": "martial", "descricao": "While the Elements of Fire and Water are highly important for the success of a warrior (or an army) in battle, without a proper harmony with Earth, both of them crumble. This rare Kiho assaults the victim’s very Earth, disrupting its harmony with the other Elements, and it is not widely taught amongst the Brotherhood. Those who master it are greatly feared in combat, as they can reduce the most stalwart combatant to a helpless, stumbling wreck in just a few strikes. This Kiho is activated with an atemi strike. If the strike is successful, you must declare whether you are attacking your target’s Fire or Water. If you attack the target’s Water, he suffers a -4k0 penalty to all damage rolls. If you attack the target’s Fire, he is forced thereafter to make two Raises with no benefit on every attack roll. (However, these Raises do not count against the maximum number of Raises the target can make for the roll.) These effects may be combined through multiple applications of the Kiho, and both last a number of Rounds equal to your Earth Ring, ending on the Reactions stage of the final Round. Each re-application of the Kiho resets the duration for the chosen effect. However, you cannot use this Kiho more than once per Turn.", "livro": "Book of Earth (Livro da Terra)", "pagina": "206"}, {"id": "bishamons_grasp", "nome": "Bishamon's Grasp", "mastery": "7", "elemento": "earth", "tipo": "kharmic", "descricao": "Rokugani history is full of tales about quiet and unassuming monks fending off multiple attackers, all the while never striking them down. The monk instead waits for his many opponents to wear themselves out in the futility of their fury. Patient members of the Brotherhood tend to prefer this style of combat, though it often earns them the undying ire of their humiliated foes. This Kiho is common among monks who understand the need to defend oneself but prefer not to beat someone senseless.This Kiho can only be activated when you are in the Defense or Full Defense Stance. While the Kiho is active, on your Turn you may make Grappling attack rolls as Free Actions against opponents who have attacked you since your last Turn. (You may make one such Free Action attack against each qualifying opponent, and this ability overturns the normal rulebook constraint on attacking while in these Stances.) Opponents in a Grapple which you control while using this Kiho may be Thrown as a Free Action rather than a Complex Action; however, if the GM allows Throws in Grapples to cause damage, the damage roll suffers a -1k1 penalty. While this Kiho is active, you may remain in the Defense or Full Defense Stances while maintaining a Grapple.", "livro": "Book of Earth (Livro da Terra)", "pagina": "206"}, {"id": "rising_mountain", "nome": "Rising Mountain", "mastery": "6", "elemento": "earth", "tipo": "kharmic", "descricao": "One of the greatest lessons of Earth is not its endurance, but its resilience. As a man chips away at a stone, he finds harder and harder stone beneath. The strength of one who would break a mountain stone by stone will fail long before the strongest layers are even seen. So, too, does a master of this Kiho become more and more difficult to harm as an attacker tries harder and harder to do so. Once activated, this Kiho lasts a number of Rounds equal to your Insight Rank +1. While this Kiho is active, every time an attacker makes a Raise when attacking or otherwise taking an offensive combat action against you (not including spells), you gain Reduction equal to twice the number of Raises made. (This effect does not trigger from Free Raises.) The Reduction is gained the moment the Raises are declared; the enemy attack does not have to be successful. These increases in Reduction are cumulative, but the total Reduction gained cannot exceed your Earth x 5. The Reduction lasts until the Kiho is deactivated or the skirmish ends, whichever comes first.", "livro": "Book of Earth (Livro da Terra)", "pagina": "207"}, {"id": "wholeness_in_all", "nome": "Wholeness in All", "mastery": "6", "elemento": "earth", "tipo": "kharmic", "descricao": "An extremely rare Kiho only taught among some of the older Orders, this remarkable ability destroys toxin, disease, and other impurities in the body of the Monk. The focus and calm required to master this Kiho is rare, and the Brotherhood knows it could lead to reckless behavior in the wrong hands. This Kiho can only be activated after two hours of uninterrupted meditation. After the time has passed, you may activate the Kiho as a Complex Action (it can only activate in this manner). You must call a Raise on the activation roll for every mundane poison, disease, or similar non-supernatural effect affecting you. If the roll is successful, your body is purged of a number of such impurities equal to the number of Void Points you have at the time (not counting the Void Point spent to activate the Kiho). All of these remaining Void Points are then spent as part of the Kiho’s effect. This Kiho does not work on most supernatural afflictions, such as the Shadowlands Taint or magical plagues, but the GM has discretion on whether unusual or semi-magical conditions may be cleansed by it.", "livro": "Book of Earth (Livro da Terra)", "pagina": "207"}, {"id": "tattoo_bear", "nome": "Bear", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "The bear is a primal being of nature, a force to be reckoned with even at its weakest moments. Those who possess this tattoo can summon that same incredible strength and endurance, although not simultaneously. While this tattoo is active, you may choose to increase your Stamina by an amount equal to your School Rank. Alternatively, you may instead choose to increase your Strength by an amount equal to half your School Rank, rounding up.", "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "the_minds_fire", "nome": "The Mind's Fire", "mastery": "4", "elemento": "fire", "tipo": "internal", "descricao": "The truly enlightened mind can easily grasp that Fire is the source of creation and inspiration as well as simple destruction. By focusing his Fire-aligned chi into ascendance, a monk can gain incredible clarity. When active, this Kiho grants you a bonus of +2k2 to all Intelligence-based Skill Rolls. When the Kiho ends you are immediately Fatigued.", "livro": "Book of Fire (Livro do Fogo)", "pagina": ""}, {"id": "sever_the_dark_lords_touch", "nome": "Sever the Dark Lord's Touch", "mastery": "5", "elemento": "fire", "tipo": "mystical ", "descricao": "A mind at one with the universe can perceive and affect the bonds that tie the physical world to the world of the spirit, even when the world in question is as insidious and despicable as the Realm of Evil. While this Kiho is active, a successful atemi strike against an unintelligent undead creature results in a Contested Roll, pitting your Fire against the undead 's Shadowlands Taint. If you are successful, the undead is instantly destroyed, its connection to Jigoku severed.", "livro": "Book of Fire (Livro do Fogo)", "pagina": ""}, {"id": "sever_the_dark_lords_touch_kuni", "nome": "Sever the Dark Lord's Touch", "mastery": "4", "elemento": "fire", "tipo": "mystical ", "descricao": "A mind at one with the universe can perceive and affect the bonds that tie the physical world to the world of the spirit, even when the world in question is as insidious and despicable as the Realm of Evil. While this Kiho is active, a successful atemi strike against an unintelligent undead creature results in a Contested Roll, pitting your Fire against the undead 's Shadowlands Taint. If you are successful, the undead is instantly destroyed, its connection to Jigoku severed. (Kuni)", "livro": "Book of Fire (Livro do Fogo)", "pagina": ""}, {"id": "seven_storms_fist", "nome": "Seven Storm's Fist", "mastery": "6", "elemento": "fire", "tipo": "martial", "descricao": "The chi of Fire flows through the body as all forms of chi do, but when its flow is disrupted, it can be particularly painful and disorienting for those not accustomed to the sensation. When this Kiho is active, a successful atemi strike against an opponent forces a COntested Fire Roll between you and that opponent. If you are successful, your opponent is Stunned for one Round.", "livro": "Book of Fire (Livro do Fogo)", "pagina": ""}, {"id": "tattoo_volcano", "nome": "Volcano", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "While this tattoo is active, the skin of the monk's torso and upper limbs takes on the appearance of lava, a surface of searing-hot blackness riven with brightly glowing fiery cracks. Any flammable object with strikes the monk's body - including wooden weapons and arrows - will sear to ash within moments, and consequently the monk is considered to have Reduction 5 against such attacks (due to their burning up before they can deliver the full impact of their blows). Metal weapons inflict normal damage, but the wielders of such weapons must succeed in Contested Fire rolls against the monk or be forced to drop their weapons due to the intense heat (Sacred Weapons and nemuranai are immune to this effect). Unarmed attacks (including the Strike option while grappling) inflict normal damage and suffer no ill efects, since their impact does not crack the fiery surface of the lava. The Volcano Tattoo only affects the monk's torso and upper limbs, so its effects may be evaded by the use of the Called Shot Maneuver to strike the lower limbs, head, etc. The GM may rule that unarmed strikes that strike with great force (beyond 2 kept dice) do crack the surface of the lava, causing the attacker to suffer Wounds equal to the monk's Fire Ring.", "livro": "Book of Fire (Livro do Fogo)", "pagina": ""}, {"id": "knowledge_from_within", "nome": "Knowledge from Within", "mastery": "4", "elemento": "void", "tipo": "internal", "descricao": "The power of the Void allows a centered monk to sense the presence of other magical effects in the area. You must be meditating or in the Center Stance to activate this Kiho. Once it is active, you become generally aware of the presence of Elemental spell effects and nemuranai (within a radius equal to your Void x10 in feet) so long as you maintain the Kiho. You will know the general direction and nature of the effects/objects (e.g. “a Fire spell in that direction”) but not their specific identity or specific location.", "livro": "Book of Void (Livro do Vazio)", "pagina": ""}, {"id": "mind_no_mind", "nome": "Mind / No-Mind", "mastery": "6", "elemento": "void", "tipo": "mystical", "descricao": "Monks practice meditation in order to attain the thought-free clarity of a pure soul on the path to Enlightenment. This Kiho allows a monk to briefly bestow this clarity on another person… whether or not that person wishes it. You make an atemi strike and a Contested Roll of your Void against your target’s Fire. If you win the Contested Roll, your target’s mind is momentarily purged of all thoughts, and he forgets everything that has happened during the last minute. At the GM’s option, this might also cause the target to be Dazed for one Round. (It may also be noted that this Kiho has helpful applications, such as calming someone who is overwhelmed with fear, rage, grief, or other uncontrolled emotion.)", "livro": "Book of Void (Livro do Vazio)", "pagina": ""}, {"id": "rebuke_of_the_heavens", "nome": "Rebuke of the Heavens", "mastery": "5", "elemento": "void", "tipo": "kharmic", "descricao": "Your holy authority can cow disruptive spirits and weaken their influence. This Kiho may target any one supernatural creature (an entity not native to Jigoku or Tengoku). It is activated as a Complex Action by performing some gesture of spiritual rebuke, such as chanting a sutra, shaking a ringed staff, or forming a mudra with your hands. (This is in addition to the normal roll to activate a Kiho.) Make a Contested Roll of your Meditation / Void against the creature’s highest Ring – if you succeed, the creature suffers a –Xk1 penalty to all rolls, where X is your Monk School Ranks. This penalty continues until the creature is slain or it departs from your presence. This Kiho is only available to monks, not to shugenja.", "livro": "Book of Void (Livro do Vazio)", "pagina": ""}, {"id": "sense_the_balance", "nome": "Sense the Balance", "mastery": "6", "elemento": "void", "tipo": "kharmic", "descricao": "The spiritual balance of individuals can be felt in the flow of their chi. The Air kiho called Harmony of the Mind allows monks to sense a few of another person’s inner secrets, but those who follow the path of Void can do so far more effectively. If you succeed at an atemi strike on your target, you may spend a Void Point to learn the total number of Spiritual Advantages or Disadvantages (one or the other, your choice) which the target possesses. If you succeed in a Contested Void roll, you may also learn the name and specific nature of the Advantage / Disadvantage with the highest point value – e.g. you not only learn the target is Cursed by the Realms, but also which Spirit Realm has cursed him. Subsequent uses of this Kiho against the same target can reveal a new Advantage or Disadvantage each time, until there are no more to learn.", "livro": "Book of Void (Livro do Vazio)", "pagina": ""}, {"id": "striking_through_the_void", "nome": "Striking through the Void", "mastery": "7", "elemento": "void", "tipo": "martial", "descricao": "This rare martial Void Kiho allows you to channel the power of the Void into your unarmed strikes. It is controversial within the more peaceful sects of the Brotherhood, who believe that the Void should not be used as a weapon. When active, this Kiho allows you to spend a Void Point on damage rolls for your unarmed strikes (one Void Point per attack).", "livro": "Book of Void (Livro do Vazio)", "pagina": ""}, {"id": "the_world_dissapears", "nome": "The World Disappears", "mastery": "6", "elemento": "void", "tipo": "internal", "descricao": "Those who are approaching the edge of Enlightenment are said to float slightly above the ground, their pure souls buoying them up toward the Heavens. This Kiho allows you to temporarily attain this rarified state. You must be meditating or in the Center Stance to activate this Kiho. Once it is active, you float a few inches above the ground for as long as it remains active, and can move at your normal speed across any surface (ground, water, molten lava) without touching it. This serene disconnection from the ground also makes you immune to Grappling and Entangling attacks while the Kiho remains active.", "livro": "Book of Void (Livro do Vazio)", "pagina": ""}, {"id": "musubi", "nome": "Musubi", "mastery": "5", "elemento": "water", "tipo": "internal", "descricao": "This kiho invokes the flowing strength and motion of Water to protect the monk. While the kiho is active, the monk moves his staff in a constant whirlwind of motion, swift and relentless yet also graceful and without pause or pattern, guided only by the innate perception of Water. Enemy attacks are deflected away by these motions, suppressed and turned aside by the flow of Water’s power. So long as the Kiho is active and the monk is holding and moving his staff (for mechanical purposes moving the staff in this way is considered a Free Action), the monk adds the combined total of his Water Ring and his Staves Skill Rank to his Armor TN. Furthermore, if the monk devotes more of his time and effort to the whirling and flowing motions of the staff, his defense becomes correspondingly more potent; for each Simple Action in the same Round the monk uses to enhance the Kiho, he may increase his Armor TN by his Water Ring again for that Round. (This additional Armor TN bonus ends at the beginning of the monk’s next Turn.)", "livro": "Book of Water (Livro da Água)", "pagina": ""}, {"id": "dharma_technique", "nome": "Dharma Technique", "mastery": "7", "elemento": "water", "tipo": "martial", "descricao": "A more advanced form of Musubi, this Kiho calls on Water’s defensive powers to protect the monk not only physically but also spiritually. Much like Musubi, this Kiho requires the monk to have a staff and maintain it in motion; however, this Kiho requires the monk to expend a Simple Action on the staff’s movement each Round in order to provide a sufficient focus for his chi. While this Kiho is in effect, the monk has the ability to deflect kami with the Water chi which he focuses through the staff. In game terms, when a spell specifically targets the monk (not an area-effect spell), the monk may make a Contested Roll of his Staves/Water against the shugenja’s Spell Casting roll. If the monk wins the roll, his chi disrupts the spell and disperses it, negating its effects against him. (If the spell is targeting multiple people, the other targets are not protected by the Kiho.) The monk may do this a number of times per skirmish equal to his Water Ring. At the GM’s option, this Kiho may also be able to defend against maho spells, using the pure Water chi to disrupt the kansen. However, the monk must make 3 Raises on the Contested Roll in order to succeed.", "livro": "Book of Water (Livro da Água)", "pagina": ""}, {"id": "tasaii_do", "nome": "Tasaii-Do", "mastery": "6", "elemento": "water", "tipo": "martial", "descricao": "This Kiho focuses the monk’s Water chi offensively, channeling it through his staff in order to overwhelm his opponent. It is activated with an attack in the same manner as an atemi Kiho, but using a staff attack instead of an unarmed attack. After striking his opponent (typically in a chi-focusing location like the head, chest, or stomach), the monk unleashes his chi through the staff and makes a Contested Roll of his Water against the target’s Earth. With a success, the target is Stunned.", "livro": "Book of Water (Livro da Água)", "pagina": ""}, {"id": "tattoo_wave", "nome": "Wave", "mastery": null, "elemento": null, "tipo": "tattoo", "descricao": "This tattoo invokes the mighty power of the tsunami to resist enemy force and drive your opponents to their knees. While this tattoo is active, you gain a +Xk0 bonus (where X is your Insight Rank) to the Contested Strength Roll used to determine the success of a Knockdown maneuver you perform with an unarmed attack. You also gain an identical bonus to resist all enemy Knockdown attempts, regardless of whether they are made unarmed or with weapons.", "livro": "Book of Water (Livro da Água)", "pagina": "189"}], "feiticos": [{"id": "air_kamis_blessing", "nome": "Air Kami's Blessing", "elemento": "air", "mastery": "3", "area": "Caster", "alcance": "Personal", "duracao": "8 Hours", "descricao": "A unique prayer that is as much a meditation as anything else, this spell is only taught in shugenja Schools which have an Air as an Affinity. It causes the Air kami within the soul of the caster to become more properly aligned, giving the caster a far greater grasp on the hearts and souls of other men, along with a certain quickness of reaction. While the blessing lasts, the shugenja may add his Air Ring to the total of all Awareness-based rolls, as well as to his Armor TN. Typically, those who know this spell perform the Blessing each morning during their daily meditations. The effects of this spell cannot be stacked.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "182"}, {"id": "arrows_flight", "nome": "Arrow's Flight", "elemento": "air", "mastery": "1", "area": "one arrow", "alcance": "Touch", "duracao": "3 Rounds", "descricao": "A prayer used by shugenja to aid bushi when an arrow absolutely must hit its target. The shugenja entreats the Air kami to play a game by guiding the arrow, and if the arrow is fired within the duration of the spell, it will unerringly strike its target. (It must still be fired by someone with a minimal understanding of archery - at least one Rank of Kyujutsu.) However, because it is the kami who ultimately ensure the arrow will hit, the shot cannot benefit from the effects of Raises or Techniques.", "tags": ["battle"], "livro": "Book of Air (Livro do Ar)", "pagina": "182"}, {"id": "castle_of_air", "nome": "Castle of Air", "elemento": "air", "mastery": "4", "area": "20' radius around the caster", "alcance": "Self", "duracao": "10 Rounds", "descricao": "The prayer commonly known as Castle of Water protects the caster by creating a physical barrier of water kami to obstruct attackers. The Castle of Air, by contrast, protects the caster by creating a cunning illusion that confuses and bewilders attackers. The Air kami create a circular barrier of false sounds and images, making it incredibly difficult for attackers to actually perceive the correct location of anyone within the bounds of the Castle of Air. An attacker may believe he is striking at the caster when he is actually swinging at empty space. The circular barrier of illusions is centered on the caster. Once cast, it remains in place regardless of whether or where the caster moves. The illusions can only be fully perceived by those who were outside of the Castle of Air when it was cast; those within the Castle when it appears can easily perceive the shadowy, insubstantial nature of the illusions. If foes from outside the Castle attempt to attack those within it, the illusions will try to misdirect or fool them. Mechanically, such attackers must make a Contested Roll of their Perception against the Caster's Air each time they try to attack someone within the Castle. A success means they manage to briefly see through the illusion and may attack normally for that Round (only). A failure means the illusion tricks them and they suffer a -5k0 penalty to their attack rolls that Round. The illusions cannot affect enemy spells, since the Air kami cannot fool other kami.", "tags": ["illusion", "defence"], "livro": "Book of Air (Livro do Ar)", "pagina": "183"}, {"id": "defender_from_beyond", "nome": "Defender from Beyond", "elemento": "air", "mastery": "5", "area": "One summoned spirit", "alcance": "30'", "duracao": "5 minutes", "descricao": "Among the innermost circles of the Kitsu family are the ancestral shugenja who carry the bloodlines of the first kitsu spirits. These secretive shugenja have discovered rituals which can persuade the Air kami to carry a message to Yomi itself, calling for the aid of an ancestral shiryo. Only Kitsu Shugenja may learn this spell, which is a secret of the sodan-senzo order. When the spell is cast, the shugenja beseeches the ancestral spirits of Yomi to send aid. If the Spell Casting Roll succeeds, a shiryo - a spirit from Yomi - will arrive on the scene in five Rounds. Once it arrives, the spirit reclaims its mortal form, but its spiritual nature is easily sensed from the celestial glow which surrounds it. It will offer whatever aid it can to the caster, whether that be advice, knowledge, or combat, but it will not do anything dishonorable. Mechanically, a typical shiryo will have the creature trait of Spirit, and will possess a Rank of 3 in all of its Rings and Traits and a Rank of 4 in any useful Skills. Once the spell's duration expires, the shiryo immediately returns to Yomi. It also leaves for Yomi if its physical body is destroyed (e.g. it is reduced to zero wounds). Although this spell normally calls a \"generic\" shiryo, the GM may opt to allow the shugenja to summon a specific named ancestral spirit with additional Raises. The GM may also choose to have a more powerful or famous shiryo answer the spell if the specific circumstances seem to warrant it. More powerful Shiryo will possess a School as appropriate for their ancestral clan, typically with a School Rank between 3 and 5.", "tags": ["battle"], "livro": "Book of Air (Livro do Ar)", "pagina": "183"}, {"id": "elemental_cipher", "nome": "Elemental Cipher", "elemento": "air", "mastery": "2", "area": "One written page", "alcance": "Touch", "duracao": "One Month", "descricao": "Understanding the ways of the Air reveals the indistinct line that exists between language and cipher. A shugenja can cause a piece of writing to be placed under an elemental cipher, enticing the kami to play a small game with those who read the text. The block of text becomes completely unintelligible unless read by the original author or the intended recipient, whose name is whispered as the spell is cast. Normally, an Elemental Cipher is not breakable by traditional decrypting and the kami will only reveal the true text to the intended recipient. However, other shugenja can decipher the kami's game and read the text by making a Spellcraft / Intelligence roll with a TN equal to the total of the original spell-casting roll.", "tags": ["illusion"], "livro": "Book of Air (Livro do Ar)", "pagina": "184"}, {"id": "flight_of_doves", "nome": "Flight of Doves", "elemento": "air", "mastery": "2", "area": "Story told by one target person", "alcance": "25'", "duracao": "10 minutes", "descricao": "This spell was originally devised by the Shiba Illusionists, and is one of their few significant contributions to the ways of magic in Rokugan. In keeping with the traditions of the Shiba Illusionists, this spell is intended primarily for entertainment, but it can sometimes have more practical applications (such as helping a courier describe his experiences to his lore). The spell invokes the Air kami to \"illustate\" a story being recounted by another individual (designated by the caster). The spirits will supply a visual and auditory illusion to accompany the story, drawing the sounds and images from the mind of the storyteller. The resulting blend of story, sound, and imagery can be quite compelling, and Kakita storytellers have been known to seek out masters of this spell to assist their art.", "tags": ["illusion"], "livro": "Book of Air (Livro do Ar)", "pagina": "184"}, {"id": "freedom_of_the_air", "nome": "Freedom of the Air", "elemento": "air", "mastery": "2", "area": "One house or other residential building", "alcance": "50'", "duracao": "Hours equal to caster's Air", "descricao": "A cleansing ritual used by shugenja when preparing a house or other building for an important even such as a wedding or a festival. The spell entreats the Air kami to raise a soft but carefully controlled wind which sweeps all the dirt, insects, and other filth out of the building. The spell also has a spiritually purifying effect, making evil or malignant spirits reluctant to remain within the dwelling - any kansen, ghosts, or other hostile disembodied spirits within the building will leave for a number of hours equal to the caster's Air. (Evil spirits which are exceptionally strong or which have an extremely strong attachment to the building cannot be banished by this basic spell, however - it is the GM's discretion whether a spirit is strong enough to resist Freedom of the Air.) The spell was originally devised by the Seppun shugenja, but due to its great usefulness it later spread across the Empire. The Seppun Shugenja School technique may be applied to this spell.", "tags": ["wards"], "livro": "Book of Air (Livro do Ar)", "pagina": "184"}, {"id": "funeral_rites", "nome": "Funeral Rites", "elemento": "air", "mastery": "4", "area": "N/A", "alcance": "N/A", "duracao": "5 minutes", "descricao": "This ritual was originally devised by the Kitsu sodan-senzo, but due to its widespread applicability it quickly spread to other shugenja families and schools. The Kitsu wished all Rokugani to properly venerate the ancestors, and thus had no difficulty sharing their discovery with the Isawa and the other clans as well. For those who do not have Kitsu blood, this spell is one of the very few ways in which shugenja can actually communicate with the ancestors while in Ningen-Do. The spell is actually an hour-long ritual prayer which can only be performed in the company of a recently deceased individual's relative within twenty four hours of the funeral (which both the shugenja and the relative must have participated in properly). Other shugenja may assist in the ritual if they also know the spell; they do not need to make Spellcasting rolls, but are still considered to use up a spell slot. Once the prayer is properly completed (a successful Spellcasting Roll by the lead shugenja), the caster and the relative may both converse for a few minutes with the spirit of the recently departed. (If extra shugenja assist in the ritual, each assisting shugenja adds +1 minutes to the duration of the spell.) Typically, this ritual is only used in situations where the living relatives want to make quite sure they are properly remembering and honoring their newly-departed ancestor. The exact results of communing with the departed relative are at the discretion of the GM, but could include learning important information, receiving advice and guidance, or taking up a task which the dead samurai left incomplete.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "184"}, {"id": "facing_your_devils", "nome": "Facing Your Devils", "elemento": "air", "mastery": "5", "area": "One target person or creature", "alcance": "30'", "duracao": "10 rounds", "descricao": "This is a dangerous and powerful spell which had appeared among ronin shugenja from time to time for almost a thousand years of Rokugani history. The spell is often regarded as wicked by clan shugenja, so those ronin who learn it guard its secrets carefully and only pass it on to their most trusted students. Typically no more than one or two shugenja in a generation will learn it. In the time of the Clan Wars, the spell's most famous user was the ronin Heichi Chokei, who claimed to be a descendent of the long-lost Boar Clan. When he was asked about the purpose of the spell, Chokei replied with a smile: \"It is for whoever is brave enough to use it.\" In later years it also gained fame as a favored spell of Naka Kuro, the so-called Grandmaster of the Elements, and his student and successor Naka Tokei. Facing Your Devils appears to call on the Air kami to test the kharmic and elemental balance of a soul by deliberately misaligning the target's Elements. The spell switches the highest and lowers Traits of the target for the duration. This may result in changes to the target's Ring Ranks, with potentially severe consequences (e.g. a dropping Earth Ring reducing available Wounds, for example). The caster may choose the affected Traits in case of a tie. Those who use Facing Your Devils see it as a means to teach others the importance of balance in all things, but much more nefarious and cruel uses are certainly possible and have been employed more than once, lending the spell to a sinister reputation. The Air spirits seem to find the spell amusing, since they do not always recognize the harm it can cause.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "185"}, {"id": "gathering_swirl", "nome": "Gathering Swirl", "elemento": "air", "mastery": "1", "area": "20' radius from caster", "alcance": "Centered on caster'", "duracao": "1 round", "descricao": "This spell, most often found in the scroll-satchels of magistrates and their assistants, seems to be a simpler version of the same prayer used for Freedom of the Air. It causes the Air kami to blow furiously through the area of effect, and while initially this seems to produce nothing but chaos, within a few moments the winds gather several unattended items and deposit them in a neat stack (though not an organized one) at whatever location within the area the caster might desire, including in someone's hands if that is preferable. The caster must name the items to be collected when the spell is cast, and only those items will be collected - a convenient way to gather scattered papers, find a note buried under a pile, or otherwise retrieve something important with a minimum of effort. It can also be used, more cleverly, to retrieve a concealed or hidden item, a use which magistrates find quite valuable. However, it cannot be used to snatch items from someone else's grasp or person - the Air spirits consider that to spoil the fun.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "185"}, {"id": "garbled_tongue", "nome": "Garbled Tongue", "elemento": "air", "mastery": "3", "area": "Two conversing persons (one may be the caster)", "alcance": "30'", "duracao": "5 minutes", "descricao": "Originally developed by Asahina shugenja, this spell found its way into the hands of the Soshi and a few other orders after several minor incidents in court. It is sometimes considered to be a dishonorable spell, but in fact its uses need not be for subterfuge. Rather, much like the Crane courtiers' technique of Cadence, the spell allows discretion in communication in situations where this would not normally be possible. It relies on the playfulness of the Air kami and the subtleties of language. The spell causes the kami to obscure a conversation between two or more persons. The Air spirits create a second layer of speech, one heard by everyone except those actually participating in the conversation (who may include the caster). Though the speakers are aware of this false layer of speech, they will clearly hear the actual conversation taking place. The illusion cannot normally be penetrated except by reading lips (since they will not match the false conversation), although a shugenja can pierce the deception by winning a Contested School Rank / Air roll against the caster.", "tags": ["illusion"], "livro": "Book of Air (Livro do Ar)", "pagina": "185"}, {"id": "howl_iof_isora", "nome": "Howl of Isora", "elemento": "air", "mastery": "4", "area": "40' diameter", "alcance": "100'", "duracao": "Instantaneous", "descricao": "This spell calls on the power of Isora, the Fortune of the Seashore, to unleash a blast of storm-wracked air and lightning that smites an area within range. The sudden roaring onslaught of wind, rain, and lightning inflicts 3k2 damage on everyone within the area of effect, and they must roll their Earth at TN 30 or be Fatigued by Isora's howl. The spell also damages weak or vulnerable physical objects - paper walls will be blown out, scrolls soaked with water, etc. Those who are fortunate enough to be blessed by the Blood of Osano-Wo are immune to the effects of this spell.", "tags": ["thunder"], "livro": "Book of Air (Livro do Ar)", "pagina": "186"}, {"id": "look_into_the_soul", "nome": "Look into the Soul", "elemento": "air", "mastery": "4", "area": "One target person or creature", "alcance": "50'", "duracao": "1 Round", "descricao": "When a priest invokes this incantation, the Air kami gather together and form a mystical lens through which the shugenja may see the world as the spirits themselves perceive it. The lens lasts only a few moments and the caster can normally only use it to observe one person or creature. That brief moment of observation, however, allows the caster to learn the target's 2 lowest Rings and the values of their constituent Traits, in effect showing part of the person's Elemental composition. Additional Rings may be learned with Raises. (If the character's Rings are all equally balanced, the spell reveals them randomly.) However, the spell cannot and will not reveal the target's Void, for that level of understanding and perception is only possible through mastery of Ishiken-do.", "tags": ["divination"], "livro": "Book of Air (Livro do Ar)", "pagina": "186"}, {"id": "piercing_the_heavens", "nome": "Piercing the Heavens", "elemento": "air", "mastery": "6", "area": "N/A", "alcance": "N/A", "duracao": "5 Rounds", "descricao": "Known only to true masters of magic, this spell is a secret of the Phoenix and has never been intentionally shared with any other shugenja school, not even the Imperial one. It is considered a sacred trust among the most high-ranking of Phoenix priests, and not even all of the Elemental Masters have been considered worthy of its power… for to abuse this prayer is to call down the very wrath of Heaven. This prayer calls for the direct attention of a Fortune named by the shugenja. It may only be performed within a temple or shrine specifically devoted to that Fortune, and may never be cast more than once a month lest it anger the entirety of Tengoku. If the spell is successfully cast, a mote of the Fortune's essence will manifest within the shrine's sacred icon and the shugenja will be permitted to briefly commune with the divine being. The Fortune is neither compelled to answer questions asked nor to fulfill boons requested, and the utmost reverence must be maintained lest its immediate and terrible wrath be unleashed. However, if true reverence is offered and the cause is worthy, the Fortune may offer help available nowhere else.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "187"}, {"id": "quiescence_of_air", "nome": "Quiescence of Air", "elemento": "air", "mastery": "2", "area": "30 foot diameter sphere", "alcance": "Caster", "duracao": "10 Rounds", "descricao": "Security in communication is of paramount importance in many situations, and shugenja often find themselves in situations where a conversation is intended to be completely private, or when they cannot allow themselves to be interrupted by extraneous sounds. By placating the spirits of the Air, a shugenja can convince them to create a barrier against sounds, a bubble of silence through which sound will not pass. The spherical sound-barrier is normally centered around the caster, although with greater effort it can also be centered on a physical object up to fifty feet way. Once this spell is cast, the kami will not allow any sound to enter or leave this bubble, creating absolute privacy for anyone inside of the space. Once created, the bubble of silence will not move, even if the caster for the target object relocates. Characters on one side of a Quiescence of Air spell's barrier gain two Free Raises on Stealth Rolls made against characters on the other side. Ninube shugenja may cast Quiescence of Air as a Nothing Spell.", "tags": ["wards"], "livro": "Book of Air (Livro do Ar)", "pagina": "187"}, {"id": "request_to_hatonokami", "nome": "Request to Hato-no-Kami", "elemento": "air", "mastery": "2", "area": "one bird", "alcance": "150'", "duracao": "1 hour", "descricao": "A specialized variation of Nature's Touch, this spell is a prayer to the Fortunes that is carried by air kami to the ears of a random bird within the spell's range. (If no bird is available, the spell as no effect.) The bird flies down and lands on the caster's hand, and the caster may instruct it to perform a simple task (such as carrying a message or distracting an enemy) for the duration of the spell. With a successful Animal Handling / Awareness roll at TN 20, the caster may persuade the bird to perform a more complex task, such as searching the area for potential enemies and reporting back. This sort of task is subject to the GM's judgement, since if the task is too complex the bird will not be able to comprehend it. In either case, the bird will not take suicidal actions (such as flying into a fire) and will immediately break off and flee if it is injured.", "tags": ["travel"], "livro": "Book of Air (Livro do Ar)", "pagina": "187"}, {"id": "seeking_the_way", "nome": "Seeking the Way", "elemento": "air", "mastery": "4", "area": "Caster's trail for one-half mile", "alcance": "touch", "duracao": "3 hours", "descricao": "This spell is a subtle illusion used to conceal a shugenja's trail from pursuers. The spell convinces mischievous Air kami to hide the tracks of the shugenja (and his mount, if any), along with any other evidence of his passage (such as broken branches). In their place it create a false trail of similar evidence leading in a completely different direction for the same distance. The illusionary trail will follow a reasonable route (e.g. it will not go straight up cliffs or directly into a lake, for example) and will normally be flawless to others' perception; however, someone tracking by scent will be able to sense the original trail, and skilled trackers can potentially see through the illusion by rolling Hunting / Perception against the caster's Spellcraft / Air. Powerful shugenja can persuade the kami to conceal the trails of their companions (and mounts) as well as themselves, as well as lengthening the amount of trail which is concealed and replaced.", "tags": ["illusion"], "livro": "Book of Air (Livro do Ar)", "pagina": "187"}, {"id": "soul_of_kazenokami", "nome": "Soul of Kaze-no-Kami", "elemento": "air", "mastery": "3", "area": "One target person (may be the caster)", "alcance": "20'", "duracao": "10 minutes", "descricao": "This spell calls on the Fortune of Wind to infuse the target's soul with the cooling serenity of an icy northern breeze, rendering him or her resistant to the pressures of emotion and stress. The target seems impervious to any sort of emotional manipulation or psychological pressure; in reality, he does feel normal emotions, but the presence of the Air kami mute their impact, so the target can perceive his own emotions as something distant and abstract. The target of this spell gains a bonus of +2k2 to resist the effects of any Social Skill Roll or Fear effects. However, the same icy serenity which makes him resistant to others' manipulation also makes it difficult for him to perceive the emotions of others; he suffers a -2k0 penalty to any Awareness-based Social rolls.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "188"}, {"id": "tenjins_ear", "nome": "Tenjin's Ear", "elemento": "air", "mastery": "4", "area": "30' radius around caster", "alcance": "caster", "duracao": "5 minutes", "descricao": "Named after the Fortune of Scribes, this powerful invocation was originally created by the Unicorn and derived from their secret Meishodo magic. So far as anyone knows, the spell has never been taught to anyone outside of the Unicorn Clan. The spell persuades the Air kami to carry the true meaning of words to the caster's ear, allowing him to perceive the tongue of foreigners. for the duration of the spell, all audible human speech within the area of effect is made intelligible to the caster, regardless of what language is used. The spell does not grant any enhanced hearing (so whispers still cannot be heard), nor does it bestow any capacity to speak in return.", "tags": ["travel"], "livro": "Book of Air (Livro do Ar)", "pagina": "188"}, {"id": "touch_of_airs_grace", "nome": "Touch of Air's Grace", "elemento": "air", "mastery": "3", "area": "One target person (may be the caster)", "alcance": "touch", "duracao": "1 hour", "descricao": "This illusion was originally devised by the Soshi family, but similar prayers have since been developed among other clans who spend time in the halls and gardens of Rokugan's courtly palaces. The spell entices the Air kami to subtly enhance the target's physical attractiveness, emphasizing his or her fest features and smoothing away any imperfections. The Air kami find this a delightful game and will often be quite creative in the tiny tricks they play to improve the target's appeal. Mechanically, the spell negates the effects of the Disturbing Countenance and Benten's Curse Disadvantages for its duration. If the target does not possess one or both of those Disadvantages, he or she instead gains the benefits of the corresponding Advantages (Dangerous Beauty and Benten's Blessing). If the target already possesses both of those Advantages, the spell does not award any additional benefit (the Air kami find it boring to try to improve someone who is already so attractive).", "tags": ["illusion"], "livro": "Book of Air (Livro do Ar)", "pagina": "188"}, {"id": "voice_of_the_wind", "nome": "Voice of the Wind", "elemento": "air", "mastery": "1", "area": "One target person (may be the caster)", "alcance": "touch", "duracao": "10 minutes", "descricao": "The kami of Air are fond of sounds, which are carried through their Element, and can lend their power to strengthen the beauty, passion, and conviction of the human voice. The recipient of this spell finds his or her voice gains timbre, depth, and resonance, becoming in every way more impressive. For the duration of the spell, the target benefits from the Voice Advantage (if he already has Voice, the benefits stack) and also gains a +1k0 bonus to any Social Skill Rolls that involve speech.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "188"}, {"id": "whispers_of_the_forgotten", "nome": "Whispers of the Forgotten", "elemento": "air", "mastery": "4", "area": "One target person (may be the caster)", "alcance": "50'", "duracao": "5 minutes", "descricao": "Men's memories are shaky, distant things, lodged deep within their minds, and nearly all mortals possess some past sin, some shame they would rather have forgotten. This spell, a favorite of the Scorpion, causes Air kami to evoke the memories and visions of past crimes. The constant painful memories distract and distress the victim of the spell, making it difficult for him to accomplish anything. For the duration of the spell, he must call one Raise for no effect on any Skill rolls or Spellcasting rolls which he makes. if he has 3 or more points in Mental or Social Disadvantages, he must call 2 Raises instead. It may be noted that there are a handful of stalwart souls in Rokugan who truly do not have any sins haunting their past. Such rare persons are immune to the effects of this spell; it is left to the GM's discretion whether a particular target is truly noble enough to shrug off the Whispers of the Forgotten. Some priests of a more ascetic nature have also been known to cast this spell on themselves in order to remind themselves of their past failings and the need for humility in the face of their human frailties.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "188"}, {"id": "wind_of_the_moon", "nome": "Wind of the Moon", "elemento": "air", "mastery": "6", "area": "One target person", "alcance": "50'", "duracao": "1 minute", "descricao": "Air acolytes of some potency realize it is possible to read the minds of others, but a few shugenja have looked at this as only the beginning of what can be done with Air. Through extremely advanced and powerful invocations of the Air kami, it is possible for a shugenja to not only read the surface thoughts of another but to transit his own thoughts into the mind of that person. This is considered a highly questionable act, and the Phoenix Clan considers this spell to border on blasphemy. However, the immense advantages that can be gained from such total manipulation of another means the spell continues to circulate covertly through the Empire. In order for this prayer to succeed, the caster must know the name of the target and must be able to see him or her clearly. Without the visual connection, the thoughts of the target will be too garbled to be decipherable, resulting only in a painful headache to both caster and target. If the name which the caster knows is false (e.g. the target is using an alias) the Spellcasting Roll suffers a +10 TN penalty as the false name confuses the spirits. Furthermore, in order to successfully impose his thoughts on the target's mind, the caster must succeed in an Contested Air Roll against the target; failure means contact is broken and both sides suffer a severe headache as above. However, if the Air roll is successful, the target will be unaware of the mental contact and for the duration of the spell will believe the thoughts springing into his mind are entirely his own. The caster must maintain partial concentration for the duration of the spell - if this is disrupted, the spell ends immediately. A peculiar side effect of this spell is that for an hour after it ends, the caster and target will find it difficult to lie convincingly to each other, inflicting a +10 TN penalty to any Sincerity (Deceit) rolls they make against each other.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "189"}, {"id": "windborn_slumbers", "nome": "Wind-Born Slumbers", "elemento": "air", "mastery": "2", "area": "One target person", "alcance": "50'", "duracao": "5 minutes", "descricao": "This spell causes the Air kami to subtly insinuate themselves into the target's body, urging him toward weariness and sleep. A target who is physically and mentally inactive (such as a guard standing post at night, or a samurai meditating in his dojo) will automatically fall asleep when targeted by this spell. (The target will awaken normally if he is touched or hears a loud noise, but otherwise sleeps until the spell's duration expires.) If the target is physically or mentally active, the spell will not put him to sleep, but he will suffer the effects of being Fatigued for the duration of the spell. (If the target is already Fatigued, his Fatigue penalties increases as though he had gone another day without rest.)", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "190"}, {"id": "wisdom_of_the_kami", "nome": "Wisdom of the Kami", "elemento": "air", "mastery": "4", "area": "Caster", "alcance": "touch", "duracao": "1 minute", "descricao": "This prayer invites the kami of the Air into the mind of the shugenja himself, enhancing the shugenja's mind and thoughts, causing him to be able to make better use of his skills and knowledge. For the duration of the spell, the caster gains 1 Rank in all Skills hie normally possesses, and may benefit from any Mastery Abilities that this would award. This can only grant ranks in Skills the shugenja already possesses - the Air kami cannot evoke knowledge the caster does not possess. When the duration of the spell expires all benefits are lost and any memories of the knowledge or insight which the shugenja gained during the spell's duration are at best fuzzy; no precise or detailed account can ever be given, and severe headaches are known to plague those who try too hard. The benefits for this spell only apply to Skills which the caster actually knows - it cannot increase the Rank of Skills which the caster has temporarily acquired through magic, nor can it combine with Advantages such as Crafty.", "tags": [], "livro": "Book of Air (Livro do Ar)", "pagina": "190"}, {"id": "drawing_on_the_mountain", "nome": "Drawing on the Mountain", "elemento": "earth", "mastery": "5", "area": "One target structure (up to a small castle)", "alcance": "300'", "duracao": "1 day", "descricao": "This spell invokes the strength of Earth to strengthen a physical structure against harm. The wood and stone of the target structure – which may be as large as a castle – are infused with the strength of the mountains themselves, allowing it to withstand floods, earthquakes, and the assaults of siege engines. When using the Siege rules from the L5R 4th edition supplement The Great Clans, for the duration of this spell the Wounds and Reduction of the target structure are doubled. When the spell expires, the extra Wounds are lost – if this reduces the structure to zero Wounds, it immediately collapses into ruin.", "tags": ["battle", "defense"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "earth_dragons_ward", "nome": "Earth Dragon's Ward", "elemento": "earth", "mastery": "4", "area": "20' radius", "alcance": "Touch", "duracao": "10 minutes", "descricao": "This spell calls on the power of the Dragon of Earth to protect an area against dangerous spirits. It was originally pioneered by the Isawa but was soon embraced by other shugenja families, especially the Yogo and the Kuni. The spell requires a warding symbol be inscribed on a solid surface (the ground, a wall, etc) prior to casting; this takes five minutes. Once successfully cast, the spell wards the area against possessing spirits and effects, making it extremely difficult for any individual within the area of effect to be possessed (whether by a ghost, a gaki, an oni, a spell, or in any other manner). Any spirit or being attempting a possession within the area of effect must first succeed in a Contested Willpower roll against the caster. (The caster will be aware that something tried to penetrate the Ward, and will know whether or not it was successful, but will not know the nature or identity of the possessing force.) This spell cannot drive out a spirit which is already possessing someone; it only protects against new possessions.", "tags": ["wards", "jade"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "grounding_energy", "nome": "Grounding Energy", "elemento": "earth", "mastery": "5", "area": "Caster and all alies within 20' radius", "alcance": "Centered on caster", "duracao": "3 Rounds", "descricao": "This spell, originally devised by the Yogo, calls on the spirits of Earth to fortify the caster and his companions, allowing them to resist the power of accursed maho spells. Any maho spell that targets the caster or any of the caster’s allies within the area of effect has its Spell Casting TN increased by an amount equal to 10x the target’s Earth.", "tags": ["wards", "defense"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "groves_of_stone", "nome": "Groves of Stone", "elemento": "earth", "mastery": "3", "area": "circular barrier 15' in radius", "alcance": "centered on caster", "duracao": "10 rounds", "descricao": "This spell is a specialized variation of the more common prayer known as Wall of Earth. It entreats the Earth spirits to draw an array of huge stones up from the ground, erupting in an instant through most intervening physical obstacles (such as the floor of a house) to create a circular barrier around the caster. The stones are too strong to break through with anything short of a siege engine (against a siege engine they are considered to have 500 Wounds and Reduction 15), but can be clambered over with a Complex Action and a roll of Athletics / Strength against the caster’s Earth x5. When the spell expires, the stones crumble away to loose earth and dust.", "tags": ["craft", "defense"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "jurojins_curse", "nome": "Jurojin's Curse", "elemento": "earth", "mastery": "2", "area": "One target creature", "alcance": "30'", "duracao": "1 day", "descricao": "This spell calls on the Earth kami to remove all protection of Jurojin, the Fortune of Health and Longevity, from the target. For the duration of the spell, the target’s Earth is considered to be 3 Ranks lower (to a minimum of 1) for the purpose of healing injuries and resisting disease or poison.", "tags": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "maw_of_the_earth", "nome": "Maw of the Earth", "elemento": "earth", "mastery": "4", "area": "Approximately 10’ in radius", "alcance": "40'", "duracao": "Permanent", "descricao": "This prayer causes the Earth spirits in the ground to wrench open a large pit roughly 20 feet deep, swallowing up anyone in the vicinity. Anyone at or within 10’ of the pit must roll their Reflexes against the caster’s Earth or fall into the pit, suffering 3k2 damage. They are also trapped in the pit until they are rescued or can climb out. (Climbing out of the pit is a Complex Action and requires an Athletics / Strength roll at a TN equal to the pit’s depth in feet.)", "tags": ["battle"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "murmur_of_earth", "nome": "Murmur of Earth", "elemento": "earth", "mastery": "3", "area": "100' radius around caster", "alcance": "Touch", "duracao": "1 round", "descricao": "This spell excites and angers the Earth spirits in the ground around the caster, causing them to briefly shake the ground in the manner of an earthquake; however, the spirits refrain from shaking the ground immediately beneath the caster himself. Although this spell does not produce a true earthquake, the brief tremor can still cause damage and alarm. Any persons within the area of effect must roll Agility at TN 20 or be knocked Prone, suffering 1k1 damage and being Dazed for one Round. Furnishing and other such items will be knocked over by the tremor, which may have a variety of effects as the GM chooses (e.g. a table with a lantern falling over might start a fire). When using the Siege rules from the L5R 4th edition supplement The Great Clans, Murmur of Earth will cause 4k2 damage to all structures within its area of effect, ignoring their Reduction.", "tags": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "rites_of_preservation", "nome": "Rites of Preservation", "elemento": "earth", "mastery": "2", "area": "One human corpse", "alcance": "10'", "duracao": "1 day", "descricao": "This spell is used to preserve the bodies of the dead until they can be properly disposed of (typically by cremation). It was originally developed to allow Imperial and other high-ranking nobles’ bodies to be preserved in dignity until their funerals, since the funeral rites of such major lords are not only lengthy but also tend to draw guests from great distances. The Crab have also found it useful for protecting their dead against the Taint, although the spell is difficult to use on the battlefield. Rites of Preservation is a ritual spell that requires one hour to cast. When a corpse is blessed with this prayer, the Earth kami are entreated to protect the body against putrefaction and other unclean influences, allowing it to remain pristine and untouched until cremation. This blessing is one of the more important religious duties of shugenja, and despite its association with dead flesh is considered an honorable task. A body which is blessed by the Rites of Preservation will not putrefy for the duration of the spell. Moreover, because the blessing repels the attentions of the kansen, the corpse is immune to being animated by maho or the Taint until the spell expires.", "tags": ["Imperial"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "sapphire_strike", "nome": "Sapphire Strike", "elemento": "earth", "mastery": "4", "area": "One target creature", "alcance": "50'", "duracao": "Instantaneous", "descricao": "During the War Against the Darkness, the Kuni family of the Crab came to realize that the forces of the Lying Darkness were uniquely vulnerable to the power of crystal. The Kuni threw themselves into researching the ways of crystal and learning how to call on its power through the medium of the Earth kami. This prayer was the result. A Sapphire Strike appears much like the far more wellknown Jade Strike, but the blast of elemental energy which is unleashed shows a distinctive blue-green tinge, quite different from the bright green color of a Jade Strike, as the Earth kami call on the essence of Lady Sun’s tears. The Sapphire Strike has a DR of 4k4, but only against targets who are specifically vulnerable to Jade or Crystal. It is considered to be both Jade and Crystal for the purpose of game effects such as whether it penetrates Invulnerability or Reduction.", "tags": ["Jade", "Crystal", "Thunder"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "shelter_of_earth", "nome": "Shelter of Earth", "elemento": "earth", "mastery": "3", "area": "One target creature (may be the caster)", "alcance": "Touch", "duracao": "30 minutes", "descricao": "This spell entreats the Earth kami to hide and conceal the targeted creature. Earth flows up to cover the target with a realistic-looking facsimile of some natural object, such as a tree or a boulder; this shell collapses back into loose earth when the spell expires. The target can hear and breathe normally, but has no other interaction with the world outside of the concealing shell of Earth; if he speaks, moves, or is actually hit by an attack, the spell immediately ends and the concealing shell collapses as above. From outside, however, the false object will seem perfectly normal and will resist physical blows with the same strength it would have if it were real. When creating the false shell, the Earth kami will try to choose an object that is appropriate for the area (such as a boulder on a mountainside), but they do lack imagination and in any case cannot create the false form of a manmade object – thus, the utility of this spell within a town or a castle is somewhat limited.", "tags": ["craft", "illusion"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "soldiers_of_clay", "nome": "Soldiers of Clay", "elemento": "earth", "mastery": "6", "area": "N/A", "alcance": "100'", "duracao": "1 hour", "descricao": "Most famously used by Isawa Tadaka and Isawa Sezaru in the early twelfth century, this powerful variation of Rise, Earth is found solely in the Phoenix libraries. Thus far the Phoenix have not shared it with any other clan, although they seriously considered doing so during the Kali-Ma Invasion. Depending on specific campaign settings, the GM could also have this spell introduced to the wider Empire in an earlier era. The spell creates ten human-sized warriors, forming them from earth and stone and animating them with the power of the Earth kami which infuse them. The warriors will move, fight, and otherwise act as the caster commands, obediently and fearlessly. They have Traits and Rings equal to the caster’s Earth, attack (with swords made of stone) as though they have Kenjutsu of 4, and have Reduction equal to twice the caster’s Earth. Their swords are considered to have the Jade property. When destroyed (or when the spell’s duration ends) they collapse into piles of loose earth.", "tags": ["craft", "battle", "jade"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "stones_endurance", "nome": "Stone's Endurance", "elemento": "earth", "mastery": "1", "area": "One target creature (may be the caster)", "alcance": "Self or Touch", "duracao": "6 hours", "descricao": "This spell calls on the strength of stone to enhance the target creature’s physical endurance and toughness. This spell was originally devised by the Unicorn to allow their horses to ride for long periods of time without tiring, but after the Unicorn returned to the Empire other clans also saw value in the spell – particularly the Crab, who found it quite useful for situations where their soldiers had to remain on duty for long periods of time. For the duration of the spell, the target is immune to being Fatigued due to a lack of rest, and is considered to have a Stamina that is one Rank higher for the purpose of any rolls or effects which specifically key on Stamina (such as resisting poisons, determining how long one can avoid drowning, etc). The spell may be cast multiple times on the same target, but the Earth spirits cannot sustain the effort beyond a total of 24 consecutive hours. Once the spell expires, the target is automatically considered Fatigued until he rests for at least half as long as he was under the spell’s effects.", "tags": ["travel"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "strike_as_stone", "nome": "Strike as Stone", "elemento": "earth", "mastery": "3", "area": "One target person (may be the caster)", "alcance": "Self or Touch", "duracao": "5 minutes", "descricao": "This spell calls on the spirits of Earth to strengthen the target’s hands and forearms, making them as hard as stone. The target’s hands cannot be physically harmed for the duration of the spell (allowing him to perform a variety of feats, such as prying open a lock with his fingers), and his unarmed Damage Rating is increased by +2k0.", "tags": ["battle"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "taming_the_beast", "nome": "Taming the Beast", "elemento": "earth", "mastery": "2", "area": "One target natural creature", "alcance": "50'", "duracao": "1 hour", "descricao": "This spell is a secret of the Kitsune family and thus far has never been taught outside of their ranks. It calls on the power of Earth to soothe a wild animal’s temperamental spirit, causing it to become temporarily tame. After completing the prayer, the shugenja makes a Contested Earth roll against the target creature (as a Free Action); with a success, the creature ceases all hostile activity for the duration of the spell, and the caster may persuade the creature to obey simple commands by means of the Animal Handling skill (TNs determined by the GM based on the complexity of the command). When the spell’s duration expires, the animal returns to its normal behavior – however, in some cases, repeated castings of this spell on the same animal have resulted in its being effectively permanently tamed (GM’s discretion). This spell only works on natural creatures (such as snakes or bears) – it has no effect on spirits, supernatural creatures, or Tainted creatures.", "tags": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "the_earth_flows", "nome": "The Earth Flows", "elemento": "earth", "mastery": "4", "area": "1 square mile", "alcance": "Centered on Caster", "duracao": "1 hour (or two Mass Battle Rounds)", "descricao": "This spell was originally developed by the Kitsu family of the Lion, but quickly spread to other families due to its value to any army on the field of battle. It calls on the Earth kami to re-arrange the landscape of a battlefield in a manner favorable to his side of the battle. For example, a hillside might shift to allow the caster’s side to charge downhill, or a cliff that shields the enemy flank might change into a gentle slope. The spell awards a +3k2 bonus to any roll made by the commander of the caster’s side to determine who is winning a Mass Battle, and a +1k1 bonus to any Mass Battle Table rolls made by individual samurai on the caster’s side. Because this spell invokes the Earth kami on such a large scale, casting it on both sides of the same battle can lead to a violent spiritual backlash – typically triggering a massive earthquake (equivalent to the Rank 5 spell Earthquake).", "tags": ["battle"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "times_deadly_hand", "nome": "Time's Deadly Hand", "elemento": "earth", "mastery": "3", "area": "One physical object", "alcance": "Touch", "duracao": "Permanent", "descricao": "This spell causes the Earth kami within a physical object to abandon that object, weakening its physical strength. Wood warps and flakes, stone and metal turn weak and brittle, cloth becomes thin and fragile, and so forth. The spell’s effects are permanent. Mechanically, any weapon which is affected by this spell will lose 2k1 from its DR, and any armor will lose 5 from its Armor TN bonus and 3 from its Reduction. A variety of other non-mechanical effects can also take place, subject to the GM’s adjudication – for example, a kimono affected by this spell will rip if it is subject to the slightest tension or stress, and a scroll will tear and crumble the moment it is unrolled. Weakened stones or beams could be used to sabotage a bridge, to facilitate breaking into a besieged castle, and so forth. In general, this spell will not affect awakened items (e.g. nemuranai), since their empowered spirits resist the shugenja’s entreaty.", "tags": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "whispers_of_the_land", "nome": "Whispers of the Land", "elemento": "earth", "mastery": "2", "area": "50' radius", "alcance": "Centered on Caster", "duracao": "10 minutes", "descricao": "This spell was originally developed by the Kitsune family of the Fox Clan, who used it to help track intruders in the lands of their modest clan. It has since spread to other families who find its properties useful, such as the Yogo and the Kuni. The spell causes the Earth spirits to reveal the tracks of any person who has walked upon them within the last three days. The surface – whether it be stone, earth, or wood – literally pushes up in the shape of the tracks, creating a clear and easily-followed path. (Note that, unlike revelatory Air spells such as By the Light of the Moon, this spell does not merely reveal actively concealed tracks but also normal unconcealed tracks that are too faint or old to normally be seen. For example, By the Light of the Moon would not reveal the barefoot tracks of a servant who walked across the floor of a dojo, but Whispers of the Land will do so.)", "tags": [], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "wooden_prison", "nome": "Wooden Prison", "elemento": "earth", "mastery": "3", "area": "One target creature", "alcance": "50'", "duracao": "5 rounds", "descricao": "This spell entreats the Earth kami inhabiting living plants and trees, causing them to make the plants rapidly grow and twine themselves around a designated target. Within seconds the target finds himself ensnared in a dense tangle of vines, creepers, and branches. The target is automatically Entangled at the moment the spell is cast; on his subsequent Turns, the target may attempt to escape as a Simple Action by making a Contested Strength roll against the plants’ Strength of 4. (Alternatively, the target can be cut free by allies – it takes two Turns’ worth of effort to slash away enough of the plants to free the target.) If the target escapes, or the spell expires, the plants drop away and shrivel up as the Earth kami cease to stimulate them. This spell can only function in an area where living plants are present, e.g. it will not function inside a building, in a desert, on a barren mountainside, or other such environments. It cannot target a flying creature.", "tags": ["Defense"], "livro": "Book of Earth (Livro da Terra)", "pagina": ""}, {"id": "fire_kamis_blessing", "nome": "Fire Kami's Blessing", "elemento": "fire", "mastery": "1", "area": "One target creature (may be caster)", "alcance": "Touch", "duracao": "1 hour", "descricao": "This prayer calls on the Fire kami to stimulate the mind and memory, allowing the recipient to recall the most obscure information, details he may have encountered only once or briefly. For the duration of this spell, the target gains a +Xk0 bonus (where X is the caster’s Fire Ring) to any High or Merchant Skill rolls using the Intelligence Trait.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "185"}, {"id": "gift_of_amaterasu", "nome": "Gift of Amaterasu", "elemento": "fire", "mastery": "1", "area": "50' radius sphere", "alcance": "50'", "duracao": "10 minutes", "descricao": "This spell is a prayer to Amaterasu, the Sun Goddess, asking her to bestow her favor on the caster in the form of radiant Fire kami. (In the twelfth century, when Amaterasu is superceded first by Yakamo and then by the Jade Sun, the name and forms of this spell changes, but the effects remain the same.) Once the prayer is completed, warm sunlight blazes down on the chosen area, bathing it in full daylight even if it is at night, indoors, or underground. This spell is particularly popular among shugenja who are assigned to assist in the protection of castles and other vital locations, since a sudden blaze of daylight can bea very effective deterrent to thieves, assassins, and spies.", "tags": ["defense"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "185"}, {"id": "osanowos_blessing", "nome": "Osano-Wo's Blessing", "elemento": "fire", "mastery": "1", "area": "40' radius", "alcance": "100'", "duracao": "30 minutes", "descricao": "This prayer acts in the exact opposite way of the commonly-used spell Extinguish; instead of urging the Fire kami to depart and thus put out flames, it urges them to greater energy and vigor, making flames harder to extinguish. For the duration of this spell, all fires within the area of effect become impossible to extinguish by normal means, and any magical effort to put them out (such as the aforementioned Extinguish spell) must succeed in a Contested Fire roll with the caster of Osano Wo’s Blessing. This spell is controversial, since it can result in otherwise controllable fires in cities and villages raging out of control. Pacifistic shugenja such as the Asahina and Isawa generally eschew its usage.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "185"}, {"id": "warning_flame", "nome": "Warning Flame", "elemento": "fire", "mastery": "1", "area": "One target person (may be caster)", "alcance": "Touch", "duracao": "10 Rounds", "descricao": "Fire is the Element of wit and intellect as well as the Element of destruction. This spell excites the Fire kami within the mind, allowing the target to notice threats and react to them far more quickly than normally. For the duration of the spell, the target is immune to being surprised, adds +1k0 to any Initiative rolls he makes, and may add +3 to his Initiative total during the Reactions stage of each Round.", "tags": ["battle"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "186"}, {"id": "purity_of_shinsei", "nome": "Purity of Shinsei ", "elemento": "fire", "mastery": "2", "area": "One target person/effect", "alcance": "50'", "duracao": "Instantaneous", "descricao": "This spell was originally devised by the Isawa to deal with the threat of Yobanjin magic, and later spread to the rest of the Empire when other gaijin threats became more frequent. The spell calls on Shinsei’s principles of Elemental unity and harmony to oppose unnatural foreign magic, using the energy of Fire as a focus. Purity of Shinsei ends the effects of a gaijin spell or spell-like effect. Typically this means targeting an individual who is being afflicted by an ongoing gaijin spell effect (such as a samurai laboring under a foreign curse), though it can also target an effect which is not afflicting a specific individual (such as a foreign curse on a castle, a village, or a physical item). The GM has final discretion on whether a particular gaijin magic effect can be countered with Purity of Shinsei. If the optional Counterspelling rules as in use, the GM may opt to let a shugenja who knows this spell attempt to Counterspell meishodo spells and gaijin magic.", "tags": ["defense"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "186"}, {"id": "wings_of_fire", "nome": "Wings of Fire", "elemento": "fire", "mastery": "2", "area": "Self", "alcance": "Touch", "duracao": "10 minutes", "descricao": "This prayer is a simpler and less potent form of the spell Wings of the Phoenix, although it is also slightly more flexible in that it does not require a suit of armor to act as an \"anchor\" for the Fire kami. When this spell is cast, a cloud of Fire kami gather and take the form of large feathery wings sprouting from the caster’s arms and back. The caster may use these wings to fly slowly (normally moving at a speed equal to Water 1, regardless of his actual Water Ring). If the caster is able to glide (e.g. he is already at a significant height above the ground), he can move more quickly, as though he is Water 4. While the spell is in effect, the caster cannot use his arms for anything but flapping and moving his fiery wings, severely limiting his potential actions; also, he will set fire to any easily flammable objects (such as paper or spell scrolls) he touches, although the Fire kami will avoid harming his clothes. When the spell ends, the Fire kami immediately disperse, regardless of whether the caster is on the ground or in the air - unlike the friendly Air kami, the mercurial and aggressive Fire kami do not particularly care about the caster’s fate once they depart.", "tags": ["travel"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "186"}, {"id": "agashas_shield", "nome": "Agasha's Shield (Tamori's Curse)", "elemento": "fire", "mastery": "3", "area": "30' radius around the caster", "alcance": "Touch/Self", "duracao": "6 rounds", "descricao": "Originally devised by Agasha shugenja who were working with hanabi (fireworks), in modern times this spell has been renamed Tamori’s Curse by the Tamori family. The spell creates a zone of protection in which Fire kami friendly to the caster reject any intrusion by other Fire kami. Any hostile Fire spell cast within the Area of Effect suffers a -4k0 penalty to the Spell Casting Roll. Any hostile Fire spell cast from an outside location that attempts to project Fire effects into the Area of Effect (such as spells like Fires From Within) will suffer a -3k0 penalty to its DR as Agasha’s Shield disperses and weakens the kami.", "tags": ["defense", "wards"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "186"}, {"id": "oath_of_the_heavens", "nome": "Oath of the Heavens", "elemento": "fire", "mastery": "3", "area": "Two target persons (see description)", "alcance": "Touch", "duracao": "5 rounds", "descricao": "This spell was originally a secret spell of the Agasha family, and has sometimes been credited as being invented by Agasha herself during her rescue from goblins by Mirumoto Hojatsu. In modern times, both the Phoenix Clan Agasha and the Dragon Clan Tamori know the spell, although the Tamori use it far more often. The spell calls on the Fire kami to form a link between the ferocity of a bushi and the intellect of a shugenja, allowing both to work in concert to greater effect. The caster traditionally targets himself and one friendly bushi (usually, though not always, a yojimbo), although it is also possible for the caster to bestow the spell’s benefits on a different shugenja rather than himself. For the duration of the spell, both recipients receive a +2k0 bonus to all rolls involving the Fire Ring and Fire Traits (e.g. all rolls involving Agility and Intelligence). However, the links also makes each recipient vulnerable to effects on the other - if either recipient becomes Fatigued, Dazed, or Stunned, the other immediately shares the same Condition. Moreover, if either recipient is reduced to Down, Out, or Dead, the spell’s effects immediately end.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "187"}, {"id": "the_breath_of_battle", "nome": "The Breath of Battle", "elemento": "fire", "mastery": "3", "area": "One target person", "alcance": "30'", "duracao": "5 rounds", "descricao": "This prayer, variously credited to the Isawa, the Kitsu, or the Seppun, is the positive counterpoint to the notorious Haze of Battle prayer. Where Haze of Battle drives its target into a maddened frenzy of combat by exciting the Fire kami within him, The Breath of Battle invokes a positive and honorable ferocity by using Fire to call on the divine favor of the Sun. The target of this spell gains a +1k1 bonus to all Agility-based Skill Rolls and a +1k0 bonus to all Damage rolls so long as he remains under the direct light of the Sun. The spell cannot function underground, at night, or when the Sun is obscured by clouds (although the spell Gift of Amaterasu can circumvent this restraint), but it ignores minor obstructions to sunlight such as foliage or shoji screens.", "tags": ["battle", "imperial"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "187"}, {"id": "whispering_flames", "nome": "Whispering Flames", "elemento": "fire", "mastery": "3", "area": "All persons within 10' radius", "alcance": "50'", "duracao": "3 rounds", "descricao": "The creation of this spell is credited to Asahina himself, who sought ways to use Fire magic peacefully after he joined the Crane Clan, but in modern times it is found in the ranks of many different families. The spell causes the Fire kami to gather and dance in a pleasing visual shape and with a soothing rhythmic light. Those who gaze upon the Fire kami see an entrancing and appealing vision that distracts them from taking violent actions. All persons within the Area of Effect find themselves entranced and are considered Dazed for the duration of the spell. However, the targets may attempt to shake off the spell’s effects during the Reactions Stage of each Round with a Willpower roll against a TN of the caster’s Fire x10. This spell’s effects are most potent against Rokugani, since the Fire kami find it more difficult to create entrancing images for those they do not understand. The GM may award gaijin and nonhuman targets a bonus to their Willpower roll to resist the spell’s effects. Animals, bestial creatures, and mindless creatures such as undead are completely immune to the spell.", "tags": ["illusion"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "187"}, {"id": "blessing_of_the_sun", "nome": "Blessing of the Sun", "elemento": "fire", "mastery": "4", "area": "One willing target person (may be the caster)", "alcance": "Touch", "duracao": "3 Rounds", "descricao": "This spell infuses the target’s limbs with a rush of aggressive Fire kami, allowing him to move and think more quickly and to ignore pain and weariness. However, there is a price to be paid for such Elemental vigor, since once the kami depart the body becomes even more weary than before. The recipient of this blessing feels a rush of burning energy and a quickening of thought. He instantly recovers from the Dazed Condition if it is in effect. Moreover, for the duration of the spell, the target’s Fire-related rolls (e.g. any roll using Agility or Intelligence and any Spell Casting Roll using the Fire Ring) may ignore both the effects of being Fatigued and the TN effects of Wound Penalties. However, once the spell expires, the target becomes Fatigued (this stacks with any pre-existing Fatigue effects) and cannot recover from this Fatigue in any way (rest, magic, or Techniques) for 24 hours.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "187"}, {"id": "essence_of_fire", "nome": "Essence of Fire", "elemento": "fire", "mastery": "4", "area": "Two target duelists", "alcance": "10'", "duracao": "One iaijutsu duel", "descricao": "This spell was originally developed by the Asahina to prevent magical tampering with iaijutsu duels. In the Crane view, iaijutsu is a test of the duelist’s own inherent skills and talents, and using the kami to aid in a duel violates its proper nature as the sacred judge of right and wrong. (The Crane also suspected certain other clans, such as the Scorpion and Dragon, of \"cheating\" with magic during duels.) This spell ensures that no magical effects will dilute the duel’s test of skill. In Crane lands it is traditional for shugenja to invoke this spell as a blessing on an iaijutsu duel, and the custom sometimes appears in other clans and families as well - particularly the Seppun. When this spell is cast, a flow of Fire kami race through the chosen targets and drive out any other active kami on them, immediately ending any ongoing spell effects they may have on their persons. The Fire kami remain until the end of the duel, protecting against further interference - any spell which targets either duelist before the duel concludes will suffer a -3k0 penalty to its Spell Casting Roll In modern times, a few shugenja have developed a more controversial variant of this spell which also uses the Fire kami to interfere with the targets’ memories and suppress their knowledge of bushi Techniques. This tactic is especially popular with shugenja from clans which do not focus on dueling, since it makes a duel purely a test of raw skill with no advantage to those descended from Kakita or Mirumoto. Casting the spell with this additional effect requires 4 Raises.", "tags": ["wards", "imperial"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "188"}, {"id": "eyes_of_the_phoenix", "nome": "Eyes of the Phoenix", "elemento": "fire", "mastery": "4", "area": "One target creature", "alcance": "25'", "duracao": "1 hour", "descricao": "This spell’s name is somewhat ironic, and has sometimes been credited to a Scorpion shugenja with a low opinion of the Isawa. Regardless of its origin, the spell’s effect is to persuade a small cloud of strong Fire kami to float directly in front of the target’s eyes. This makes it appear to others as though the target’s eyes have caught on fire, an unsettling effect to say the least. When the spell is cast, any allies of the target suffer a Fear 3 effect (if they are vulnerable to Fear - undead are immune, and the GM may rule that other creatures are resistant or immune if it seems appropriate). More importantly, for the duration of the spell, the target is considered to be Blinded.", "tags": ["illusion"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "188"}, {"id": "castle_of_fire", "nome": "Castle of Fire", "elemento": "fire", "mastery": "5", "area": "Circle with a radius of 30' from caster", "alcance": "Centered on caster", "duracao": "10 Rounds", "descricao": "Like the other Castle spells, Castle of Fire is a defensive prayer, in this case a more sophisticated version of Wall of Fire. It calls on the kami of Fire to erect a barrier surrounding the caster. The fiery barrier is 1’ thick and 10’ high; anyone who is standing on its location when it appears must roll Reflexes at TN 20 to leap away (either inside or outside the Castle) and avoid being burned. The Castle’s barrier instantly incinerates any arrows or other missiles which try to pass through it. Creatures which pass through the Castle’s barrier (or are caught by it when it appears) suffer 6k6 damage and are set afire.", "tags": ["battle", "defense"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "188"}, {"id": "consumed_by_five_fires", "nome": "Consumed by Five Fires", "elemento": "fire", "mastery": "5", "area": "One target creature (and caster)", "alcance": "100'", "duracao": "Instantaneous", "descricao": "One of the most potent and deadly of Fire spells, but also one used only by those facing the most desperate need. The spell invokes an array of powerful Fire kami to strike down the target with incredibly powerful heat and flame - but in order to persuade so many kami to strike with such immense power, the shugenja must bestow them with a gift of his own life-force. The target of this spell is instantly killed, reduced to Dead and then burned down to ashes in a matter of seconds. However, the caster immediately suffers the same number of Wounds as were inflicted on the target - an effect which is often, though not always, lethal. This damage cannot be reduced or mitigated in any way, and if it is lethal the caster cannot avert death. This spell will automatically fail if it targets a creature which is resistant to Fire, and it cannot kill divine entities such as Fortunes.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "188"}, {"id": "the_dragons_talon", "nome": "The Dragon's Talon (Kuro's Fire)", "elemento": "fire", "mastery": "5", "area": "Up to 10 target creatures within range", "alcance": "100'", "duracao": "Instantaneous", "descricao": "A potent battle spell favored by the Elemental Master of Fire and also used by high-ranking battle shugenja from several clans; in the twelfth century Naka Kuro, the Grand Master of the Elements, also used this spell and it came to be called Kuro’s Fire in his honor. Regardless of its name, this spell calls on the unmatched power of the Dragon of Fire to strike down large numbers of lesser foes. When the prayer is completed, bolts of fire resembling the snarling heads of dragons streak out from the shugenja’s hands, striking down the chosen targets. Each target suffers 8k6 damage. However, the nature of this spell is such that the Fire kami will only attack targets who they consider weak and unworthy; in game terms, the spell can only target foes of Insight Rank 1 or 2, or nonhumans of comparable power (GM’s judgment).", "tags": ["battle"], "livro": "Book of Fire (Livro do Fogo)", "pagina": "189"}, {"id": "curse_of_the_burning_hand", "nome": "Curse of the Burning Hand", "elemento": "fire", "mastery": "6", "area": "One target creature", "alcance": "10'", "duracao": "Infinite", "descricao": "A truly powerful curse which has only been employed a few times in the Empire’s history, the Curse of the Burning Hand binds a hostile Fire kami to the soul of the target, making it all but impossible to remove. The spell is difficult and requires a full minute to cast; also, the caster must succeed in a Contested Fire Roll against the target in order to inflict the Curse. Once it is in place, the target finds himself constantly wreathed in flames; these fires do not harm him, but harm any friends, allies, or innocents who touch him. The fire inflicts 3k3 damage on anyone who touches the cursed individual, and set alight any physical objects he touches which are flammable (e.g. wood, paper, clothing, etc). However, because the Fire kami is hostile, it will not help its victim against his enemies - the flame will suddenly recede any time he tries to use it as a weapon. Barring any outside interference, the spell’s effects will last indefinitely. However, other spells which remove magical effects can potentially end the Curse of the Burning Hand if the GM judges them to be appropriate; likewise, other effects which drive out kami (such as Banishment) can remove the Curse.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "189"}, {"id": "rise_fire", "nome": "Rise, Fire", "elemento": "fire", "mastery": "6", "area": "One summoned spirit", "alcance": "30'", "duracao": "Concentration", "descricao": "Fire itself arises and takes physical form to defend you. The ultimate realization of the Summon spell, this prayer summons a massive kami of pure Fire to serve you. It takes the form of a fiery humanoid shape, roughly ten feet in height, its outlines constantly shifting and changing in a perpetual dance of fiery energy. The huge Fire spirit can move up to 10 x your Fire per Round, and it ignites all easily flammable objects within ten feet of itself - paper, leaves, grass, silk, and so forth. The manifest kami is treated as if it has all physical Traits equal to your Fire Ring, and attacks with a Jiujutsu Skill equal to half your Fire Rank; the DR from these attacks is equal to your Fire Rank. Anyone struck by the Fire kami will catch on fire, suffering an additional 1k1 damage per Round until the flames are extinguished. (This effect does not stack.) For purposes of taking damage, the kami is considered to have Wounds as though its Earth is equal to your Fire Ring, but suffers no Wound penalties; it is Invulnerable. If it is successfully reduced to zero Wounds, it is dispelled.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "189"}, {"id": "the_elements_fury", "nome": "The Elements' Fury", "elemento": "fire", "mastery": "6", "area": "Caster", "alcance": "Self", "duracao": "Instantaneous", "descricao": "A supremely advanced form of the lesser spell known as Hurried Steps, this spell has been used by only a few highly advanced masters of magic; its creation is credited to Naka Kaeteru, the first Grand Master of the Elements. When this prayer is completed, the caster’s mind and body are infused with energetic Fire kami to such an extent that his thoughts, movements, and speech become all but superhuman. He may immediately cast a number of spells of Mastery Level 4 or less equal to his Fire Ring, casting each spell as a Free Action regardless of its normal casting time. Spell Casting Rolls must be made and spell slots are used as normal, but there is no need to Raise for a shorter casting time.", "tags": [], "livro": "Book of Fire (Livro do Fogo)", "pagina": "189"}, {"id": "commune_with_the_void", "nome": "Commune with the Void", "elemento": "void", "mastery": "2", "area": "self", "alcance": "n/a", "duracao": "1 round per question (must maintain concentration)", "descricao": "Commune with the Void allows the caster to enter into a direct communion with the ineffable Void and thereby gain information in a manner which is superficially similar to the basic Commune spell in the other four Elements. Much like the other Commune spells, this spell allows the caster to seek information. However, the answers tend to be far more enigmatic and unpredictable than those offered by the Elemental kami. The Void, after all, is not an array of individual spirits but a single all-encompassing whole. Thus, while in game terms the caster is still allowed to ask two questions (and can Raise to gain the ability to ask more), in practice the shugenja is not actually “asking” anything, but is using the Void to follow the connections between things and seek insight into their nature and history. In essence, the GM may answer these questions as completely or as confusingly as he might wish, and can provide information not only from the past but also from the future. (Of course, a wise GM should be wary about being too specific about things that have not happened yet.) The GM can even go beyond the specific question if he wishes, giving the player information not actually sought. On the other hand, the Void is difficult to comprehend - the GM should also feel free to deliver confusing or misleading information, but nothing outright false.", "tags": [], "livro": "Book of Void (Livro do Vazio)", "pagina": "189"}, {"id": "strengthen_the_void", "nome": "Strengthen the Void", "elemento": "void", "mastery": "2", "area": "20' radius from caster", "alcance": "n/a", "duracao": "5 Rounds", "descricao": "This spell allows the caster to thin the veil separating the Void from reality, enhancing the power of the Void within the local area. This is often used when training young ishi, allowing them to touch the Void more readily, but it has a practical value in that anyone within its effect can better harmonize with the Void and thus better reach their own physical and spiritual potential. While this spell is in effect, anyone within the Area of Effect gains a Free Raise to casting Void spells; however, the intensity of the Void in the area makes it harder to focus enough on individual Elements cast other spells, inflicting a +5 TN penalty on all non-Void spells. Also, anyone who spends a Void Point within the area of effect gains a +2k1 bonus instead of the normal +1k1. Any creature of the Lying Darkness (and any mortal with at least 1 Shadow Rank) who enters the area of effect will feel a deep sense of discomfort. Such creatures and individuals must roll Willpower at TN 20 or suffer a +10 TN penalty to all their Skill rolls and attack rolls made while they are within the area of effect. If they fail the Willpower roll by more than 10, they must try to leave the area of effect and cannot voluntarily re-enter it.", "tags": [], "livro": "Book of Void (Livro do Vazio)", "pagina": "190"}, {"id": "banish_the_Void", "nome": "Banish the Void", "elemento": "void", "mastery": "3", "area": "20' radius from caster", "alcance": "n/a", "duracao": "5 Rounds", "descricao": "This spell is the exact counterpoint to Strengthen the Void; it thickens the veil between the Void and reality, making it more difficult to perceive the Void or to call on the inner harmony which the Void represents. This spell is normally used by ishiken to control the activities of their more powerful and dangerous apprentices, but is sometimes employed in more practical venues as well. Within this spell’s area of effect, casting other Void spells suffers a +10 TN penalty. Also, anyone wishing to spend Void Points within this area must spend two Void Points to gain the effects of one. If the character only has one Void Point, he cannot spend it within the area of effect. GM’s Note: It is left to the GM’s decision whether the effects of Strengthen the Void and Banish the Void also apply to “Void-like” effects such as Naga Akasha or the ratling Name.", "tags": [], "livro": "Book of Void (Livro do Vazio)", "pagina": "190"}, {"id": "essence_of_void", "nome": "Essence of Void", "elemento": "void", "mastery": "4", "area": "one target creature", "alcance": "50’", "duracao": "concentration", "descricao": "This spell allows the ishiken to suffuse another living creature with the pure essence of the Void, overwhelming the creature’s bodily functions and rendering that creature inert and unmoving so long as the spell remains in effect. The caster must be able to see the target, and the spell requires a successful Contested Void Roll (creatures without a Void Ring may resist with Name, Akasha, or Willpower at the GM’s discretion). If the target fails the Contested Roll, it is held immobile, unable to move, speak, or otherwise act of its own volition so long as the caster maintains concentration. On the second and subsequent Rounds of the spell, the target may make another Contested Roll during the Reactions Stage to throw off the spell’s effects.", "tags": [], "livro": "Book of Void (Livro do Vazio)", "pagina": "191"}, {"id": "air_and_earth", "nome": "Air and Earth", "elemento": "multi", "mastery": "3", "area": "cone 50' long and 30' wide at base", "alcance": "self", "duracao": "Instantaneous", "descricao": "This spell causes a ferocious horizontal cyclone to blast outward from the caster, ripping up pieces of earth into a barrage of wind and stone. The caster must be standing on a natural earth surface (e.g. not in a building or on a ship) in order to cast this spell. Anyone other than the caster within the area of effect takes 4k2 Wounds (this damage is considered Jade for the purpose of harming supernatural creatures) and is Dazed; they must also make a Contested Earth roll against the caster or be knocked Prone.", "tags": ["jade"], "livro": "Book of Void (Livro do Vazio)", "pagina": "186"}, {"id": "fire_and_air", "nome": "Fire and Air", "elemento": "multi", "mastery": "3", "area": "10' radius", "alcance": "self", "duracao": "Instantaneous", "descricao": "This spell capitalizes on the explosive relationship between Fire and Air to combine offensive and defensive effects. The Fire spirits unleash a blast of flame to scorch the caster’s enemies, while the Air spirits call on the invigorating power of this flame to lift the caster through the air to a safer location nearby. Everyone other than the caster within the spell’s area of effect takes XkX in fire damage (where X is the caster’s Fire), while the caster flies up through the air and lands up to his Air x20’ away, the Air spirits cushioning his descent so he is unharmed. Both effects take place in the same Round.", "tags": ["travel"], "livro": "Book of Void (Livro do Vazio)", "pagina": "187"}, {"id": "fire_and_water", "nome": "Fire and Water", "elemento": "multi", "mastery": "2", "area": "10' radius", "alcance": "50'", "duracao": "2 Rounds", "descricao": "This spell invokes fire and water spirits at the same time and persuades them to mingle, unleashing a cloud of scalding steam. The area of effect is suddenly filled with super-hot steam which lasts until the spell ends, at which point it disperses. Those caught within the steam suffer 2k2 Wounds each Round they are there (unless they are resistant to heat) and their vision is impaired in the same manner as the Missing Eye Disadvantage until they leave the steam cloud.", "tags": ["battle"], "livro": "Book of Void (Livro do Vazio)", "pagina": "187"}, {"id": "earth_and_fire", "nome": "Earth and Fire", "elemento": "multi", "mastery": "4", "area": "5' radius", "alcance": "100'", "duracao": "Instantaneous", "descricao": "This spell invokes the combined wrath of the Earth and Fire kami, bringing them forth from the ground as a blast of searing magma. Anyone caught in the brief but ferocious blast suffers 5k4 Wounds and is knocked Prone. The damage from this spell bypasses the first 5 points of Reduction on the target, and is considered to be Jade for the purpose of harming supernatural creatures.", "tags": ["jade"], "livro": "Book of Void (Livro do Vazio)", "pagina": "187"}, {"id": "water_and_air", "nome": "Water and Air", "elemento": "multi", "mastery": "2", "area": "self", "alcance": "1 mile", "duracao": "Concentration", "descricao": "This spell combines the communicative powers of the Air kami with the clarity and divination abilities of the Water kami to grant a potent form of long-distance divination. The caster must have access to a body of still water (a large basin or tub, a koi pond, a moat, etc) in order to cast this spell. By gazing into the water, the caster gains access to the vantage of Air spirits within the spell’s range, allowing him to look down on any location within that range as though gazing down from the sky, and to hear anything happening in that location. The perspective may be anywhere from a tree-top’s height all the way up to the height of the clouds. This spell has obvious military applications, and is known to be used by the Iuchi for such purposes.", "tags": ["divination"], "livro": "Book of Void (Livro do Vazio)", "pagina": "187"}, {"id": "water_and_earth", "nome": "Water and Earth", "elemento": "multi", "mastery": "2", "area": "20' radius", "alcance": "100'", "duracao": "5 Rounds", "descricao": "This spell persuades the Water kami and Earth kami in the area of effect to mingle, instantly reducing the ground to sticky, nigh-impassable mud. The spell can be cast anywhere where the ground is normal earth or even stone, but cannot be cast on a finished surface such as a tiled or wooden floor. For the duration of the spell, anyone attempting to physically move through the area of effect can only move a number of feet equal to their Water Ring with a Simple Action, and cannot move at all with a Free Action. Moreover, all such persons suffer a -1k1 penalty to any Agility-based rolls due to the mud impeding their physical motions.", "tags": ["battle"], "livro": "Book of Void (Livro do Vazio)", "pagina": "187"}, {"id": "cleansing_the_body", "nome": "Cleansing the Body", "elemento": "multi", "mastery": "2", "area": "1 target person (can be the caster)", "alcance": "touch", "duracao": "Instantaneous/24 hours (see description)", "descricao": "The only known Multi-Element spell created by the Kuni family, this spell calls on both the simple cleansing of Water and the spiritual purity of Earth to help protect against both physical and spiritual pollution. A person targeted with this spell is instantly cleansed of all dirt and filth, and gains a +2k1 bonus to any roll made within the next 24 hours to resist or recover from disease, poison, or infection. Moreover, if the target does not have the Shadowlands Taint, the spell also grants a +2k1 bonus to any rolls made to resist getting the Taint within that same 24 hour period. (This benefit does not work on a target who already has at least one Rank of Taint.) This spell cannot be \"stacked\" that is, a single person can only benefit from one casting of the spell within a 24-hour period.", "tags": ["jade", "Crab"], "livro": "Book of Void (Livro do Vazio)", "pagina": "188"}, {"id": "the_mountains_wrath", "nome": "The Mountain's Wrath", "elemento": "multi", "mastery": "4", "area": "self", "alcance": "N/A", "duracao": "4 Rounds", "descricao": "Created by the Tamori family, this spell invokes both the defensive resilience of Earth and the aggressive ferocity of Fire to protect the caster in combat - a common place for the martial Tamori to find themselves. The caster’s skin is covered by a sheath of stone wreathed in an outward layer of flickering red flames. The caster gains Reduction equal to his Earth x3, and any wooden weapon which strikes the caster is set afire. Anyone who touches the caster (or strikes him with unarmed attacks) suffers Xk1 Wounds (where X is the caster’s Fire Rank), and the caster’s own unarmed strikes have their DR increased by the same amount.", "tags": ["defense", "Dragon"], "livro": "Book of Void (Livro do Vazio)", "pagina": "188"}, {"id": "wrath_of_the_sun", "nome": "Wrath of the Sun", "elemento": "multi", "mastery": "5", "area": "30' radius", "alcance": "100'", "duracao": "Instantaneous", "descricao": "This spell is a creation of the Moshi family, and invokes both the fury of Fire and the wrathful aspect of Air to mimic the anger of the Moshi family’s patron Fortune, the Sun itself. When cast, it unleashes a blaze of searing light and a concussive detonation of air directly above the target. All those within the area of effect suffer 5k3 Wounds (3k1 Wounds if they are resistant to heat) and are knocked Prone, Dazed, and considered Blinded; during the Reactions stage of each Round they can attempt to recover from the blindness by rolling Stamina at a TN equal to the caster’s Fire x5 (in addition to the normal roll to recover from Dazed). This spell is noted for being particularly effective against creatures of the Nothing, which suffer an additional 2k2 damage from its effects.", "tags": ["thunder", "Mantis", "Centipede"], "livro": "Book of Void (Livro do Vazio)", "pagina": "188"}, {"id": "stiffling_wind", "nome": "Stifling Wind", "elemento": "multi", "mastery": "3", "area": "20' radius", "alcance": "100'", "duracao": "5 Rounds", "descricao": "Devised by the Soshi to support their shinobi allies, this spell is a more sophisticated development of the original Earth and Air spell. It mingles the Earth and Air kami to create a thick, choking cloud that obscures vision and renders breathing difficult. All those within the area of effect are considered Blinded while they remain within the cloud and for one Round after they leave (as they must wipe the dirt out of their eyes before they can see again). Moreover, while they remain within the cloud, at the start of their Turn each Round they must roll Stamina at a TN equal to the caster’s Earth x5 - if the roll is failed, they can only take Free Actions that Round (due to being choked by dust).", "tags": ["Scorpion"], "livro": "Book of Void (Livro do Vazio)", "pagina": "188"}, {"id": "soul_sword", "nome": "Soul Sword", "elemento": "multi", "mastery": "5", "area": "self", "alcance": "self", "duracao": "10 rounds", "descricao": "One of the more powerful and complex multi-Element spells known, this Agasha spell is the ultimate expression of the Elemental Weapon spells, combining all four Elements to create a weapon of pure Elemental power. The weapon takes the form of a 5k4 katana and is wielded using the Kenjutsu Skill, but with a +2k2 bonus to attack rolls as the spirits within the blade guide it toward its foes. The Soul Sword is considered to have the properties of both Jade and Crystal for the purpose of who can be harmed by it, and it ignores all effects of enemy armor (both Armor TN and Reduction). If the wielder drops or otherwise loses the sword, the Air spirits within the blade fly it back into his hand as a Free Action.", "tags": ["craft", "Phoenix", "Dragon"], "livro": "Book of Void (Livro do Vazio)", "pagina": "189"}, {"id": "drown_the_spirit", "nome": "Drown the Spirit", "elemento": "multi", "mastery": "4", "area": "1 target creature", "alcance": "30'", "duracao": "3 Rounds", "descricao": "One of the very few Multi-Element spells known to use Void magic, this spell can only be cast by a Void shugenja. It was devised by the Isawa ishiken as a way of punishing or outright defeating powerful foes, and it works by using the Void to turn the target’s internal Air and Water kami against him. The spell is quite visually spectacular, with the caster gathering a visible ball of dark crackling energy in his hands and then sending it forth to strike and suffuse the target. The target of the spell has his Strength Rank reduced by an amount equal to the combined total of his Air and Water Rings for the duration of the spell. If this reduces his Strength Rank to zero, he is helplessly immobilized and cannot take Actions until the spell expires.", "tags": ["Phoenix"], "livro": "Book of Void (Livro do Vazio)", "pagina": "189"}, {"id": "purification_of_the_kami", "nome": "Purification of the Kami", "elemento": "water", "mastery": "1", "area": "Body of water up to 500 feet in radius", "alcance": "touch", "duracao": "permanent", "descricao": "This prayer invokes the purity and cleansing strength of the Water kami to purge flth and contamination from a body of water such as a pond, a moat, or some of a stream or river. The caster touches the water as part of the casting ritual, and the purifcation ripples out from that point in waves of glowing light. This spell renders all the water within the area of effect wholly pure and safe to drink, removing all dirt, disease, and toxins. (However, it cannot purge the Taint.) The purifcation is a one-off event and cannot prevent dirt or poison from returning to the water later. This spell can also be cast on water inside a single container (such as a bucket, barrel, or bottle). If the spell is cast on an alcoholic beverage (such as sake, shochu, or plum wine) it will purge the drink’s favor and alcohol content, leaving it as pure water.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "180"}, {"id": "the_swell_of_the_storm", "nome": "The Swell of the Storm", "elemento": "water", "mastery": "1", "area": "one target creature", "alcance": "25'", "duracao": "Instantaneous", "descricao": "This spell evokes a sudden blast of water that strikes with the heavy, irresistible power of the tide. The water is summoned into existence, fying out from the caster in a heavy mass and striking the target with gentle but nigh-irresistible power. The target must make a Contested Roll of his Strength against the caster’s Water – failure means Knockdown (the target is knocked Prone). The spell will also extinguish any open fames the targets are carrying (torches, lanterns, candles, etc). This spell can affect Huge creatures, although the GM may wish to award them a bonus on their Contested Roll to refect the greater diffculty of knocking down such large targets.", "tags": ["defense"], "livro": "Book of Water (Livro da Água)", "pagina": "180"}, {"id": "suitengus_curse", "nome": "Suitengu's Curse", "elemento": "water", "mastery": "1", "area": "one target creature", "alcance": "20'", "duracao": "10 Rounds", "descricao": "This prayer invokes Suitengu, the Fortune of the Sea, to drag down the target with the weight of his sullen wrath. The target feels a great weight on all his limbs, as though he is trying to swim in heavy seas. Mechanically, Suitengu’s hostility lower’s the target’s Refexes Rank by 1 and causes him to move as though his Water is 1 Rank lower for the duration of the spell.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "180"}, {"id": "strength_of_the_tsunami", "nome": "Strength of the Tsunami", "elemento": "water", "mastery": "2", "area": "caster", "alcance": "touch", "duracao": "3 Rounds", "descricao": "This spell calls on Water’s affnity to physical strength. The surge of Water kami through the body briefy enhances the muscles, allowing the targeted person to perform prodigious feats. For the duration of the spell, the target’s Strength Rank is increased by an amount equal to half the caster’s Water Ring (rounded down). This cannot raise the Strength Rank higher than 9.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "180"}, {"id": "surging_soul", "nome": "Surging Soul", "elemento": "water", "mastery": "2", "area": "one target person", "alcance": "10'", "duracao": "3 Rounds", "descricao": "In contrast to the more peaceful and healing aspects of Water, this prayer evokes the power of Water on the attack, unleashing a surge of chi through the target’s limbs to empower his strikes. However, the massive surge of Water kami through the body also makes it diffcult for the target to remain still. The recipient of this prayer enjoys a +1k1 bonus to all Attack rolls, but cannot enter or beneft from the Center Stance and must take at least one Move Action every Round for the duration of the spell. Surging Soul is greatly favored among war-shugenja such as the martial wing of the Kitsu, the Tamori, the Kuni, and the Iuchi, but fnds less acceptance in families like the Asahina and the Isawa.", "tags": ["battle"], "livro": "Book of Water (Livro da Água)", "pagina": "180"}, {"id": "yukis_touch", "nome": "Yuki's Touch", "elemento": "water", "mastery": "2", "area": "Body of water 100' radius from caster", "alcance": "touch", "duracao": "Instantaneous", "descricao": "This spell, named after the legendary spirit known as the Yuki no Onna, persuades the Water spirits in a stream, river, or lake to expel all Fire from their presence, causing the water to instantly freeze. A single natural body of water freezes solid out to a distance of 100’ from the caster. Although this has uses in combat, the most frequent employment of the spell is to allow travelers or soldiers to cross water barriers. Any persons or creatures within the water will be trapped, and if they are under the surface they will suffocate (treat as Drowning). Breaking free of the ice will require a Contested Roll of Strength against the caster’s Water. The ice will melt normally.", "tags": ["travel"], "livro": "Book of Water (Livro da Água)", "pagina": "181"}, {"id": "heavens_tears", "nome": "Heaven's Tears", "elemento": "water", "mastery": "2", "area": "30' radius around caster", "alcance": "centered on caster", "duracao": "2 Rounds", "descricao": "This prayer evokes the sorrow of the Heavens, unleashing a brief deluge of rain which is endowed with the spiritual purity of the Sun. The spell summons divine rain from the sky, and thus can only be used effectively outdoors – it cannot cause rain to fall indoors or underground. Those of pure soul (no Taint or Shadow corruption, Honor Rank 4.0 or better) who are bathed in Heaven’s Tears are healed each Round by a number of Wounds equal to the caster’s Water. Conversely, those with Taint or Shadow corruption suffer 1k1 Wounds for each Round they are exposed to the Tears.", "tags": ["crystal"], "livro": "Book of Water (Livro da Água)", "pagina": "181"}, {"id": "endless_deluge", "nome": "Endless Deluge", "elemento": "water", "mastery": "3", "area": "1 mile diameter", "alcance": "centered on caster", "duracao": "12 hours", "descricao": "This spell calls on the Water spirits in the sky to congregate and descend to the earth, unleashing a massive rainstorm. Casting this spell is a ritual requiring at least ten minutes; at the GM’s option, casting this spell in an especially dry region, or during a drought, may require more casting time or require Raises to succeed. Rainclouds gather while the spell is being cast, and once it is completed the clouds open up and rain begins pouring down, continuing without cease for many hours. The chief value of this spell is to extinguish fres (even large confagrations such as forest fres will be doused within a half hour or so) and to abate the effects of drought. However, the relentless pouring rain also obscures visibility and slickens objects, imposing a -1k0 penalty on all physical actions and a -2k0 penalty on ranged attacks. The rain also imposes a -1k1 penalty on Spell Casting Rolls for Fire spells within it, since the relentless water makes the Fire spirits reluctant to act. Finally, due to the large volume of rain over a short period of time, the spell can potentially cause fash-fooding (GM’s option).", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "181"}, {"id": "sanctuary_of_the_waves", "nome": "Sanctuary of the Waves", "elemento": "water", "mastery": "3", "area": "one target person", "alcance": "50'", "duracao": "10 Rounds", "descricao": "The sea is a thing of great destructive power, but also great mercy and salvation.” - Asako Chukage This spell calls on the power of Water to protect and hide the chosen targets (who must be willing, and can include the caster). The spell can only be cast within range of a large quantity of water in a natural environment – e.g. a pond, stream, or something larger. When the spell is cast, the water lunges out, scoops up the targets, and draws them into the water, concealing them beneath its surface. The targets have enough air to breathe for the duration of the spell, but no longer. The surrounding barrier of water completely protects the targets, but also completely blocks them from any sort of attack against those outside – indeed, they will not even be able to see what is happening above the water unless they can roll Perception at TN 20 to make out the blurry images. Once the spell’s duration expires, the water releases the targets where they are – they must swim to the surface on their own.>", "tags": ["defense"], "livro": "Book of Water (Livro da Água)", "pagina": "182"}, {"id": "the_inner_ocean", "nome": "The Inner Ocean", "elemento": "water", "mastery": "3", "area": "one willing person", "alcance": "50'", "duracao": "5 minutes", "descricao": "This spell evokes the target’s inner Water to the ultimate degree, strengthening it to the point where it completely overwhelms the target’s other Elements. The target – who may be the caster – is physically transformed into pure clear water, along with anything he might be wearing or carrying at the moment the spell is cast. This state persists until the spell expires, and while the target is water he cannot speak, attack, cast spells, or directly manipulate physical objects. However, he can move more quickly (performing Move Actions as though he has +1 Rank in his Water Ring), can indirectly manipulate objects by pushing against them, and can fow his liquid body through narrow openings. (The target’s physical mass does not change, so he cannot squeeze himself into a small box or otherwise evade the constraints of his size.) The target is effectively immune to most physical harm, but Fire spells can damage him, as can truly intense heat such as a burning castle or a lava fow. At the GM’s option, certain types of physical events – such as being scattered or partially soaked up with towels – might also harm the transformed person. Once the spell’s duration ends, the target’s Elements rebalance and he returns to normal.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "182"}, {"id": "typhoons_surge", "nome": "Typhoon's Surge", "elemento": "water", "mastery": "3", "area": "one or more target allies", "alcance": "50'", "duracao": "Instantaneous", "descricao": "This spell, sometimes called by the more mundane name “Renewed Energy,” is a variation on the more commonly used prayer Rejuvenating Vapors. The spell targets a number of allies within range up to the caster’s Water Rank (additional targets beyond the caster’s Water may be taken with Raises). All of the targets experience a sudden and powerful surge of energy as the spell foods them with invigorating chi. They are freed from the effects of the Fatigued and Dazed conditions, and each target heals a number of Wounds equal to the caster’s Water Rank.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "182"}, {"id": "steed_of_the_ebbing_tides", "nome": "Steed of the Ebbing Tides", "elemento": "water", "mastery": "4", "area": "one summoned steed", "alcance": "25'", "duracao": "4 hours", "descricao": "This prayer was originally developed by the Iuchi, although the Isawa have since devised a similar spell on their own. It summons forth a number of powerful kami, who take the physical form of a watery, translucent horse. The Steed will bear the caster (or one other person designated by the caster at the time the Steed is frst summoned) in the same manner of a normal horse, can be controlled with Horsemanship in the normal way, and will fght selfessly in its rider’s defense; for game purposes, the Steed is considered to have the same mechanical statistics as an Utaku Warhorse, but also has Reduction 15. It is untiring for as long as it remains in existence. Once the spell expires, the Steed collapses into normal water – which can be an unpleasant surprise if someone is still mounted on it.", "tags": ["travel"], "livro": "Book of Water (Livro da Água)", "pagina": "182"}, {"id": "master_of_the_rolling_river", "nome": "Master of the Rolling River", "elemento": "water", "mastery": "4", "area": "Up to 25 allies in one group", "alcance": "100'", "duracao": "5 minutes", "descricao": "This spell was originally devised by battle shugenja of the Kitsu and Iuchi families, and remains a favorite among them. It infuses a military unit with the fowing speed and relentless strength of Water, allowing the soldiers to move more quickly and strike more powerfully on the battlefeld. The caster chooses one group of allies (up to roughly a squadron) to receive this blessing; all troops in that unit may move as though their Water is 1 Rank higher and are considered to have a Strength 1 Rank higher for the duration of the spell. This spell normally only benefts samurai, but a skilled caster can extend to the blessing to cover other allies. Two Raises will allow the spell to affect non-samurai humans (e.g. ashigaru), while four Raises will allow it to affect non-human allies such as Naga or Ratlings. This spell may also be used to affect Mass Battle scenarios. Each casting of the spell during a Mass Battle awards a bonus equal to the caster’s Water Ring to the total of the commanding general’s next Battle Skill roll to determine winning or losing.", "tags": ["battle"], "livro": "Book of Water (Livro da Água)", "pagina": "183"}, {"id": "seed_of_qanan", "nome": "Seed of Qanan", "elemento": "water", "mastery": "4", "area": "any two people", "alcance": "touch", "duracao": "5 rounds", "descricao": "A Unicorn secret spell based on gaijin magic, this spell uses the Water kami’s control over internal energy to briefy create a temporary connection between two people, merging their chi and allowing them to call on each others’ knowledge and skill. The targets must be touched simultaneously by the caster to establish the initial link of Water kami, and must remain within 50’ of each other for the link to continue functioning – if this distance is exceeded, the spell immediately ends. In game terms, the linked people are able to use each others’ Skills, employing whichever Skill Rank is higher for a given task. However, they do not gain the benefts of Mastery Abilities.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "183"}, {"id": "the_emperors_road", "nome": "The Emperor's Road", "elemento": "water", "mastery": "4", "area": "One Imperial road up to ten miles in length", "alcance": "touch", "duracao": "8 hours", "descricao": "This spell was originally devised by the Seppun for the purpose of easing and supporting the Emperor’s journeys to and from the annual Imperial Winter Court. Since then the spell has been applied more widely, but is still quite rare outside of the Seppun family. The spell creates a powerful aura of friendly Water spirits along a specifc Imperial road, easing travel along its length. The road is cleared of all minor obstacles and irregularities (a major physical obstacle such as a fallen tree or a rockslide will not be affected), and the Water spirits cause honorable travelers who are loyal to the Emperor to move as though their Water is 2 Ranks higher so long as they remain on the road. Moreover, the blessing infuses these travelers and their mounts with the energy of Water, causing them not to become Fatigued due to travel so long as they remain on the road.", "tags": ["travel", "imperial"], "livro": "Book of Water (Livro da Água)", "pagina": "183"}, {"id": "within_the_waves", "nome": "Within the Waves", "elemento": "water", "mastery": "4", "area": "10' diameter sphere", "alcance": "self", "duracao": "one hour", "descricao": "This spell was originally devised by Isawa shugenja trying to locate the legendary undersea kingdom which was supposedly the home of Shiba’s wife. Although they never succeeded in that goal, the spell they created has seen considerable use in the centuries since. Within the Waves persuades the Water kami to hold themselves away from the caster in a spherical formation, thereby forming an air bubble around him. The caster can move the bubble by concentrating, allowing him to explore freely beneath the surface of a river, lake, or even the ocean. (Such movement is at the normal speed based on the caster’s Water.) Other persons can enter and leave the bubble by swimming, and a skilled caster can carry a few passengers along within the bubble’s center. When the spell’s duration expires, the Water kami push the bubble to the surface.", "tags": ["travel"], "livro": "Book of Water (Livro da Água)", "pagina": "183"}, {"id": "chi_reversal", "nome": "Chi Reversal", "elemento": "water", "mastery": "5", "area": "one target person/creature", "alcance": "20'", "duracao": "one hour", "descricao": "This prayer invokes Water’s connection to the fow of Chi through the body, taking control of that fow in order to alter the target’s balance of energy. One “pair” of the target’s mental and physical Traits from the same Element (chosen by the caster) have their Ranks fipped for the duration of the spell. Thus, if the caster chose to fip a target’s Fire Traits, an Intelligence of 2 and Agility of 4 would become an Intelligence of 4 and an Agility of 2 for the duration of the spell. The caster may Raise to affect additional pairs of Traits.", "tags": [], "livro": "Book of Water (Livro da Água)", "pagina": "184"}, {"id": "open_the_waves", "nome": "Open the Waves", "elemento": "water", "mastery": "5", "area": "Trench up to 30' wide and deep and 300' long", "alcance": "300'", "duracao": "15 minutes", "descricao": "This spell calls on the Water kami to hold themselves apart, creating a “trench” through a body of water to allow the passage of men, animals, or even wagons and war machines. The spell is employed primarily by martial shugenja who need to help their clan’s armies to cross river obstacles, but has also been used for more benign purposes, such as helping peasants to escape foods. The spell’s chief limitation is that it cannot always clear the water all the way to the bottom – there is only so much that can be asked of the kami.", "tags": ["Battle"], "livro": "Book of Water (Livro da Água)", "pagina": "184"}, {"id": "whirlpool", "nome": "Whirlpool", "elemento": "water", "mastery": "5", "area": "Whirlpool 200' in radius", "alcance": "1 mile", "duracao": "10 minutes", "descricao": "This prayer is a favorite among the Yoritomo, who are credited with frst creating it. It can only be cast near or on a large body of open water – a lake or sea. The spell excites the Water kami into a tremendous rage, causing them to create a huge and powerful whirlpool that will suck down any ships or swimmers in the vicinity. Any swimmer caught within the area of effect will be in danger of being sucked under, requiring a roll of Athletics (Swimming) / Strength at TN 30 each Round to avoid this. A ship within the area of effect will likewise be in danger, and the ship’s captain must roll Navigation / Intelligence at TN 30 every minute to keep the vessel from being sucked under. Once under water, all victims will be subject to Drowning, and can only reach the surface again by rolling Athletics (Swimming) / Strength at TN 40.", "tags": ["thunder"], "livro": "Book of Water (Livro da Água)", "pagina": "184"}, {"id": "opening_the_veil", "nome": "Opening the Veil", "elemento": "water", "mastery": "6", "area": "10'", "alcance": "One spirit portal", "duracao": "one hour", "descricao": "This prayer, a spell known only to the Kitsu and Isawa, invokes the Travel aspect of Water to open a temporary portal into the Spirit Realms. The spell can normally only access the realms of Meido or Chikushudo, but extremely powerful casters can sometimes access Yomi, Sakkaku, Toshigoku, Yume-do, or Gaki-do. The portal lasts only a short time, so passage through it is fraught with risk. Also, this spell cannot work in any area which has been warded against the infuences of the Spirit Realms (GM’s discretion).", "tags": ["Travel"], "livro": "Book of Water (Livro da Água)", "pagina": "184"}, {"id": "breath_of_mist", "nome": "Breath of Mist", "elemento": "water", "mastery": "6", "area": "a circular area 200' in radius", "alcance": "1/2 mile", "duracao": "30 minutes", "descricao": "This spell is especially popular among the more pacifstic types of shugenja, since it provides a way to avert a battle without actual violence. The spell evokes the full power of hundreds of Water kami to reduce the ground to a half-liquid mire while, at the same time, flling the air with water vapor to obscure vision. Entire armies have been rendered effectively helpless by this spell, unable to move or to strike out at their foes. In game terms, the spell turns all the ground within the area of effect into Diffcult terrain. The fog reduces normal visibility to 10’. Between 10’ and 30’, characters can discern vague outlines – this imposes a +15 TN penalty on any ranged attacks. Beyond 30’ all characters are effectively Blind.", "tags": ["defense"], "livro": "Book of Water (Livro da Água)", "pagina": "184"}, {"id": "maho_heart_of_the_damned", "nome": "[MAHO] Heart Of The Damned", "elemento": "earth", "mastery": "1", "area": "Caster", "alcance": "Touch", "duracao": "Instantaneous", "descricao": "A foul necromantic ritual, first practiced by Iuchiban himself, this spell calls on the strength of the dead to enhance the living. The caster must touch a recently-dead human corpse (dead within the last day) when casting the spell. The corpse shrivels and rots away as the caster draws on its essence, reddish-black energy flowing out of the dead body and into the caster. The caster heals 2k2 Wounds and regains 1 Rank in any Ring or Trait which has been reduced below its normal level.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_purge_the_weak", "nome": "[MAHO] Purge The Weak", "elemento": "earth", "mastery": "1", "area": "Food and water for up to 5 people", "alcance": "50 feet", "duracao": "Permanent", "descricao": "This unpleasant curse ruins food and drink, rendering it foul, diseased, and inedible. The effects of the spell are obvious - food becomes rotten, water turns foul and discolored, and so forth. The food and water lose all nutritional value and anyone who eats or drinks must roll Stamina at TN 20 or become severely ill, suffering a -3k0 penalty to all Skill, Trait, and Spell Casting rolls. The illness is incurable with medical treatment and will last for two weeks unless magically cured.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_suck_the_marrow", "nome": "[MAHO] Suck The Marrow", "elemento": "earth", "mastery": "1", "area": "One target creature", "alcance": "Touch", "duracao": "1 day", "descricao": "This unpleasant curse impedes the victim's ability to heal and recover from injury and sickness. The victim becomes pale and weak, exuding an unpleasant body odor, and is unable to heal Wounds normally or from applications of the Medicine skill. The victim also is unable to recover from illnesses or poisons, and suffers a -2k0 penalty to any roll made to resist the effects of a poison or disease. Magical healing can still affect the target normally.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_symbol_of_blood", "nome": "[MAHO] Symbol Of Blood", "elemento": "water", "mastery": "1", "area": "30 foot radius", "alcance": "Touch", "duracao": "12 hours", "descricao": "This spell inscribes a sinister ward onto a flat surface. The caster writes the ward in the blood he spill to cast the spell, and once inscribed the ward cannot be destroyed except by physically destroying the surface on which it is written. The ward causes its victims' blood to become sluggish and cold. Anyone other than the caster who enters the area of effect suffers a -2k0 penalty to all physical Actions. The effect only applies while they are within the area of effect, and does not stack with other Symbols of Blood.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_ward_of_divine_peace", "nome": "[MAHO] Ward of Divine Peace", "elemento": "air", "mastery": "1", "area": "50 foot radius", "alcance": "Touch", "duracao": "8 hours", "descricao": "This spell is favored by Bloodspeaker cell leaders, who use it to maintain psychological dominance over their followers. The spell's name is an ironic joke within the cult's ranks. The spell creates a false aura of calm and well-being that lasts for several hours. This makes it difficult for them to focus their attention or resist appeals from others. Anyone who is within the spell's area of effect, or who enters it while the spell is in effect, suffers a -1k0 penalty to all Skill and Trait rolls that use Awareness or Willpower. This penalty lasts until the end of the spell's duration, but does not stack with itself.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_curse_of_the_clan", "nome": "[MAHO] Curse Of The Clan", "elemento": "air", "mastery": "2", "area": "One target samurai", "alcance": "50 feet", "duracao": "1 month", "descricao": "This subtle curse causes a samurai to manifest his clan's most stereotypical and notorious behavior. For example, a Crab might become more crude, intolerant, and ruthlessly pragmatic, while a Phoenix might become more arrogant and obsessed with magical power. The changes are significant but not overwhelming, and the victim of the spell will try to rationalize and justify his behavior. If a PC is targeted with this spell the GM should present the situation as a role-playing challenge rather than dictating how the character is played.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_curse_of_the_kansen", "nome": "[MAHO] Curse Of The Kansen", "elemento": "air", "mastery": "2", "area": "One target creature", "alcance": "50 feet", "duracao": "8 hours", "descricao": "This curse subtly attracts hostile kansen to harass the target. The spell's victim begins hearing constant whispers inside his head, voices urging him to sinful and corrupt behavior. The continual distraction causes him to suffer a -1k0 penalty to all Courtier, Etiquette, and Sincerity rolls. If he is rolling to resist the Temptation Skill, the penalty is -2k0 instead. (This effect stacks with the maho spell Sinful Dreams.) If the optional Honor Roll rule is in effect, the victim of this spell also suffers a penalty of -1k0 to Honor Rolls.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_gift_of_the_maker", "nome": "[MAHO] Gift Of The Maker", "elemento": "fire", "mastery": "2", "area": "One target creature (can be the caster)", "alcance": "Self;Touch", "duracao": "1 hour", "descricao": "The caster summons the power of Jigoku, temporarily granting the blessings of the Taint. Most Bloodspeakers rationalize this spell's effects by claiming it is evoking power from within themselves. The caster (or another person touched by the caster) gains a Greater Shadowlands Power of his choice for the duration of the spell.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_dark_wings", "nome": "[MAHO] Dark Wings", "elemento": "water", "mastery": "2", "area": "Caster", "alcance": "Self", "duracao": "10 minutes", "descricao": "The caster sprouts monstrous wings from his back, resembling those of a bat or other such creature. For the duration of the spell the caster can fly, and is considered to have Swift 3 (as per the creature ability from the Book of Void, L5R 4th Edition core rulebook) while flying.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_dancing_with_demons", "nome": "[MAHO] Dancing With Demons", "elemento": "air", "mastery": "3", "area": "Self;one target creature", "alcance": "500 feet", "duracao": "24 hours", "descricao": "A ritual spell first used by the notorious Doji Nashiko, this spell is also employed by many other maho-tsukai, and has found its way into the repertoire of several Bloodspeaker Cult cells. The spell is a ritual and requires the caster to dance for at least an hour (rolling Perform: Dance / Awareness at TN 25) while casting - if the dance is interrupted or the Skill roll is unsuccessful, the spell fails. However, if the spell succeeds, the caster may choose either to gain a Physical or Mental Advantage for the duration of the spell, or inflict a Physical or Mental Disadvantage on another person within range for the duration of the spell. (The caster need not be able to see the target so long as he is within range.) The maximum Experience Point value of an Advantage or Disadvantage created by the spell is equal to the caster's Air + Insight Rank + Taint Rank, if any. This spell cannot make extreme physical changes to the target, such as removing limbs or organs (e.g. it cannot inflict Disadvantages like Missing Eye). The GM should exercise intelligent judgment in considering its effects.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_mists_of_fear", "nome": "[MAHO] Mists Of Fear", "elemento": "air", "mastery": "3", "area": "One target creature", "alcance": "50 feet", "duracao": "Instantaneous", "descricao": "This spell summons forth a potent illusion of whatever the target fears most in the world. The illusion is present for only a few moments and can only be perceived by the target, who must roll against a Fear 5 effect. If the target suffers from a Phobia the spell will also activate its effects.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_symbol_of_the_bloodspeaker", "nome": "[MAHO] Symbol Of The Bloodspeaker", "elemento": "air", "mastery": "3", "area": "50 foot radius", "alcance": "Touch", "duracao": "12 hours", "descricao": "The Bloodspeaker Cult uses this spell to protect their meeting places against unwanted intrusion. The symbol must be inscribed into a flat surface (wall, floor, etc) when it is cast. The moment anyone who is not a loyal member of the Bloodspeaker Cult enters the symbol's radius, the symbol glows a bright sickly green and the intruder is bathed in eerie green flames, inflicting 4k3 damage. The symbol can discharge any number of times against different targets, but each target can only be affected once within the duration of the spell.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_tomb_of_earth", "nome": "[MAHO] Tomb Of Earth", "elemento": "earth", "mastery": "4", "area": "One target creature", "alcance": "50 feet", "duracao": "Conditional (see below)", "descricao": "This spell is a perverse inversion of the elemental spell Tomb of Jade. Instead of targeting those with the Taint, it targets those who are pure of soul - the spell cannot affect anyone who has at least one full Rank of Taint. The victim of Tomb of Earth is held immobile as he begins turning to stone, beginning with the skin and working its way inward. Each Round (including the Round the spell is cast) on the caster's Turn, the caster makes an Opposed Roll of his Insight / Earth against the target's Insight / Air. If the caster wins, the target remains immobilized by the spell (unable to take Actions of any kind) and suffers 2k2 damage. If the target wins, the spell's effects end. If the target is killed by the spell, he is turned completely to stone, which crumbles to dust within 24 hours.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_burning_blood", "nome": "[MAHO] Burning Blood", "elemento": "fire", "mastery": "4", "area": "One target creature", "alcance": "50 feet", "duracao": "Instantaneous", "descricao": "This horrible spell infuses the target's bloodstream with angry Fire kansen, causing his blood to superheat and boil through his skin, emerging as a cloud of reddish vapor. The target suffers Wounds with a DR equal to his Fire, and must roll Willpower at TN 20 or fall Prone due to the unbearable pain. Whether or not the target falls prone, he is considered to be Fatigued on his next two Turns, due to the debilitating effect of the boiling blood.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_blood_armor", "nome": "[MAHO] Blood Armor", "elemento": "earth", "mastery": "5", "area": "Caster and one target creature", "alcance": "50 feet", "duracao": "3 Rounds", "descricao": "This is an extremely vicious defensive spell which high-ranking Bloodspeaker leaders frequently use to defend themselves. When the spell is cast, the maho-tsukai chooses one living target within range. For the duration of the spell, any time the caster suffers Wounds from any source, he only takes 25% of the damage rolled (rounded down). The target of the spell takes the other 75% (rounded up). Casting this spell does not produce any obvious visual effect, but each time the spell shifts damage to the target, the caster glows with unholy reddish-black energy, while appropriate injuries (burns, cuts, etc) spontaneously appear on the target. This spell works on all Wound damage, even from spells like Jade Strike that normally could not hurt the target.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_take_the_body", "nome": "[MAHO] Take The Body", "elemento": "air", "mastery": "6", "area": "Caster and one target person", "alcance": "500 feet", "duracao": "Permanent", "descricao": "This spell is, to the best of anyone's knowledge, known only to two people - Iuchiban and Yajinden. They have guarded its secrets carefully and so far no other maho-tsukai has ever exhibited its power. The spell allows the caster to literally “leap” his soul into the body of another person within range, instantly and permanently taking their body as his own. The caster must succeed in a Contested Willpower roll against the victim, and if the victim wins, the caster is hurled back into his current body. (The victim will be very much aware that he just fought off some kind of terrible all-consuming power.) The spell does not normally cause the souls to “switch”- the abandoned body simply falls dead. The fate of the original soul is unknown, and some Rokugani believe it may actually be destroyed, a truly horrific and blasphemous act. There are some reports of powerful Lost or maho-tsukai being able to switch into the other body rather than be destroyed, but these tales are not confirmed. The occupied body retains its physical Traits and physical Advantages and Disadvantages, but instantly acquires the mental Traits and Void of the caster, along with all of the caster's Skills and any Mental or Spiritual Advantages and Disadvantages the caster may have. (Social Advantages or Disadvantages may or may not persist - the GM should adjudicate such situations.) If the maho-tsukai remains within the same body for an extended period of time (six months or more) it will gradually change to physically resemble the caster's original physical form, changing Rings, Traits, and Advantages as appropriate.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_fierce_blood_of_the_earth", "nome": "[MAHO] Fierce Blood Of The Earth", "elemento": "earth", "mastery": "5", "area": "Caster", "alcance": "Touch", "duracao": "Instantaneous", "descricao": "A hideous and blasphemous spell that many Bloodspeakers use to artificially extend their lifespans. The caster touches one living being, who must be either willing or physically helpless (securely bound, asleep, or unconscious). The caster must make an Opposed Earth Roll against an unwilling victim. If the spell is successful, the maho-tsukai consumes the victim's life force, killing him instantly. In return, the caster heals all physical injuries, regrows any missing limbs or organs, and extends his life by one year. Although this spell has no obvious or immediate side-effects, using it repeatedly will have a price - the maho-tsukai will acquire a desiccated, almost mummified appearance, making his true nature increasingly difficult to conceal.", "tags": ["maho"], "livro": "Enemies of the Empire", "pagina": ""}, {"id": "maho_eternal_unrest", "nome": "[MAHO] Eternal Unrest", "elemento": "earth", "mastery": "2", "area": "Target corpse", "alcance": "Touch", "duracao": "1 month", "descricao": "The Great Clans, page 283. As masters of necromancy, the Chuda often find themselves in need of corpses for their spells and techniques. This ritual is designed to ensure such corpses are always available, regardless of circumstances. It normally requires one hour to complete, although it can be shortened (with Raises) to a minimum of ten minutes. You may target a maximum number of corpses equal to your Taint Rank. At the spell’s conclusion the targeted corpses are prepared for use. At any later time within the spell’s duration you may take a Complex Action and expend an Earth spell slot to instantly summon the prepared corpses to your location. Chuda Necromancers are particularly fond of using this spell to summon forth corpses for use with their insidious Technique.", "tags": ["maho", "nothing"], "livro": "Great Clans (Grandes Clãs)", "pagina": "283"}], "armas": [{"id": "shinai", "nome": "Shinai", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "0k1", "efeitos": ["no_dr_explosion"]}, {"id": "bokken", "nome": "Bokken", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "0k2", "custo": "5k", "efeitos": ["dbl_opp_armor_rule"]}, {"id": "blade_of_secrets_katana", "nome": "Blade of Secrets (Katana)", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai", "nemuranai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "3k2", "efeitos": ["blade_of_secrets"]}, {"id": "blade_of_truths_katana", "nome": "Blade of Truths (Katana)", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai", "nemuranai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "3k2", "efeitos": ["blade_of_truths"]}, {"id": "yashin_bloodsword_ambition_wakizashi", "nome": "Yashin- Bloodsword Ambition (Wakizashi)", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai", "ranged", "nemuranai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "3k3", "alcance": "20'", "efeitos": ["bloodsword_ambition"]}, {"id": "handan_bloodsword_judgement_katana", "nome": "Handan- Bloodsword Judgement (Katana)", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai", "nemuranai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "4k4", "efeitos": ["bloodsword_judgement"]}, {"id": "jonetsu_bloodsword_passion_katana", "nome": "Jonetsu- Bloodsword Passion (Katana)", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai", "nemuranai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "4k4", "efeitos": ["bloodsword_passion"]}, {"id": "fukushu_bloodsword_revenge_katana", "nome": "Fukushu- Bloodsword Revenge (Katana)", "pericia": "kenjutsu", "tags": ["medium", "melee", "samurai", "nemuranai"], "livro": "Book of Fire (Livro do Fogo)", "dr": "4k4", "efeitos": ["bloodsword_revenge"]}, {"id": "dragon_beard_hook", "nome": "Dragon Beard Hook", "pericia": "chain_weapons", "tags": ["large", "melee"], "livro": "Book of Water (Livro da Água)", "dr": "1k2", "custo": "4k", "efeitos": ["dragon_beard_hook_rule"]}, {"id": "rope_dart", "nome": "Rope Dart", "pericia": "chain_weapons", "tags": ["large", "ninja", "melee"], "livro": "Book of Water (Livro da Água)", "dr": "1k1", "custo": "5b", "efeitos": ["rope_dart_rule"]}, {"id": "three_section_staff", "nome": "Three Section Staff", "pericia": "staves", "tags": ["large", "monk", "ninja", "melee"], "livro": "Book of Water (Livro da Água)", "dr": "2k2", "custo": "1k"}, {"id": "pitchfork", "nome": "Pitchfork", "pericia": "staves", "tags": ["large", "peasant", "melee"], "livro": "Book of Water (Livro da Água)", "dr": "1k2", "custo": "3b", "efeitos": ["pitchfork_rule"]}, {"id": "torch", "nome": "Torch", "pericia": "jiujutsu", "tags": ["improvised", "peasant", "melee"], "livro": "Book of Water (Livro da Água)", "dr": "0k1", "custo": "1b", "efeitos": ["torch_rule"]}, {"id": "yobanjin_ring_sword", "nome": "Espada-anel yobanjin", "pericia": "swordsmanship_ring_sword", "tags": ["medium", "melee", "gaijin"], "livro": "The Imperial Archives", "dr": "2k2", "custo": "10k"}, {"id": "crossbow_oyumi", "nome": "Besta (oyumi)", "pericia": "crossbow", "tags": ["medium", "ranged", "peasant"], "livro": "The Imperial Archives", "dr": "4k2", "alcance": "150'", "custo": "5k", "efeitos": ["crossbow_reload_rule"]}], "skills": [{"id": "craft_meishodo", "nome": "Craft (Meishodo)", "traco": "varies", "tipo": "merchant", "livro": "Great Clans (Grandes Clãs)"}, {"id": "swordsmanship_ring_sword", "nome": "Swordsmanship (Ring-Sword)", "traco": "agility", "tipo": "bugei", "livro": "The Imperial Archives"}, {"id": "crossbow", "nome": "Crossbow", "traco": "agility", "tipo": "low", "livro": "The Imperial Archives"}, {"id": "craft_maskmaking", "nome": "Craft (Maskmaking)", "traco": "varies", "tipo": "high", "livro": "The Imperial Archives"}, {"id": "lore_shourido", "nome": "Lore (Shourido)", "traco": "intelligence", "tipo": "high", "livro": "The Imperial Archives"}, {"id": "perform_poetry", "nome": "Perform (Poetry)", "traco": "awareness", "tipo": "high", "livro": "Strongholds of the Empire"}]};
L5R4E.kitsSup={"order_of_the_wind": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "winds_grace_order": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "fukurokujins_eyes": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "order_of_the_nameless_gift": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "temple_of_persistence": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "order_of_eternity": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "peasant_koga_ninja": {"itens": ["Roupas de camponês", "Roupas escuras", "Três armas ninja à escolha", "Mochila de viagem"], "koku": 0, "bu": 0, "zeni": 5, "armas": ["tanto"]}, "ronin_void_mystic": {"itens": ["Roupas resistentes", "Uma arma à escolha", "Mochila de viagem"], "koku": 5, "bu": 0, "zeni": 0, "armas": ["wakizashi"]}, "monks_order_of_jurojins_blessing": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "monks_the_shrine_of_heavens_mirror": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "monks_shinmaki_order": {"itens": ["Bō (ou um par de jō)", "Roupas de viagem simples e ásperas", "Bolsa de pergaminhos com passagens do Tao"], "koku": 0, "bu": 0, "zeni": 2}, "yobanjin_warrior": {"itens": ["Roupas yobanjin", "Espada-anel yobanjin", "Besta (oyumi)", "Bolsa de couro"], "koku": 0, "bu": 0, "zeni": 0, "armadura": "light_armor"}, "yobanjin_shaman_shugenja": {"itens": ["Roupas yobanjin", "Bolsa de couro"], "koku": 0, "bu": 0, "zeni": 0, "armas": ["tanto"]}};
L5R4E.efeitosSup={"no_dr_explosion": "Damage dice cannot explode", "blade_of_secrets": "Raises do not increase the TN but still grant effect. Each time the wielder does this, the sword drains a Void Point. If the wielder has no Void Points left, the sword instead drains a Rank of Earth instead, eventually resulting in death if the wielder continues. The wielder will not realize the drain until he begins to feel a physical effect. May harm Invulnerable creatures. The wielder must roll a Willpower Roll at TN 30 in order to voluntarily give up the sword.", "blade_of_truths": "Damage dice explode on 9's and 10's but anytime the wielder rolls two or more explosions on the same damage roll, the blade's curse is activated. Thereafter, any opponent of the sword's wielder will get a +1k1 bonus to any damage roll against the wielder until the wielder dies or until he abandons the sword for at least a year. May harm Invulnerable creatures. The wielder must roll a Willpower Roll at TN 30 in order to voluntarily give up the sword.", "bloodsword_ambition": "Each kill \"banks\" a Free Raise for use at some later time. Continual +2k2 bonus to Sincerity (Deceit) and Stealth Skill Rolls. Must succeed a Willpower Roll against TN 25 or attack, when in the presence of someone who lower Glory but higher Status than the wielder. May harm any foe, regardless of imunities (including Oracles and Dark Oracles).", "bloodsword_judgement": "Each kill \"banks\" a Free Raise for use at some later time. Continual +2k0 bonus to all Attack Rolls with Handan Wielder may roll Perception Roll at TN 20 to discern others' Honor Rank. Sometimes, Handan will lie and tell the wielder the target's Honor Rank is 1.0, regardless of their true Rank. Any time the wielder believes someone has wronged him or failed to live up to the COde of Bushido, the wielder must make a Willpower Roll at TN 25 or attack. May harm any foe, regardless of imunities (including Oracles and Dark Oracles).", "bloodsword_passion": "Each kill \"banks\" a Free Raise for use at some later time. Continual +1k0 bonus to all Kenjutsu Rolls Wielder must make a Willpower Roll at TN 25 or attack any individual that comes between the wielder and something he desires. May harm any foe, regardless of imunities (including Oracles and Dark Oracles).", "bloodsword_revenge": "Each kill \"banks\" a Free Raise for use at some later time. Wielder gains Combat Reflexes and Quick Advantages. Continual +3k0 bonus to all Kenjutsu Rolls with Fukushu. Wielder must make a Willpower Roll at TN 25 or attack any individual that slights or obstructs the wielder. May harm any foe, regardless of imunities (including Oracles and Dark Oracles).", "dragon_beard_hook_rule": "The dragon beard hook may be used to initiate and maintain a grapple at a distance of up to 30 feet.", "rope_dart_rule": "Rope darts may be used to initiate and maintain a grapple at a distance of up to 15 feet.", "pitchfork_rule": "If a pitchfork inflicts more than 20 Wounds with a single attack, it breaks.", "torch_rule": "Enemies hit with a torch must roll Reflexes at TN 10 to avoid catching on fire. Foes who are set on fire take 1k1 fire damage during the Reactions Stage of each Round until they extinguish the fire (such as by jumping into water, or taking a Complex Action to smother the flames).", "crossbow_reload_rule": "Reloading a crossbow requires two Complex Actions (reduced to one Complex Action at Crossbow Skill Rank 5). A crossbow relies on its own mechanical force to deliver damage, and thus does not add the wielder's Strength to its DR. A loaded crossbow can be fired one-handed."};
(function(){const S=L5R4E.suplementos;if(!S)return;
  for(const k in S){const arr=L5R4E[k]||(L5R4E[k]=[]);S[k].forEach(x=>arr.push(x));}
  Object.assign(L5R4E.kits||(L5R4E.kits={}),L5R4E.kitsSup||{});Object.assign(L5R4E.efeitosEquip||(L5R4E.efeitosEquip={}),L5R4E.efeitosSup||{});})();
